-- V474: Seed 142 Class 11 Biology Mock Tests (104 Real-Format 70M Papers + 38 Chapter-Wise 25M Mocks)

DO $$
DECLARE
    v_class_id UUID;
BEGIN
    SELECT id INTO v_class_id FROM learn_exam_types WHERE slug IN ('class-11', 'cbse-class-11') LIMIT 1;
    IF v_class_id IS NULL THEN
        SELECT id INTO v_class_id FROM learn_exam_types WHERE name ILIKE '%Class 11%' LIMIT 1;
    END IF;

    IF v_class_id IS NOT NULL THEN
        DELETE FROM learn_test_questions WHERE mock_test_id IN (SELECT id FROM learn_mock_tests WHERE id::text LIKE '11030000-%');
        DELETE FROM learn_mock_tests WHERE id::text LIKE '11030000-%';

        ON CONFLICT (id) DO NOTHING;

Reason (R): Biological names are generally derived from Latin irrespective of their origin to ensure universal uniformity.
Choose the correct option:
A) Both A and R are true, and R is the correct explanation of A.
B) Both A and R are true, and R is not the correct explanation of A.
C) A is true but R is false.
D) A is false but R is true.', '{"A":"Both A and R are true, and R is the correct explanation of A","B":"Both A and R are true, and R is not the correct explanation of A","C":"A is true but R is false","D":"A is false but R is true"}'::jsonb, 'A', 'ASSERTION_REASON', 'Biology', 'The Living World', 1, 'Universal italic/underline convention identifies Latinised binomials.', NULL, NULL, 'Universal italic/underline convention identifies Latinised binomials.', 'EASY', true),
        ('11031111-0000-4000-8000-000000000007', 'Write four universal rules of Binomial Nomenclature.', NULL, NULL, 'VSA', 'Biology', 'The Living World', 2, '1. Latinised/italics; 2. Genus capitalised, species lowercase; 3. Underlined separately if handwritten; 4. Author abbreviation at end (Linn.).', '0.5M × 4', NULL, '1. Latinised/italics; 2. Genus capitalised, species lowercase; 3. Underlined separately if handwritten; 4. Author abbreviation at end (Linn.).', 'MEDIUM', true),
        ('11031111-0000-4000-8000-000000000008', 'Distinguish between Taxonomy and Systematics.', NULL, NULL, 'VSA', 'Biology', 'The Living World', 2, 'Taxonomy covers characterisation, identification, classification, and nomenclature; Systematics adds evolutionary/phylogenetic relationships among organisms.', '1M each', NULL, 'Taxonomy covers characterisation, identification, classification, and nomenclature; Systematics adds evolutionary/phylogenetic relationships among organisms.', 'MEDIUM', true),
        ('11031111-0000-4000-8000-000000000009', 'Write the complete taxonomic classification (Kingdom to Species) of (i) Man and (ii) Mango.', NULL, NULL, 'SA', 'Biology', 'The Living World', 3, 'Man: Animalia, Chordata, Mammalia, Primata, Hominidae, Homo, sapiens. Mango: Plantae, Angiospermae, Dicotyledonae, Sapindales, Anacardiaceae, Mangifera, indica.', '1.5M each', NULL, 'Man: Animalia, Chordata, Mammalia, Primata, Hominidae, Homo, sapiens. Mango: Plantae, Angiospermae, Dicotyledonae, Sapindales, Anacardiaceae, Mangifera, indica.', 'MEDIUM', true),
        ('11031111-0000-4000-8000-00000000000a', 'Define Herbarium and list three details recorded on a herbarium sheet label.', NULL, NULL, 'SA', 'Biology', 'The Living World', 3, 'Storehouse of dried, pressed, preserved plant specimens on sheets. Label carries: Date & place of collection, English/local/botanical names, Family, Collector''s name.', 'Definition (1.5M) + 3 label items (1.5M)', NULL, 'Storehouse of dried, pressed, preserved plant specimens on sheets. Label carries: Date & place of collection, English/local/botanical names, Family, Collector''s name.', 'MEDIUM', true),
        ('11031111-0000-4000-8000-00000000000b', 'Define Taxon and Taxonomic Hierarchy. Explain why classification of living organisms is indispensable in biology, citing all 7 taxonomic ranks with housefly (Musca domestica) and wheat (Triticum aestivum).', NULL, NULL, 'LA', 'Biology', 'The Living World', 5, 'Taxon = unit of classification at any rank. Hierarchy: Kingdom -> Phylum/Division -> Class -> Order -> Family -> Genus -> Species. Housefly (Muscidae, Diptera, Insecta, Arthropoda); Wheat (Poaceae, Poales, Monocotyledonae, Angiospermae). Helps rapid retrieval, evolutionary study, and universal identification.', 'Taxon & need (2M) + 7 ranks with 2 examples (3M)', NULL, 'Taxon = unit of classification at any rank. Hierarchy: Kingdom -> Phylum/Division -> Class -> Order -> Family -> Genus -> Species. Housefly (Muscidae, Diptera, Insecta, Arthropoda); Wheat (Poaceae, Poales, Monocotyledonae, Angiospermae). Helps rapid retrieval, evolutionary study, and universal identification.', 'HARD', true),
        ('11031111-0000-4000-8000-00000000000c', '(i) What is the basic unit of classification capable of interbreeding? (ii) Family of Lion, Tiger, Leopard (Panthera) and Cat (Felis)? (iii) Name India''s largest botanical garden in Shibpur, Howrah. (iv) Contrast "Growth" vs "Consciousness" as defining features of life.', NULL, NULL, 'CASE', 'Biology', 'The Living World', 4, '(i) Species. (ii) Felidae. (iii) Indian Botanical Garden, Howrah. (iv) Non-living mountains grow by external accretion so growth isn''t defining; self-consciousness/consciousness is defining.', '4 × 1M = 4M', 'A field taxonomist collects flowering plants across Western Ghats, pressing samples for reference libraries while sorting specimens from Family Felidae and Solanaceae.', '(i) Species. (ii) Felidae. (iii) Indian Botanical Garden, Howrah. (iv) Non-living mountains grow by external accretion so growth isn''t defining; self-consciousness/consciousness is defining.', 'HARD', true),
        ('11031111-0000-4000-8000-00000000000d', 'Five-Kingdom classification (1969) was proposed by:', '{"A":"Linnaeus","B":"R.H. Whittaker","C":"Carl Woese","D":"Bentham & Hooker"}'::jsonb, 'B', 'MCQ', 'Biology', 'Biological Classification', 1, 'Monera, Protista, Fungi, Plantae, Animalia based on cell, body, nutrition, phylogeny.', NULL, NULL, 'Monera, Protista, Fungi, Plantae, Animalia based on cell, body, nutrition, phylogeny.', 'EASY', true),
        ('11031111-0000-4000-8000-00000000000e', 'Which organisms lack a cell wall completely and are the smallest living cells surviving without oxygen?', '{"A":"Archaebacteria","B":"Mycoplasma","C":"Diatoms","D":"Slime moulds"}'::jsonb, 'B', 'MCQ', 'Biology', 'Biological Classification', 1, 'Mycoplasma (PPLO) are wall-less prokaryotes.', NULL, NULL, 'Mycoplasma (PPLO) are wall-less prokaryotes.', 'EASY', true),
        ('11031111-0000-4000-8000-00000000000f', 'Diatomaceous earth ("kieselguhr") used in polishing and syrup filtration consists of indestructible silica cell walls of:', '{"A":"Dinoflagellates","B":"Chrysophytes (Diatoms)","C":"Euglenoids","D":"Protozoans"}'::jsonb, 'B', 'MCQ', 'Biology', 'Biological Classification', 1, 'Soap-box-like silica frustules accumulate on ocean floors.', NULL, NULL, 'Soap-box-like silica frustules accumulate on ocean floors.', 'EASY', true),
        ('11031111-0000-4000-8000-000000000010', 'Who crystallised Tobacco Mosaic Virus (TMV) and showed viruses are largely protein?', '{"A":"D.J. Ivanowsky","B":"W.M. Stanley (1935)","C":"M.W. Beijerinck","D":"T.O. Diener"}'::jsonb, 'B', 'MCQ', 'Biology', 'Biological Classification', 1, 'Stanley crystallised TMV in 1935; Beijerinck coined "Contagium vivum fluidum".', NULL, NULL, 'Stanley crystallised TMV in 1935; Beijerinck coined "Contagium vivum fluidum".', 'EASY', true),
        ('11031111-0000-4000-8000-000000000011', 'Viroids discovered by T.O. Diener (1971) causing Potato Spindle Tuber disease consist of:', '{"A":"Protein coat only","B":"Free low-molecular-weight infectious RNA without protein capsid","C":"Double-stranded DNA","D":"Prion proteins"}'::jsonb, 'B', 'MCQ', 'Biology', 'Biological Classification', 1, 'Viroids lack protein coats unlike viruses.', NULL, NULL, 'Viroids lack protein coats unlike viruses.', 'EASY', true),
        ('11031111-0000-4000-8000-000000000012', 'Assertion (A): Lichens are reliable pollution indicators of SO₂ pollution.
Reason (R): The phycobiont (algal) and mycobiont (fungal) partners in lichens do not grow in SO₂-polluted industrial zones.
Choose the correct option:
A) Both A and R are true, and R is the correct explanation of A.
B) Both A and R are true, and R is not the correct explanation of A.
C) A is true but R is false.
D) A is false but R is true.', '{"A":"Both A and R are true, and R is the correct explanation of A","B":"Both A and R are true, and R is not the correct explanation of A","C":"A is true but R is false","D":"A is false but R is true"}'::jsonb, 'A', 'ASSERTION_REASON', 'Biology', 'Biological Classification', 1, 'SO₂ kills sensitive algal symbionts rapidly.', NULL, NULL, 'SO₂ kills sensitive algal symbionts rapidly.', 'EASY', true),
        ('11031111-0000-4000-8000-000000000013', 'What is "Red Tide" and which protists cause it?', NULL, NULL, 'VSA', 'Biology', 'Biological Classification', 2, 'Rapid multiplication of red dinoflagellates like Gonyaulax makes sea water appear red and releases toxins fatal to marine fish.', 'Organism (1M) + Toxin effect (1M)', NULL, 'Rapid multiplication of red dinoflagellates like Gonyaulax makes sea water appear red and releases toxins fatal to marine fish.', 'MEDIUM', true),
        ('11031111-0000-4000-8000-000000000014', 'Distinguish between Viruses, Viroids, and Prions (infectious agent type).', NULL, NULL, 'VSA', 'Biology', 'Biological Classification', 2, 'Viruses: nucleic acid (DNA or RNA) + protein capsid. Viroids: free infectious RNA only. Prions: abnormally folded infectious proteins (cause BSE/mad cow, CJD).', '2M', NULL, 'Viruses: nucleic acid (DNA or RNA) + protein capsid. Viroids: free infectious RNA only. Prions: abnormally folded infectious proteins (cause BSE/mad cow, CJD).', 'MEDIUM', true),
        ('11031111-0000-4000-8000-000000000015', 'Describe the three groups of Archaebacteria and the extreme habitats they survive in due to special cell wall lipids.', NULL, NULL, 'SA', 'Biology', 'Biological Classification', 3, 'Halophiles (extreme salty areas), Thermoacidophiles (hot sulphur springs), Methanogens (marshy areas & ruminant gut producing biogas methane). Branched ether-linked membrane lipids confer tolerance.', '3 × 1M', NULL, 'Halophiles (extreme salty areas), Thermoacidophiles (hot sulphur springs), Methanogens (marshy areas & ruminant gut producing biogas methane). Branched ether-linked membrane lipids confer tolerance.', 'MEDIUM', true),
        ('11031111-0000-4000-8000-000000000016', 'Explain the three steps of sexual cycle in Fungi: Plasmogamy, Karyogamy, and Meiosis, noting "Dikaryophase" in Ascomycetes and Basidiomycetes.', NULL, NULL, 'SA', 'Biology', 'Biological Classification', 3, 'Plasmogamy (fusion of protoplasms) -> delayed nuclear fusion forms n+n dikaryon phase -> Karyogamy (2n) -> Meiosis in fruiting body producing haploid spores.', '3 steps + dikaryon (3M)', NULL, 'Plasmogamy (fusion of protoplasms) -> delayed nuclear fusion forms n+n dikaryon phase -> Karyogamy (2n) -> Meiosis in fruiting body producing haploid spores.', 'MEDIUM', true),
        ('11031111-0000-4000-8000-000000000017', 'Compare the four major classes of Kingdom Fungi — Phycomycetes, Ascomycetes, Basidiomycetes, and Deuteromycetes — on mycelium structure, asexual spores, sexual fruiting bodies, and one example each.', NULL, NULL, 'LA', 'Biology', 'Biological Classification', 5, 'Phycomycetes (aseptate coenocytic; zoospores/aplanospores; Mucor/Rhizopus). Ascomycetes (septate branched; conidia; ascocarps/ascospores; Penicillium/Neurospora/Yeast). Basidiomycetes (septate; basidiospores exogenously on basidia; Agaricus/Ustilago/Puccinia). Deuteromycetes ("fungi imperfecti" asexual only; Alternaria/Trichoderma).', '4 classes × 1.25M = 5M', NULL, 'Phycomycetes (aseptate coenocytic; zoospores/aplanospores; Mucor/Rhizopus). Ascomycetes (septate branched; conidia; ascocarps/ascospores; Penicillium/Neurospora/Yeast). Basidiomycetes (septate; basidiospores exogenously on basidia; Agaricus/Ustilago/Puccinia). Deuteromycetes ("fungi imperfecti" asexual only; Alternaria/Trichoderma).', 'HARD', true),
        ('11031111-0000-4000-8000-000000000018', '(i) Name the two symbiotic partners in Lichens and their roles. (ii) Which blue-green algae fix atmospheric nitrogen in specialised heterocysts? (iii) Why did Whittaker remove Chlamydomonas and Chlorella from Plantae into Protista? (iv) Name a fungus extensively used in biochemical and genetic work.', NULL, NULL, 'CASE', 'Biology', 'Biological Classification', 4, '(i) Phycobiont (algae: photosynthesis) & Mycobiont (fungi: shelter, water & mineral absorption). (ii) Nostoc and Anabaena. (iii) Both are unicellular eukaryotic organisms. (iv) Neurospora (and Saccharomyces/yeast).', '4 × 1M = 4M', 'While surveying mountain bark and freshwater blooms, microbiologists classify autotrophic unicells, nitrogen-fixing filaments, and symbiotic crustose growths across kingdoms.', '(i) Phycobiont (algae: photosynthesis) & Mycobiont (fungi: shelter, water & mineral absorption). (ii) Nostoc and Anabaena. (iii) Both are unicellular eukaryotic organisms. (iv) Neurospora (and Saccharomyces/yeast).', 'HARD', true),
        ('11031111-0000-4000-8000-000000000019', 'Agar, widely used to grow microbes and solidify ice-creams/jellies, is obtained commercially from red algae:', '{"A":"Laminaria and Sargassum","B":"Gelidium and Gracilaria","C":"Spirogyra and Volvox","D":"Chlorella"}'::jsonb, 'B', 'MCQ', 'Biology', 'Plant Kingdom', 1, 'Gelidium and Gracilaria yield commercial agar.', NULL, NULL, 'Gelidium and Gracilaria yield commercial agar.', 'EASY', true),
        ('11031111-0000-4000-8000-00000000001a', 'Why are Bryophytes called "amphibians of the plant kingdom"?', '{"A":"They live in deserts","B":"They live on damp soil yet require external water for antherozoids to reach archegonia","C":"They lack chlorophyll","D":"They have seeds"}'::jsonb, 'B', 'MCQ', 'Biology', 'Plant Kingdom', 1, 'Flagellated antherozoids need water film for sexual reproduction.', NULL, NULL, 'Flagellated antherozoids need water film for sexual reproduction.', 'EASY', true),
        ('11031111-0000-4000-8000-00000000001b', 'Double fertilisation (syngamy + triple fusion forming triploid PEN) is a unique hallmark of:', '{"A":"Gymnosperms","B":"Angiosperms","C":"Pteridophytes","D":"Bryophytes"}'::jsonb, 'B', 'MCQ', 'Biology', 'Plant Kingdom', 1, 'Two male gametes fuse with egg (2n zygote) and polar nuclei (3n PEN).', NULL, NULL, 'Two male gametes fuse with egg (2n zygote) and polar nuclei (3n PEN).', 'EASY', true),
        ('11031111-0000-4000-8000-00000000001c', 'Peat moss used as fuel and packing material for trans-shipment of living plants due to high water-holding capacity is:', '{"A":"Funaria","B":"Sphagnum","C":"Marchantia","D":"Polytrichum"}'::jsonb, 'B', 'MCQ', 'Biology', 'Plant Kingdom', 1, 'Sphagnum absorbs water many times its dry weight.', NULL, NULL, 'Sphagnum absorbs water many times its dry weight.', 'EASY', true),
        ('11031111-0000-4000-8000-00000000001d', 'In Gymnosperms like Pinus and Cycas, the seeds remain naked because:', '{"A":"Ovules are NOT enclosed inside an ovary wall before or after fertilisation","B":"Flowers are microscopic","C":"Leaves are needle-like","D":"No xylem exists"}'::jsonb, 'A', 'MCQ', 'Biology', 'Plant Kingdom', 1, 'Gymnos = naked, sperma = seed.', NULL, NULL, 'Gymnos = naked, sperma = seed.', 'EASY', true),
        ('11031111-0000-4000-8000-00000000001e', 'Assertion (A): In Pteridophytes (Selaginella, Salvinia), heterospory is viewed as a key evolutionary precursor to the seed habit.
Reason (R): Female gametophyte is retained on the parent sporophyte for variable periods where the zygote develops into a young embryo.
Choose the correct option:
A) Both A and R are true, and R is the correct explanation of A.
B) Both A and R are true, and R is not the correct explanation of A.
C) A is true but R is false.
D) A is false but R is true.', '{"A":"Both A and R are true, and R is the correct explanation of A","B":"Both A and R are true, and R is not the correct explanation of A","C":"A is true but R is false","D":"A is false but R is true"}'::jsonb, 'A', 'ASSERTION_REASON', 'Biology', 'Plant Kingdom', 1, 'Microspore + megaspore retention paved the way for seed plants.', NULL, NULL, 'Microspore + megaspore retention paved the way for seed plants.', 'EASY', true),
        ('11031111-0000-4000-8000-00000000001f', 'Distinguish between Isogamous, Anisogamous, and Oogamous sexual reproduction in Algae with examples.', NULL, NULL, 'VSA', 'Biology', 'Plant Kingdom', 2, 'Isogamous: similar gametes (Ulothrix/Spirogyra); Anisogamous: dissimilar motile gametes (Eudorina); Oogamous: large non-motile egg + small motile male gamete (Volvox, Fucus).', '2M', NULL, 'Isogamous: similar gametes (Ulothrix/Spirogyra); Anisogamous: dissimilar motile gametes (Eudorina); Oogamous: large non-motile egg + small motile male gamete (Volvox, Fucus).', 'MEDIUM', true),
        ('11031111-0000-4000-8000-000000000020', 'Name the algal pigments and stored food characteristic of Chlorophyceae, Phaeophyceae, and Rhodophyceae.', NULL, NULL, 'VSA', 'Biology', 'Plant Kingdom', 2, 'Green (Chl a,b; Starch), Brown (Chl a,c + fucoxanthin; Laminarin/Mannitol), Red (Chl a,d + r-phycoerythrin; Floridean starch).', '2M', NULL, 'Green (Chl a,b; Starch), Brown (Chl a,c + fucoxanthin; Laminarin/Mannitol), Red (Chl a,d + r-phycoerythrin; Floridean starch).', 'MEDIUM', true),
        ('11031111-0000-4000-8000-000000000021', 'Explain three anatomical adaptations enabling Gymnosperm conifers (Pinus) to tolerate extreme temperature, humidity, and wind.', NULL, NULL, 'SA', 'Biology', 'Plant Kingdom', 3, '(1) Needle-like leaves reduce surface area. (2) Thick cuticle and sunken stomata minimise transpiration loss. (3) Mycorrhizal fungal root association aids mineral/water uptake.', '3 × 1M', NULL, '(1) Needle-like leaves reduce surface area. (2) Thick cuticle and sunken stomata minimise transpiration loss. (3) Mycorrhizal fungal root association aids mineral/water uptake.', 'MEDIUM', true),
        ('11031111-0000-4000-8000-000000000022', 'Compare Liverworts (Marchantia) and Mosses (Funaria) in Bryophytes on plant body, asexual gemmae, and protonema stage.', NULL, NULL, 'SA', 'Biology', 'Plant Kingdom', 3, 'Liverworts: dorsiventral thalloid body, asexual cup-shaped gemmae. Mosses: upright leafy gametophyte arising via creeping green filamentous protonema -> leafy stage.', '1.5M each', NULL, 'Liverworts: dorsiventral thalloid body, asexual cup-shaped gemmae. Mosses: upright leafy gametophyte arising via creeping green filamentous protonema -> leafy stage.', 'MEDIUM', true),
        ('11031111-0000-4000-8000-000000000023', 'Trace the complete life cycle pattern and dominant phases in Bryophytes, Pteridophytes, and Gymnosperms/Angiosperms (Haplontic, Diplontic, and Haplo-diplontic life cycles with examples).', NULL, NULL, 'LA', 'Biology', 'Plant Kingdom', 5, 'Haplontic (Volvox, Spirogyra, Chlamydomonas — dominant gametophyte n, zygotic meiosis); Diplontic (Fucus, Gymnosperms, Angiosperms — dominant sporophyte 2n); Haplo-diplontic (Bryophytes dominant n gametophyte + short 2n sporophyte; Pteridophytes & Ectocarpus/Kelps dominant 2n sporophyte + short free n gametophyte).', '3 life-cycle types + examples (5M)', NULL, 'Haplontic (Volvox, Spirogyra, Chlamydomonas — dominant gametophyte n, zygotic meiosis); Diplontic (Fucus, Gymnosperms, Angiosperms — dominant sporophyte 2n); Haplo-diplontic (Bryophytes dominant n gametophyte + short 2n sporophyte; Pteridophytes & Ectocarpus/Kelps dominant 2n sporophyte + short free n gametophyte).', 'HARD', true),
        ('11031111-0000-4000-8000-000000000024', '(i) Name the two classes of Pteridophytes exemplified by Selaginella and Pteris. (ii) What are prothallus and strobili/cones? (iii) Why are pteridophytes restricted to cool, damp, shady places? (iv) Name the tallest gymnosperm tree species.', NULL, NULL, 'CASE', 'Biology', 'Plant Kingdom', 4, '(i) Lycopsida (Selaginella) and Pteropsida (Pteris). (ii) Prothallus: inconspicuous free-living photosynthetic gametophyte; Strobili: compact cone of sporophylls. (iii) Need water for fertilisation & specific microclimate for prothallus. (iv) Giant redwood Sequoia.', '4 × 1M = 4M', 'Walking along moist Himalayan stream banks, botanists find liverwort gemma cups, feathery fern fronds bearing sori undersides, and towering needle-leaved conifers.', '(i) Lycopsida (Selaginella) and Pteropsida (Pteris). (ii) Prothallus: inconspicuous free-living photosynthetic gametophyte; Strobili: compact cone of sporophylls. (iii) Need water for fertilisation & specific microclimate for prothallus. (iv) Giant redwood Sequoia.', 'HARD', true),
        ('11031111-0000-4000-8000-000000000025', 'Water canal system with ostia, spongocoel, osculum, and flagellated choanocytes is unique to Phylum:', '{"A":"Coelenterata","B":"Porifera","C":"Ctenophora","D":"Echinodermata"}'::jsonb, 'B', 'MCQ', 'Biology', 'Animal Kingdom', 1, 'Choanocytes line spongocoel and canals in sponges.', NULL, NULL, 'Choanocytes line spongocoel and canals in sponges.', 'EASY', true),
        ('11031111-0000-4000-8000-000000000026', 'Bioluminescence and eight external ciliated comb plates are hallmarks of:', '{"A":"Platyhelminthes","B":"Ctenophora (Sea walnuts / Comb jellies)","C":"Mollusca","D":"Annelida"}'::jsonb, 'B', 'MCQ', 'Biology', 'Animal Kingdom', 1, 'Ctenophores swim using 8 ciliated comb plates.', NULL, NULL, 'Ctenophores swim using 8 ciliated comb plates.', 'EASY', true),
        ('11031111-0000-4000-8000-000000000027', 'Flame cells (solenocytes) serve osmoregulation and excretion in:', '{"A":"Annelids","B":"Platyhelminthes (Flatworms)","C":"Arthropods","D":"Molluscs"}'::jsonb, 'B', 'MCQ', 'Biology', 'Animal Kingdom', 1, 'Platyhelminthes use flame cells; Annelids use nephridia; Arthropods Malpighian tubules.', NULL, NULL, 'Platyhelminthes use flame cells; Annelids use nephridia; Arthropods Malpighian tubules.', 'EASY', true),
        ('11031111-0000-4000-8000-000000000028', 'Radula (file-like rasping organ for feeding) and calcareous shell over mantle belong to Phylum:', '{"A":"Arthropoda","B":"Mollusca","C":"Echinodermata","D":"Hemichordata"}'::jsonb, 'B', 'MCQ', 'Biology', 'Animal Kingdom', 1, 'Second largest animal phylum Mollusca.', NULL, NULL, 'Second largest animal phylum Mollusca.', 'EASY', true),
        ('11031111-0000-4000-8000-000000000029', 'Which mammal is oviparous (egg-laying)?', '{"A":"Macropus (Kangaroo)","B":"Ornithorhynchus (Platypus)","C":"Pteropus (Flying fox)","D":"Balaenoptera (Blue whale)"}'::jsonb, 'B', 'MCQ', 'Biology', 'Animal Kingdom', 1, 'Platypus is a primitive egg-laying monotreme.', NULL, NULL, 'Platypus is a primitive egg-laying monotreme.', 'EASY', true),
        ('11031111-0000-4000-8000-00000000002a', 'Assertion (A): Cyclostomes (Petromyzon/Lamprey) have a sucking circular mouth without jaws and migrate to freshwater for spawning.
Reason (R): After spawning within a few days they die, and their ammocoete larvae metamorphose back to ocean.
Choose the correct option:
A) Both A and R are true, and R is the correct explanation of A.
B) Both A and R are true, and R is not the correct explanation of A.
C) A is true but R is false.
D) A is false but R is true.', '{"A":"Both A and R are true, and R is the correct explanation of A","B":"Both A and R are true, and R is not the correct explanation of A","C":"A is true but R is false","D":"A is false but R is true"}'::jsonb, 'A', 'ASSERTION_REASON', 'Biology', 'Animal Kingdom', 1, 'Anadromous spawning behaviour of jawless vertebrates.', NULL, NULL, 'Anadromous spawning behaviour of jawless vertebrates.', 'EASY', true),
        ('11031111-0000-4000-8000-00000000002b', 'Distinguish between Diploblastic and Triploblastic organisation with one phylum example each.', NULL, NULL, 'VSA', 'Biology', 'Animal Kingdom', 2, 'Diploblastic: 2 germ layers (ectoderm + endoderm with mesoglea; Coelenterata/Ctenophora). Triploblastic: 3 germ layers including mesoderm (Platyhelminthes to Chordata).', '2M', NULL, 'Diploblastic: 2 germ layers (ectoderm + endoderm with mesoglea; Coelenterata/Ctenophora). Triploblastic: 3 germ layers including mesoderm (Platyhelminthes to Chordata).', 'MEDIUM', true),
        ('11031111-0000-4000-8000-00000000002c', 'State four flight adaptations in Class Aves (Birds).', NULL, NULL, 'VSA', 'Biology', 'Animal Kingdom', 2, 'Feathers, forelimbs modified into wings, pneumatic hollow bones with air cavities, crop & gizzard, and air sacs supplementing lungs.', '0.5M × 4', NULL, 'Feathers, forelimbs modified into wings, pneumatic hollow bones with air cavities, crop & gizzard, and air sacs supplementing lungs.', 'MEDIUM', true),
        ('11031111-0000-4000-8000-00000000002d', 'Compare Chondrichthyes (Cartilaginous fishes) and Osteichthyes (Bony fishes) on mouth position, operculum, air bladder, and scales.', NULL, NULL, 'SA', 'Biology', 'Animal Kingdom', 3, 'Chondrichthyes: ventral mouth, gill slits without operculum, no air bladder (must swim constantly), placoid scales (Scoliodon). Osteichthyes: terminal mouth, 4 gill pairs with operculum, air bladder for buoyancy, cycloid/ctenoid scales (Labeo/Catla).', '3 × 1M', NULL, 'Chondrichthyes: ventral mouth, gill slits without operculum, no air bladder (must swim constantly), placoid scales (Scoliodon). Osteichthyes: terminal mouth, 4 gill pairs with operculum, air bladder for buoyancy, cycloid/ctenoid scales (Labeo/Catla).', 'MEDIUM', true),
        ('11031111-0000-4000-8000-00000000002e', 'Explain Metameric segmentation, Closed circulatory system, and Parapodia in Phylum Annelida with example.', NULL, NULL, 'SA', 'Biology', 'Animal Kingdom', 3, 'True external & internal serial repetition (metamerism); closed vessels; lateral appendages parapodia in aquatic Nereis aid swimming (Earthworm/Hirudinaria).', '3M', NULL, 'True external & internal serial repetition (metamerism); closed vessels; lateral appendages parapodia in aquatic Nereis aid swimming (Earthworm/Hirudinaria).', 'MEDIUM', true),
        ('11031111-0000-4000-8000-00000000002f', 'List the three fundamental diagnostic characters of Phylum Chordata (Notochord, Dorsal hollow nerve cord, Paired pharyngeal gill slits) and compare Chordates vs Non-Chordates across five structural parameters. Mention the three Chordate subphyla with examples.', NULL, NULL, 'LA', 'Biology', 'Animal Kingdom', 5, '3 core features + 5 comparisons (CNS dorsal/hollow vs ventral/solid, heart ventral vs dorsal, post-anal tail present vs absent) + Urochordata (Ascidia), Cephalochordata (Branchiostoma), Vertebrata.', 'Core & 5 differences (3.5M) + 3 subphyla (1.5M)', NULL, '3 core features + 5 comparisons (CNS dorsal/hollow vs ventral/solid, heart ventral vs dorsal, post-anal tail present vs absent) + Urochordata (Ascidia), Cephalochordata (Branchiostoma), Vertebrata.', 'HARD', true),
        ('11031111-0000-4000-8000-000000000030', '(i) Distinguish true coelomates, pseudocoelomates, and acoelomates with one phylum each. (ii) Which phylum shows water vascular system aiding locomotion and food capture? (iii) Name the largest phylum featuring chitinous exoskeleton & jointed appendages. (iv) Identify the excretory organ of Hemichordata (Balanoglossus).', NULL, NULL, 'CASE', 'Biology', 'Animal Kingdom', 4, '(i) Coelomate (Annelida–Chordata), Pseudocoelomate (Aschelminthes), Acoelomate (Platyhelminthes). (ii) Echinodermata. (iii) Arthropoda. (iv) Proboscis gland.', '4 × 1M = 4M', 'In a marine zoology aquarium, students compare radial starfish, jointed lobsters, soft shelled cuttlefish, and lancelets along symmetry and body-cavity criteria.', '(i) Coelomate (Annelida–Chordata), Pseudocoelomate (Aschelminthes), Acoelomate (Platyhelminthes). (ii) Echinodermata. (iii) Arthropoda. (iv) Proboscis gland.', 'HARD', true),
        ('11031111-0000-4000-8000-000000000031', 'Pneumatophores (vertically upward breathing roots) occur in halophytic mangroves like:', '{"A":"Banyan","B":"Rhizophora growing in swampy marshes","C":"Sweet potato","D":"Maize"}'::jsonb, 'B', 'MCQ', 'Biology', 'Morphology of Flowering Plants', 1, 'Obtain O₂ for respiration from waterlogged mud.', NULL, NULL, 'Obtain O₂ for respiration from waterlogged mud.', 'EASY', true),
        ('11031111-0000-4000-8000-000000000032', 'In mustard, china rose, and brinjal, the flower is hypogynous meaning the ovary is:', '{"A":"Inferior","B":"Superior","C":"Half-inferior","D":"Absent"}'::jsonb, 'B', 'MCQ', 'Biology', 'Morphology of Flowering Plants', 1, 'Gynoecium occupies highest position above other floral whorls.', NULL, NULL, 'Gynoecium occupies highest position above other floral whorls.', 'EASY', true),
        ('11031111-0000-4000-8000-000000000033', 'Aestivation where margins of sepals or petals overlap one another in ONE particular direction (e.g., China rose, Lady''s finger, Cotton) is:', '{"A":"Valvate","B":"Twisted","C":"Imbricate","D":"Vexillary"}'::jsonb, 'B', 'MCQ', 'Biology', 'Morphology of Flowering Plants', 1, 'Regular sequential overlap = twisted; Fabaceae has vexillary.', NULL, NULL, 'Regular sequential overlap = twisted; Fabaceae has vexillary.', 'EASY', true),
        ('11031111-0000-4000-8000-000000000034', 'When stamens are attached to petals (as in Brinjal), the condition is termed:', '{"A":"Epiphyllous","B":"Epipetalous","C":"Monoadelphous","D":"Polyadelphous"}'::jsonb, 'B', 'MCQ', 'Biology', 'Morphology of Flowering Plants', 1, 'Epiphyllous = attached to perianth (Lily).', NULL, NULL, 'Epiphyllous = attached to perianth (Lily).', 'EASY', true),
        ('11031111-0000-4000-8000-000000000035', 'Scutellum in a monocot (maize) seed represents:', '{"A":"Seed coat","B":"Large shield-shaped single cotyledon","C":"Endosperm","D":"Coleorhiza"}'::jsonb, 'B', 'MCQ', 'Biology', 'Morphology of Flowering Plants', 1, 'Single specialised cotyledon of grasses.', NULL, NULL, 'Single specialised cotyledon of grasses.', 'EASY', true),
        ('11031111-0000-4000-8000-000000000036', 'Assertion (A): In Pea and Bean (Fabaceae), placentation is marginal while in Tomato and Lemon it is axile.
Reason (R): In marginal placentation ovules bear along a single ventral ridge suture, whereas axile placentation has ovules attached to a central axis in a multilocular ovary.
Choose the correct option:
A) Both A and R are true, and R is the correct explanation of A.
B) Both A and R are true, and R is not the correct explanation of A.
C) A is true but R is false.
D) A is false but R is true.', '{"A":"Both A and R are true, and R is the correct explanation of A","B":"Both A and R are true, and R is not the correct explanation of A","C":"A is true but R is false","D":"A is false but R is true"}'::jsonb, 'A', 'ASSERTION_REASON', 'Biology', 'Morphology of Flowering Plants', 1, 'Accurate ovary cross-section structures.', NULL, NULL, 'Accurate ovary cross-section structures.', 'EASY', true),
        ('11031111-0000-4000-8000-000000000037', 'Distinguish between Racemose and Cymose inflorescence.', NULL, NULL, 'VSA', 'Biology', 'Morphology of Flowering Plants', 2, 'Racemose: main axis grows continuously, flowers arranged acropetally. Cymose: main axis terminates in a flower (limited growth), basipetal succession.', '1M each', NULL, 'Racemose: main axis grows continuously, flowers arranged acropetally. Cymose: main axis terminates in a flower (limited growth), basipetal succession.', 'MEDIUM', true),
        ('11031111-0000-4000-8000-000000000038', 'Define Parthenocarpic fruit with one example.', NULL, NULL, 'VSA', 'Biology', 'Morphology of Flowering Plants', 2, 'Fruit developed without fertilisation of ovary, hence seedless (e.g., banana).', 'Definition (1M) + Example (1M)', NULL, 'Fruit developed without fertilisation of ovary, hence seedless (e.g., banana).', 'MEDIUM', true),
        ('11031111-0000-4000-8000-000000000039', 'Explain Basal, Parietal, and Free-Central placentation with one example each.', NULL, NULL, 'SA', 'Biology', 'Morphology of Flowering Plants', 3, 'Basal: single ovule at base of ovary (Sunflower, Marigold). Parietal: ovules on inner peripheral ovary wall (Mustard, Argemone). Free-central: ovules on central axis without septa (Dianthus, Primrose).', '1M × 3', NULL, 'Basal: single ovule at base of ovary (Sunflower, Marigold). Parietal: ovules on inner peripheral ovary wall (Mustard, Argemone). Free-central: ovules on central axis without septa (Dianthus, Primrose).', 'MEDIUM', true),
        ('11031111-0000-4000-8000-00000000003a', 'Describe the three regions of a typical root tip (Meristematic, Elongation, Maturation + Root hairs).', NULL, NULL, 'SA', 'Biology', 'Morphology of Flowering Plants', 3, 'Root cap protects apical meristem (tiny thin-walled dividing cells); Elongation zone drives rapid root lengthening; Maturation zone differentiates epidermal root hairs absorbing water/minerals.', '3 regions × 1M', NULL, 'Root cap protects apical meristem (tiny thin-walled dividing cells); Elongation zone drives rapid root lengthening; Maturation zone differentiates epidermal root hairs absorbing water/minerals.', 'MEDIUM', true),
        ('11031111-0000-4000-8000-00000000003b', 'Write the floral formula and describe all floral whorls (Calyx, Corolla, Androecium, Gynoecium, Symmetry, Placentation) of Family Solanaceae (e.g., Solanum nigrum / Potato / Tomato) with two economic uses.', NULL, NULL, 'LA', 'Biology', 'Morphology of Flowering Plants', 5, 'oplus ⚥ K(5) C(5) A5 G(2) (superior, syncarpous, bicarpellary, axile placentation with swollen placenta & oblique septum). Persistent calyx, epipetalous stamens, berry/capsule fruit. Uses: Food (potato, tomato, brinjal), Spice (chilli), Medicine (belladonna, ashwagandha).', 'Floral formula & traits (3.5M) + Uses (1.5M)', NULL, 'oplus ⚥ K(5) C(5) A5 G(2) (superior, syncarpous, bicarpellary, axile placentation with swollen placenta & oblique septum). Persistent calyx, epipetalous stamens, berry/capsule fruit. Uses: Food (potato, tomato, brinjal), Spice (chilli), Medicine (belladonna, ashwagandha).', 'HARD', true),
        ('11031111-0000-4000-8000-00000000003c', '(i) Label A–D regions of a dicot seed: outer testa, inner tegmen, hilum scar, micropyle pore. (ii) What is the function of coleoptile and coleorhiza in monocot seed? (iii) Name the proteinaceous layer separating endosperm from embryo in maize grain. (iv) Contrast actinomorphic vs zygomorphic flowers with examples.', NULL, NULL, 'CASE', 'Biology', 'Morphology of Flowering Plants', 4, '(i)Seed coats (testa/tegmen), scar of attachment (hilum), entry pore for O₂/water (micropyle). (ii) Protective sheaths enclosing plumule and radicle respectively. (iii) Aleurone layer. (iv) Radial symmetry (Mustard/Datura) vs Bilateral symmetry (Pea/Gulmohar/Bean).', '4 × 1M = 4M', 'Dissecting soaked gram and maize grains in botany practical reveals distinct cotyledon counts, protective embryo sheaths, and protein-rich endosperm layers.', '(i)Seed coats (testa/tegmen), scar of attachment (hilum), entry pore for O₂/water (micropyle). (ii) Protective sheaths enclosing plumule and radicle respectively. (iii) Aleurone layer. (iv) Radial symmetry (Mustard/Datura) vs Bilateral symmetry (Pea/Gulmohar/Bean).', 'HARD', true),
        ('11031111-0000-4000-8000-00000000003d', 'Bulliform cells (large, empty, colourless upper-epidermal motor cells) help curl grass leaves during water stress in:', '{"A":"Dicot leaf","B":"Monocot (isobilateral) leaf","C":"Dicot stem","D":"Gymnosperm root"}'::jsonb, 'B', 'MCQ', 'Biology', 'Anatomy of Flowering Plants', 1, 'Flaccid bulliform cells curl leaves inward reducing transpiration.', NULL, NULL, 'Flaccid bulliform cells curl leaves inward reducing transpiration.', 'EASY', true),
        ('11031111-0000-4000-8000-00000000003e', 'Casparian strips made of waxy suberin blocking apoplastic water entry occur on radial/tangential walls of:', '{"A":"Pericycle","B":"Endodermis of roots","C":"Cortex","D":"Epidermis"}'::jsonb, 'B', 'MCQ', 'Biology', 'Anatomy of Flowering Plants', 1, 'Forces symplastic selective ion uptake across endodermal membranes.', NULL, NULL, 'Forces symplastic selective ion uptake across endodermal membranes.', 'EASY', true),
        ('11031111-0000-4000-8000-00000000003f', 'Vascular bundles in a Dicot stem are:', '{"A":"Radial and exarch","B":"Conjoint, collateral, and OPEN (cambium present), arranged in a ring","C":"Scattered and closed","D":"Concentric only"}'::jsonb, 'B', 'MCQ', 'Biology', 'Anatomy of Flowering Plants', 1, 'Open bundles possess intrafascicular cambium; monocot stems have scattered closed bundles.', NULL, NULL, 'Open bundles possess intrafascicular cambium; monocot stems have scattered closed bundles.', 'EASY', true),
        ('11031111-0000-4000-8000-000000000040', 'In roots, protoxylem lies toward the periphery and metaxylem toward the centre; this xylem arrangement is:', '{"A":"Endarch","B":"Exarch","C":"Mesarch","D":"Polyarch"}'::jsonb, 'B', 'MCQ', 'Biology', 'Anatomy of Flowering Plants', 1, 'Roots = Exarch; Stems = Endarch.', NULL, NULL, 'Roots = Exarch; Stems = Endarch.', 'EASY', true),
        ('11031111-0000-4000-8000-000000000041', 'Subsidiary cells, guard cells, and stomatal aperture together constitute:', '{"A":"Trichome","B":"Stomatal apparatus","C":"Lenticel","D":"Hydathode"}'::jsonb, 'B', 'MCQ', 'Biology', 'Anatomy of Flowering Plants', 1, 'Bean-shaped guard cells in dicots; dumb-bell-shaped in grasses.', NULL, NULL, 'Bean-shaped guard cells in dicots; dumb-bell-shaped in grasses.', 'EASY', true),
        ('11031111-0000-4000-8000-000000000042', 'Assertion (A): Monocot stems do not undergo secondary growth.
Reason (R): Vascular bundles in monocot stems lack vascular cambium ("closed" bundles).
Choose the correct option:
A) Both A and R are true, and R is the correct explanation of A.
B) Both A and R are true, and R is not the correct explanation of A.
C) A is true but R is false.
D) A is false but R is true.', '{"A":"Both A and R are true, and R is the correct explanation of A","B":"Both A and R are true, and R is not the correct explanation of A","C":"A is true but R is false","D":"A is false but R is true"}'::jsonb, 'A', 'ASSERTION_REASON', 'Biology', 'Anatomy of Flowering Plants', 1, 'Absence of cambium prevents secondary thickening.', NULL, NULL, 'Absence of cambium prevents secondary thickening.', 'EASY', true),
        ('11031111-0000-4000-8000-000000000043', 'How do guard cells differ in shape between Dicots and Monocots (Grasses)?', NULL, NULL, 'VSA', 'Biology', 'Anatomy of Flowering Plants', 2, 'Dicots have bean/kidney-shaped guard cells; Grasses (monocots) have dumb-bell-shaped guard cells.', '1M each', NULL, 'Dicots have bean/kidney-shaped guard cells; Grasses (monocots) have dumb-bell-shaped guard cells.', 'MEDIUM', true),
        ('11031111-0000-4000-8000-000000000044', 'What is a Stele?', NULL, NULL, 'VSA', 'Biology', 'Anatomy of Flowering Plants', 2, 'All tissues lying on the inner side of the endodermis — namely pericycle, vascular bundles, and pith.', '2M', NULL, 'All tissues lying on the inner side of the endodermis — namely pericycle, vascular bundles, and pith.', 'MEDIUM', true),
        ('11031111-0000-4000-8000-000000000045', 'Differentiate anatomically between a Dicot Root and a Monocot Root (3 points: xylem bundles, pith size, secondary growth).', NULL, NULL, 'SA', 'Biology', 'Anatomy of Flowering Plants', 3, 'Dicot root: 2–4 (tetrarch) xylem-phloem patches, small/inconspicuous pith, undergoes secondary growth. Monocot root: polyarch (>6 xylem bundles), large well-developed pith, no secondary growth.', '3 × 1M', NULL, 'Dicot root: 2–4 (tetrarch) xylem-phloem patches, small/inconspicuous pith, undergoes secondary growth. Monocot root: polyarch (>6 xylem bundles), large well-developed pith, no secondary growth.', 'MEDIUM', true),
        ('11031111-0000-4000-8000-000000000046', 'Compare Dorsiventral (Dicot) leaf vs Isobilateral (Monocot) leaf anatomy.', NULL, NULL, 'SA', 'Biology', 'Anatomy of Flowering Plants', 3, 'Dicot: stomata mostly abaxial (lower), mesophyll differentiated into palisade & spongy parenchyma, reticulate venation sizes. Monocot: stomata equal on both surfaces, undifferentiated spongy mesophyll, bulliform cells present.', '3 × 1M', NULL, 'Dicot: stomata mostly abaxial (lower), mesophyll differentiated into palisade & spongy parenchyma, reticulate venation sizes. Monocot: stomata equal on both surfaces, undifferentiated spongy mesophyll, bulliform cells present.', 'MEDIUM', true),
        ('11031111-0000-4000-8000-000000000047', 'Compare the internal anatomy of a Dicot Stem and a Monocot Stem across five tissues: Epidermis/Hypodermis, Ground tissue/Cortex, Vascular bundle arrangement, Cambium & Water-containing cavities, and Secondary growth.', NULL, NULL, 'LA', 'Biology', 'Anatomy of Flowering Plants', 5, 'Dicot stem: collenchymatous hypodermis, distinct cortex/endodermis/pericycle/pith, vascular bundles in ring, conjoint open (cambium present), secondary growth occurs. Monocot stem: sclerenchymatous hypodermis, undifferentiated ground tissue, scattered closed bundles with bundle sheath, phloem parenchyma absent & lysigenous water cavity present, no secondary growth.', '5 tissue comparisons × 1M = 5M', NULL, 'Dicot stem: collenchymatous hypodermis, distinct cortex/endodermis/pericycle/pith, vascular bundles in ring, conjoint open (cambium present), secondary growth occurs. Monocot stem: sclerenchymatous hypodermis, undifferentiated ground tissue, scattered closed bundles with bundle sheath, phloem parenchyma absent & lysigenous water cavity present, no secondary growth.', 'HARD', true),
        ('11031111-0000-4000-8000-000000000048', '(i) Define Cuticle and name the only epidermal zone lacking cuticle. (ii) Compare root hairs vs stem trichomes. (iii) Why is outer wall of guard cell thin while inner pore-facing wall is thick? (iv) Name the starch-storing layer in dicot stem endodermis.', NULL, NULL, 'CASE', 'Biology', 'Anatomy of Flowering Plants', 4, '(i) Waxy outer coating preventing water loss; absent in roots. (ii) Root hairs are unicellular absorptive extensions; trichomes are usually multicellular branched/secretory hairs preventing water loss. (iii) Differential wall thickness allows outward bulging when turgid to open stomatal pore. (iv) Starch sheath.', '4 × 1M = 4M', 'Under a compound microscope, cross-sections of sunflower and maize stems show striking contrasts in bundle rings, sclerenchyma caps, and epidermal trichomes.', '(i) Waxy outer coating preventing water loss; absent in roots. (ii) Root hairs are unicellular absorptive extensions; trichomes are usually multicellular branched/secretory hairs preventing water loss. (iii) Differential wall thickness allows outward bulging when turgid to open stomatal pore. (iv) Starch sheath.', 'HARD', true),
        ('11031111-0000-4000-8000-000000000049', 'How many chambers are present in the heart of a frog (Rana tigrina)?', '{"A":"Two","B":"Three (two atria and one ventricle)","C":"Four","D":"One"}'::jsonb, 'B', 'MCQ', 'Biology', 'Structural Organisation in Animals', 1, 'Three-chambered heart with sinus venosus and conus arteriosus.', NULL, NULL, 'Three-chambered heart with sinus venosus and conus arteriosus.', 'EASY', true),
        ('11031111-0000-4000-8000-00000000004a', 'During hibernation (winter sleep) and aestivation (summer sleep), a frog respires exclusively through its:', '{"A":"Lungs","B":"Buccal cavity","C":"Moist skin (cutaneous respiration)","D":"Gills"}'::jsonb, 'C', 'MCQ', 'Biology', 'Structural Organisation in Animals', 1, 'Cutaneous gas exchange works underwater and underground.', NULL, NULL, 'Cutaneous gas exchange works underwater and underground.', 'EASY', true),
        ('11031111-0000-4000-8000-00000000004b', 'Vasa efferentia in male frogs connect testes directly to:', '{"A":"Cloaca directly","B":"Bidder''s canal inside the kidney before opening into urinogenital duct","C":"Urinary bladder","D":"Pancreas"}'::jsonb, 'B', 'MCQ', 'Biology', 'Structural Organisation in Animals', 1, '10–12 vasa efferentia enter kidneys -> Bidder''s canal -> ureter (urinogenital duct).', NULL, NULL, '10–12 vasa efferentia enter kidneys -> Bidder''s canal -> ureter (urinogenital duct).', 'EASY', true),
        ('11031111-0000-4000-8000-00000000004c', 'Frogs excrete nitrogenous waste primarily as:', '{"A":"Ammonia","B":"Urea (ureotelic)","C":"Uric acid","D":"Amino acids"}'::jsonb, 'B', 'MCQ', 'Biology', 'Structural Organisation in Animals', 1, 'Adult frog is ureotelic; aquatic tadpole is ammonotelic.', NULL, NULL, 'Adult frog is ureotelic; aquatic tadpole is ammonotelic.', 'EASY', true),
        ('11031111-0000-4000-8000-00000000004d', 'Which membrane protects frog''s eyes while swimming underwater?', '{"A":"Tympanum","B":"Nictitating membrane (third eyelid)","C":"Cornea only","D":"Retina"}'::jsonb, 'B', 'MCQ', 'Biology', 'Structural Organisation in Animals', 1, 'Transparent nictitating membrane shields eye in water.', NULL, NULL, 'Transparent nictitating membrane shields eye in water.', 'EASY', true),
        ('11031111-0000-4000-8000-00000000004e', 'Assertion (A): In male frogs, vocal sacs on the throat and copulatory pads on the first digit of forelimbs enable sexual dimorphism.
Reason (R): Females lack both sound-producing vocal sacs and thumb copulatory pads.
Choose the correct option:
A) Both A and R are true, and R is the correct explanation of A.
B) Both A and R are true, and R is not the correct explanation of A.
C) A is true but R is false.
D) A is false but R is true.', '{"A":"Both A and R are true, and R is the correct explanation of A","B":"Both A and R are true, and R is not the correct explanation of A","C":"A is true but R is false","D":"A is false but R is true"}'::jsonb, 'A', 'ASSERTION_REASON', 'Biology', 'Structural Organisation in Animals', 1, 'External diagnostic traits distinguish male vs female frogs.', NULL, NULL, 'External diagnostic traits distinguish male vs female frogs.', 'EASY', true),
        ('11031111-0000-4000-8000-00000000004f', 'What is Poikilothermy and Mimicry/Camouflage in frogs?', NULL, NULL, 'VSA', 'Biology', 'Structural Organisation in Animals', 2, 'Cold-bloodedness (body temperature varies with environment). Frogs change colour on grasses/dry land (protective colouration/mimicry) to hide from predators.', '1M each', NULL, 'Cold-bloodedness (body temperature varies with environment). Frogs change colour on grasses/dry land (protective colouration/mimicry) to hide from predators.', 'MEDIUM', true),
        ('11031111-0000-4000-8000-000000000050', 'Why is the digestive tract of a frog relatively short?', NULL, NULL, 'VSA', 'Biology', 'Structural Organisation in Animals', 2, 'Because adult frogs are strictly carnivores feeding on insects/worms, which digest faster than plant cellulose.', '2M', NULL, 'Because adult frogs are strictly carnivores feeding on insects/worms, which digest faster than plant cellulose.', 'MEDIUM', true),
        ('11031111-0000-4000-8000-000000000051', 'Explain the three modes of respiration used by Rana tigrina on land vs in water.', NULL, NULL, 'SA', 'Biology', 'Structural Organisation in Animals', 3, 'Cutaneous (moist skin dissolved O₂ — both land & water/hibernation), Buccal (moist oral lining on land), Pulmonary (pair of pink sac-like lungs via nostrils on land).', '3 × 1M', NULL, 'Cutaneous (moist skin dissolved O₂ — both land & water/hibernation), Buccal (moist oral lining on land), Pulmonary (pair of pink sac-like lungs via nostrils on land).', 'MEDIUM', true),
        ('11031111-0000-4000-8000-000000000052', 'Trace the blood circulation pathway through the frog''s three-chambered heart, sinus venosus, and conus arteriosus.', NULL, NULL, 'SA', 'Biology', 'Structural Organisation in Animals', 3, 'Sinus venosus collects deoxygenated venous blood -> Right atrium; Lungs return oxygenated blood -> Left atrium. Both empty into single ventricle -> pumped into ventral conus arteriosus -> tissues/lungs.', 'Pathway cleanly traced (3M)', NULL, 'Sinus venosus collects deoxygenated venous blood -> Right atrium; Lungs return oxygenated blood -> Left atrium. Both empty into single ventricle -> pumped into ventral conus arteriosus -> tissues/lungs.', 'MEDIUM', true),
        ('11031111-0000-4000-8000-000000000053', 'Describe the Male and Female Reproductive Systems of Frog (Rana tigrina) noting Bidder''s canal, urinogenital duct difference, fertilisation site, egg count, and larval development.', NULL, NULL, 'LA', 'Biology', 'Structural Organisation in Animals', 5, 'Male: paired yellowish testes attached to kidneys via mesorchium -> 10–12 vasa efferentia -> Bidder''s canal -> collecting tubules -> urinogenital duct carrying BOTH urine and sperms into cloaca. Female: paired ovaries near kidneys (no functional connection to kidneys) -> paired oviducts opening separately into cloaca -> lays 2500–3000 ova externally in water; external fertilisation -> tadpole larva undergoes metamorphosis.', 'Male system (2.5M) + Female & fertilisation (2.5M)', NULL, 'Male: paired yellowish testes attached to kidneys via mesorchium -> 10–12 vasa efferentia -> Bidder''s canal -> collecting tubules -> urinogenital duct carrying BOTH urine and sperms into cloaca. Female: paired ovaries near kidneys (no functional connection to kidneys) -> paired oviducts opening separately into cloaca -> lays 2500–3000 ova externally in water; external fertilisation -> tadpole larva undergoes metamorphosis.', 'HARD', true),
        ('11031111-0000-4000-8000-000000000054', '(i) How many pairs of cranial nerves arise from a frog''s brain? (ii) Role of liver bile and pancreatic juice in frog''s duodenum. (iii) Why do frogs have a renal portal system and hepatic portal system? (iv) Name the ear organ receiving sound waves.', NULL, NULL, 'CASE', 'Biology', 'Structural Organisation in Animals', 4, '(i) 10 pairs. (ii) Bile emulsifies fats; pancreatic juice digests carbohydrates and proteins. (iii) Special venous bypasses routing kidney/intestine blood through capillaries before heart return. (iv) Tympanum (ear drum, no external pinna).', '4 × 1M = 4M', 'Observing an Indian bullfrog in monsoon puddles highlights webbed hind digits for swimming, protruding eyes without external ear pinnae, and moist vascular skin.', '(i) 10 pairs. (ii) Bile emulsifies fats; pancreatic juice digests carbohydrates and proteins. (iii) Special venous bypasses routing kidney/intestine blood through capillaries before heart return. (iv) Tympanum (ear drum, no external pinna).', 'HARD', true),
        ('11031111-0000-4000-8000-000000000055', 'Fluid Mosaic Model of plasma membrane was proposed in 1972 by:', '{"A":"Schleiden and Schwann","B":"Singer and Nicolson","C":"Robert Brown","D":"Camillo Golgi"}'::jsonb, 'B', 'MCQ', 'Biology', 'Cell: The Unit of Life', 1, 'Quasi-fluid lipid bilayer allows lateral movement of integral proteins.', NULL, NULL, 'Quasi-fluid lipid bilayer allows lateral movement of integral proteins.', 'EASY', true),
        ('11031111-0000-4000-8000-000000000056', 'Sub-metacentric chromosome has the centromere slightly away from the middle, resulting in:', '{"A":"Equal arms","B":"One shorter arm (p) and one longer arm (q) appearing L-shaped at anaphase","C":"Terminal centromere","D":"Two centromeres"}'::jsonb, 'B', 'MCQ', 'Biology', 'Cell: The Unit of Life', 1, 'Metacentric (V), Sub-metacentric (L), Acrocentric (J), Telocentric (I).', NULL, NULL, 'Metacentric (V), Sub-metacentric (L), Acrocentric (J), Telocentric (I).', 'EASY', true),
        ('11031111-0000-4000-8000-000000000057', 'Hydrolytic enzymes (lipases, proteases, carbohydrases) active at acidic pH are packaged inside:', '{"A":"Peroxisomes","B":"Lysosomes","C":"Ribosomes","D":"Centrosomes"}'::jsonb, 'B', 'MCQ', 'Biology', 'Cell: The Unit of Life', 1, 'Single-membrane suicidal bags derived from Golgi apparatus.', NULL, NULL, 'Single-membrane suicidal bags derived from Golgi apparatus.', 'EASY', true),
        ('11031111-0000-4000-8000-000000000058', '70S ribosomes (50S + 30S subunits) are found inside:', '{"A":"Eukaryotic cytoplasm only","B":"Prokaryotes, as well as Mitochondria and Chloroplasts of eukaryotes","C":"Golgi bodies","D":"Lysosomes"}'::jsonb, 'B', 'MCQ', 'Biology', 'Cell: The Unit of Life', 1, 'Endosymbiotic organelles retain 70S ribosomes and circular DNA.', NULL, NULL, 'Endosymbiotic organelles retain 70S ribosomes and circular DNA.', 'EASY', true),
        ('11031111-0000-4000-8000-000000000059', '9 + 2 microtubule array of peripheral doublets and central pair is characteristic of:', '{"A":"Centriole","B":"Eukaryotic cilia and flagella axoneme","C":"Bacterial flagellum","D":"Microfilament"}'::jsonb, 'B', 'MCQ', 'Biology', 'Cell: The Unit of Life', 1, 'Centrioles show 9+0 cartwheel; cilia/flagella axoneme shows 9+2.', NULL, NULL, 'Centrioles show 9+0 cartwheel; cilia/flagella axoneme shows 9+2.', 'EASY', true),
        ('11031111-0000-4000-8000-00000000005a', 'Assertion (A): Mitochondria and Chloroplasts are termed semi-autonomous organelles.
Reason (R): Both contain their own circular DNA molecules, RNA, and 70S ribosomes capable of synthesising part of their own proteins.
Choose the correct option:
A) Both A and R are true, and R is the correct explanation of A.
B) Both A and R are true, and R is not the correct explanation of A.
C) A is true but R is false.
D) A is false but R is true.', '{"A":"Both A and R are true, and R is the correct explanation of A","B":"Both A and R are true, and R is not the correct explanation of A","C":"A is true but R is false","D":"A is false but R is true"}'::jsonb, 'A', 'ASSERTION_REASON', 'Biology', 'Cell: The Unit of Life', 1, 'Internal genetic machinery enables semi-autonomy.', NULL, NULL, 'Internal genetic machinery enables semi-autonomy.', 'EASY', true),
        ('11031111-0000-4000-8000-00000000005b', 'State the two statements of Modern Cell Theory as modified by Rudolf Virchow.', NULL, NULL, 'VSA', 'Biology', 'Cell: The Unit of Life', 2, '(1) All living organisms are composed of cells and products of cells. (2) All cells arise from pre-existing cells ("Omnis cellula-e cellula").', '1M each', NULL, '(1) All living organisms are composed of cells and products of cells. (2) All cells arise from pre-existing cells ("Omnis cellula-e cellula").', 'MEDIUM', true),
        ('11031111-0000-4000-8000-00000000005c', 'Distinguish between Active transport and Passive transport across plasma membrane with one example.', NULL, NULL, 'VSA', 'Biology', 'Cell: The Unit of Life', 2, 'Passive moves down concentration gradient without ATP (osmosis/diffusion). Active pumps against gradient using ATP (Na⁺/K⁺ pump).', '1M each', NULL, 'Passive moves down concentration gradient without ATP (osmosis/diffusion). Active pumps against gradient using ATP (Na⁺/K⁺ pump).', 'MEDIUM', true),
        ('11031111-0000-4000-8000-00000000005d', 'Explain the Endomembrane System: why are ER, Golgi apparatus, Lysosomes, and Vacuoles grouped together while Mitochondria/Chloroplasts are excluded?', NULL, NULL, 'SA', 'Biology', 'Cell: The Unit of Life', 3, 'Their functions are tightly coordinated: proteins/lipids made on RER/SER move via vesicles to cis-Golgi -> modified & sorted at trans face -> packaged into lysosomes/vacuoles/secretions. Mitochondria/plastids/peroxisomes operate independently.', 'Coordinated vesicle flow (2M) + Exclusion reason (1M)', NULL, 'Their functions are tightly coordinated: proteins/lipids made on RER/SER move via vesicles to cis-Golgi -> modified & sorted at trans face -> packaged into lysosomes/vacuoles/secretions. Mitochondria/plastids/peroxisomes operate independently.', 'MEDIUM', true),
        ('11031111-0000-4000-8000-00000000005e', 'List three roles of Mesosomes in prokaryotic bacterial cells.', NULL, NULL, 'SA', 'Biology', 'Cell: The Unit of Life', 3, 'Cell wall formation, DNA replication & distribution to daughter cells, respiration, and increasing plasma membrane surface area for enzymatic activity.', '3 × 1M', NULL, 'Cell wall formation, DNA replication & distribution to daughter cells, respiration, and increasing plasma membrane surface area for enzymatic activity.', 'MEDIUM', true),
        ('11031111-0000-4000-8000-00000000005f', 'Describe the ultrastructure and functions of (a) Chloroplast (double membrane, stroma, thylakoids, grana, stroma lamellae) and (b) Nucleus (nuclear envelope, nuclear pores, nucleolus, chromatin/SAT-chromosomes).', NULL, NULL, 'LA', 'Biology', 'Cell: The Unit of Life', 5, 'Chloroplast (2.5M): double envelope, colourless stroma with 70S ribosomes/ds circular DNA/enzymes, stacked thylakoid coins (grana) for light reactions and stroma for dark reactions. Nucleus (2.5M): double porous envelope, nucleoplasm, non-membranous rRNA-factory nucleolus, nucleoprotein chromatin condensing into chromosomes.', '(a) 2.5M + (b) 2.5M', NULL, 'Chloroplast (2.5M): double envelope, colourless stroma with 70S ribosomes/ds circular DNA/enzymes, stacked thylakoid coins (grana) for light reactions and stroma for dark reactions. Nucleus (2.5M): double porous envelope, nucleoplasm, non-membranous rRNA-factory nucleolus, nucleoprotein chromatin condensing into chromosomes.', 'HARD', true),
        ('11031111-0000-4000-8000-000000000060', '(i) Contrast plasmid DNA vs genomic DNA in bacteria. (ii) What is "polyribosome / polysome"? (iii) Role of contractile vacuole in Amoeba vs gas vacuoles in blue-green bacteria. (iv) What are Pili and Fimbriae?', NULL, NULL, 'CASE', 'Biology', 'Cell: The Unit of Life', 4, '(i) Small circular extrachromosomal DNA conferring antibiotic resistance vs single main circular chromosome. (ii) Several ribosomes attached to a single mRNA translating proteins simultaneously. (iii) Contractile vacuole performs osmoregulation/excretion; gas vacuoles regulate buoyancy. (iv) Surface extensions aiding conjugation (pili) or rock/host attachment (fimbriae).', '4 × 1M = 4M', 'Electron micrographs of Escherichia coli and leaf mesophyll cells reveal key contrasts in membrane-bound compartmentalisation, ribosome sedimentation, and surface appendages.', '(i) Small circular extrachromosomal DNA conferring antibiotic resistance vs single main circular chromosome. (ii) Several ribosomes attached to a single mRNA translating proteins simultaneously. (iii) Contractile vacuole performs osmoregulation/excretion; gas vacuoles regulate buoyancy. (iv) Surface extensions aiding conjugation (pili) or rock/host attachment (fimbriae).', 'HARD', true),
        ('11031111-0000-4000-8000-000000000061', 'Most abundant protein in the whole biosphere and most abundant protein in the animal world respectively are:', '{"A":"Collagen and RuBisCO","B":"RuBisCO and Collagen","C":"Insulin and Keratin","D":"Haemoglobin and Myosin"}'::jsonb, 'B', 'MCQ', 'Biology', 'Biomolecules', 1, 'RuBisCO dominates plant leaves; Collagen dominates animal extracellular matrix.', NULL, NULL, 'RuBisCO dominates plant leaves; Collagen dominates animal extracellular matrix.', 'EASY', true),
        ('11031111-0000-4000-8000-000000000062', 'A zwitterion form of an amino acid exists at its isoelectric pH with:', '{"A":"Net positive charge only","B":"Both positive (-NH₃⁺) and negative (-COO⁻) charges simultaneously","C":"Only carboxyl ion","D":"No nitrogen"}'::jsonb, 'B', 'MCQ', 'Biology', 'Biomolecules', 1, 'Dipolar neutral ionic species.', NULL, NULL, 'Dipolar neutral ionic species.', 'EASY', true),
        ('11031111-0000-4000-8000-000000000063', 'The chemical bond linking consecutive monosaccharides in starch/cellulose and nucleotides in DNA respectively are:', '{"A":"Peptide and Ester","B":"Glycosidic bond and Phosphodiester bond","C":"Hydrogen and Disulphide","D":"Ionic and Covalent"}'::jsonb, 'B', 'MCQ', 'Biology', 'Biomolecules', 1, 'Glycosidic in polysaccharides; 3''-5'' phosphodiester in nucleic acids.', NULL, NULL, 'Glycosidic in polysaccharides; 3''-5'' phosphodiester in nucleic acids.', 'EASY', true),
        ('11031111-0000-4000-8000-000000000064', 'Competitive inhibition of enzyme Succinic dehydrogenase by Malonate occurs because:', '{"A":"Malonate denatures protein","B":"Malonate closely resembles the substrate Succinate and competes for the active site","C":"Malonate changes pH","D":"Malonate binds allosterically permanently"}'::jsonb, 'B', 'MCQ', 'Biology', 'Biomolecules', 1, 'Reversible structural mimicry solved by raising [Succinate].', NULL, NULL, 'Reversible structural mimicry solved by raising [Succinate].', 'EASY', true),
        ('11031111-0000-4000-8000-000000000065', 'Why is Cellulose NOT positive with iodine I₂ solution unlike Starch?', '{"A":"It is too small","B":"Cellulose forms straight unbranched chains lacking helical coils that trap I₂ molecules","C":"It dissolves in iodine","D":"It contains fructose"}'::jsonb, 'B', 'MCQ', 'Biology', 'Biomolecules', 1, 'Amylose helices trap I₂ turning blue-black; straight cellulose cannot.', NULL, NULL, 'Amylose helices trap I₂ turning blue-black; straight cellulose cannot.', 'EASY', true),
        ('11031111-0000-4000-8000-000000000066', 'Assertion (A): Enzymes accelerate chemical reactions dramatically without being consumed in the overall process.
Reason (R): Enzymes lower the activation energy barrier between substrate and transition state.
Choose the correct option:
A) Both A and R are true, and R is the correct explanation of A.
B) Both A and R are true, and R is not the correct explanation of A.
C) A is true but R is false.
D) A is false but R is true.', '{"A":"Both A and R are true, and R is the correct explanation of A","B":"Both A and R are true, and R is not the correct explanation of A","C":"A is true but R is false","D":"A is false but R is true"}'::jsonb, 'A', 'ASSERTION_REASON', 'Biology', 'Biomolecules', 1, 'Catalytic lowering of activation energy raises reaction rate.', NULL, NULL, 'Catalytic lowering of activation energy raises reaction rate.', 'EASY', true),
        ('11031111-0000-4000-8000-000000000067', 'Distinguish between Primary Metabolites and Secondary Metabolites with two examples each.', NULL, NULL, 'VSA', 'Biology', 'Biomolecules', 2, 'Primary: essential roles in normal physiological growth (amino acids, sugars, nucleic acids). Secondary: ecological/unknown roles in plants/fungi/microbes (alkaloids/morphine, carotenoids, rubber, antibiotics).', '1M each', NULL, 'Primary: essential roles in normal physiological growth (amino acids, sugars, nucleic acids). Secondary: ecological/unknown roles in plants/fungi/microbes (alkaloids/morphine, carotenoids, rubber, antibiotics).', 'MEDIUM', true),
        ('11031111-0000-4000-8000-000000000068', 'Contrast Saturated vs Unsaturated fatty acids with one example each (and glycerol esterification).', NULL, NULL, 'VSA', 'Biology', 'Biomolecules', 2, 'Saturated have no C=C double bonds (palmitic acid 16C); Unsaturated contain 1+ C=C bonds (oleic/arachidonic acid 20C). Triglycerides esterify 3 fatty acids onto 1 glycerol.', '2M', NULL, 'Saturated have no C=C double bonds (palmitic acid 16C); Unsaturated contain 1+ C=C bonds (oleic/arachidonic acid 20C). Triglycerides esterify 3 fatty acids onto 1 glycerol.', 'MEDIUM', true),
        ('11031111-0000-4000-8000-000000000069', 'Explain the four levels of Protein Structure (Primary, Secondary, Tertiary, Quaternary) with one example.', NULL, NULL, 'SA', 'Biology', 'Biomolecules', 3, 'Primary: linear amino acid sequence; Secondary: α-helix or β-pleated sheet via H-bonds; Tertiary: 3D hollow woollen-ball folding essential for enzyme/protein activity; Quaternary: multiple polypeptide subunits assembled (e.g., adult Haemoglobin 2α + 2β).', '4 levels cleanly (3M)', NULL, 'Primary: linear amino acid sequence; Secondary: α-helix or β-pleated sheet via H-bonds; Tertiary: 3D hollow woollen-ball folding essential for enzyme/protein activity; Quaternary: multiple polypeptide subunits assembled (e.g., adult Haemoglobin 2α + 2β).', 'MEDIUM', true),
        ('11031111-0000-4000-8000-00000000006a', 'Explain how temperature, pH, and substrate concentration [S] affect enzyme reaction velocity (defining K_m).', NULL, NULL, 'SA', 'Biology', 'Biomolecules', 3, 'Bell-shaped T and pH curves peaking at optimum (low T inactivates, high T denatures). Velocity rises hyperbolically with [S] reaching V_max saturation; K_m is [S] at ½ V_max.', '1M × 3', NULL, 'Bell-shaped T and pH curves peaking at optimum (low T inactivates, high T denatures). Velocity rises hyperbolically with [S] reaching V_max saturation; K_m is [S] at ½ V_max.', 'MEDIUM', true),
        ('11031111-0000-4000-8000-00000000006b', 'Describe Watson-Crick B-DNA double helix structure (antiparallel strands, sugar-phosphate backbone, A=T & G≡C pairing, pitch 3.4 nm, 10 bp/turn) and classify all six IUBMB Enzyme Classes (Oxidoreductases, Transferases, Hydrolases, Lyases, Isomerases, Ligases) with one function each.', NULL, NULL, 'LA', 'Biology', 'Biomolecules', 5, 'B-DNA structural measurements & base pairing (2.5M) + Six enzyme classes accurately defined (2.5M).', 'B-DNA (2.5M) + 6 Enzyme classes (2.5M)', NULL, 'B-DNA structural measurements & base pairing (2.5M) + Six enzyme classes accurately defined (2.5M).', 'HARD', true),
        ('11031111-0000-4000-8000-00000000006c', '(i) Define Cofactors and distinguish Prosthetic groups, Co-enzymes, and Metal ions. (ii) Which vitamin is an essential component of co-enzymes NAD and NADP? (iii) Identify the nucleotide vs nucleoside difference. (iv) Name the polymer of fructose stored in roots of Dahlia.', NULL, NULL, 'CASE', 'Biology', 'Biomolecules', 4, '(i) Non-protein helpers required for catalysis: tightly bound organic (prosthetic like haem in peroxidase/catalase), transiently bound organic (co-enzymes like NAD), and coordinate metal ions (Zn²⁺ in carboxypeptidase). (ii) Niacin (Vitamin B₃). (iii) Nucleoside = Sugar + Base; Nucleotide = Sugar + Base + Phosphate. (iv) Inulin.', '4 × 1M = 4M', 'Biochemists extracting catalase from potato tubers examine how non-protein haem prosthetic groups, vitamins, and zinc cofactors regulate metabolic enzyme catalysis.', '(i) Non-protein helpers required for catalysis: tightly bound organic (prosthetic like haem in peroxidase/catalase), transiently bound organic (co-enzymes like NAD), and coordinate metal ions (Zn²⁺ in carboxypeptidase). (ii) Niacin (Vitamin B₃). (iii) Nucleoside = Sugar + Base; Nucleotide = Sugar + Base + Phosphate. (iv) Inulin.', 'HARD', true),
        ('11031111-0000-4000-8000-00000000006d', 'DNA replication occurs during which sub-stage of Interphase?', '{"A":"G₁ phase","B":"S (Synthesis) phase (DNA content doubles 2C -> 4C while chromosome number stays 2n)","C":"G₂ phase","D":"G₀ phase"}'::jsonb, 'B', 'MCQ', 'Biology', 'Cell Cycle and Cell Division', 1, 'Centriole also duplicates in animal cytoplasm during S phase.', NULL, NULL, 'Centriole also duplicates in animal cytoplasm during S phase.', 'EASY', true),
        ('11031111-0000-4000-8000-00000000006e', 'Crossing over (exchange of genetic segments between non-sister chromatids) occurs at:', '{"A":"Leptotene","B":"Zygotene","C":"Pachytene (mediated by recombinase)","D":"Diplotene"}'::jsonb, 'C', 'MCQ', 'Biology', 'Cell Cycle and Cell Division', 1, 'Pachytene crossing over generates genetic variation.', NULL, NULL, 'Pachytene crossing over generates genetic variation.', 'EASY', true),
        ('11031111-0000-4000-8000-00000000006f', 'Best stage of mitosis to clearly study morphology (shape & size) of chromosomes under microscope is:', '{"A":"Prophase","B":"Metaphase (condensation complete & aligned at equatorial plate)","C":"Anaphase","D":"Telophase"}'::jsonb, 'B', 'MCQ', 'Biology', 'Cell Cycle and Cell Division', 1, 'Chromosomes are maximally condensed at metaphase.', NULL, NULL, 'Chromosomes are maximally condensed at metaphase.', 'EASY', true),
        ('11031111-0000-4000-8000-000000000070', 'During Anaphase of mitosis vs Anaphase I of meiosis:', '{"A":"Centromeres split in mitosis & Anaphase II; homologous chromosomes separate without centromere split in Anaphase I","B":"Both split centromeres","C":"Neither splits","D":"Sister chromatids fuse"}'::jsonb, 'A', 'MCQ', 'Biology', 'Cell Cycle and Cell Division', 1, 'Reduction from 2n to n occurs at Anaphase I.', NULL, NULL, 'Reduction from 2n to n occurs at Anaphase I.', 'EASY', true),
        ('11031111-0000-4000-8000-000000000071', 'Failure of cytokinesis after karyokinesis leads to a multinucleated syncytium condition seen in:', '{"A":"Onion root tip","B":"Liquid endosperm of coconut","C":"Bacteria","D":"Yeast buds"}'::jsonb, 'B', 'MCQ', 'Biology', 'Cell Cycle and Cell Division', 1, 'Free nuclear division produces liquid coconut endosperm.', NULL, NULL, 'Free nuclear division produces liquid coconut endosperm.', 'EASY', true),
        ('11031111-0000-4000-8000-000000000072', 'Assertion (A): Mitosis is called equational division whereas Meiosis is called reductional division.
Reason (R): Mitosis maintains chromosome number identical between parent and daughter cells (2n->2n), whereas Meiosis halves chromosome number (2n->n) to keep sexual life cycle ploidy constant.
Choose the correct option:
A) Both A and R are true, and R is the correct explanation of A.
B) Both A and R are true, and R is not the correct explanation of A.
C) A is true but R is false.
D) A is false but R is true.', '{"A":"Both A and R are true, and R is the correct explanation of A","B":"Both A and R are true, and R is not the correct explanation of A","C":"A is true but R is false","D":"A is false but R is true"}'::jsonb, 'A', 'ASSERTION_REASON', 'Biology', 'Cell Cycle and Cell Division', 1, 'Fertilisation restores 2n only because gametes are haploid n.', NULL, NULL, 'Fertilisation restores 2n only because gametes are haploid n.', 'EASY', true),
        ('11031111-0000-4000-8000-000000000073', 'What is Quiescent Stage (G₀)? Give one human cell example that enters G₀.', NULL, NULL, 'VSA', 'Biology', 'Cell Cycle and Cell Division', 2, 'An inactive metabolic stage where cells exit G₁ and stop dividing until signalled to replace injured cells (e.g., adult heart/muscle/nerve cells).', 'Definition (1M) + Example (1M)', NULL, 'An inactive metabolic stage where cells exit G₁ and stop dividing until signalled to replace injured cells (e.g., adult heart/muscle/nerve cells).', 'MEDIUM', true),
        ('11031111-0000-4000-8000-000000000074', 'How does Cytokinesis in plant cells differ from animal cells?', NULL, NULL, 'VSA', 'Biology', 'Cell Cycle and Cell Division', 2, 'Animal cells form a peripheral plasma membrane cleavage furrow growing inward; Plant cells have inextensible rigid walls so they build a central cell plate (middle lamella) outward.', '1M each', NULL, 'Animal cells form a peripheral plasma membrane cleavage furrow growing inward; Plant cells have inextensible rigid walls so they build a central cell plate (middle lamella) outward.', 'MEDIUM', true),
        ('11031111-0000-4000-8000-000000000075', 'List the five sub-stages of Prophase I of Meiosis with their defining chromosomal events.', NULL, NULL, 'SA', 'Biology', 'Cell Cycle and Cell Division', 3, 'Leptotene (compaction), Zygotene (synapsis forming bivalents/synaptonemal complex), Pachytene (crossing over by recombinase), Diplotene (chiasmata X-structures visible as synaptonemal complex dissolves), Diakinesis (terminalisation of chiasmata).', '3M', NULL, 'Leptotene (compaction), Zygotene (synapsis forming bivalents/synaptonemal complex), Pachytene (crossing over by recombinase), Diplotene (chiasmata X-structures visible as synaptonemal complex dissolves), Diakinesis (terminalisation of chiasmata).', 'MEDIUM', true),
        ('11031111-0000-4000-8000-000000000076', 'State three biological significances of Mitosis vs three of Meiosis.', NULL, NULL, 'SA', 'Biology', 'Cell Cycle and Cell Division', 3, 'Mitosis: genetic uniformity, multicellular growth, cell repair/replacement. Meiosis: maintains constant chromosome number across generations, creates genetic variation via crossing over & independent assortment driving evolution.', '1.5M each', NULL, 'Mitosis: genetic uniformity, multicellular growth, cell repair/replacement. Meiosis: maintains constant chromosome number across generations, creates genetic variation via crossing over & independent assortment driving evolution.', 'MEDIUM', true),
        ('11031111-0000-4000-8000-000000000077', 'Trace all stages of Mitosis (Prophase, Metaphase, Anaphase, Telophase + Cytokinesis) clearly noting chromosome condensation, spindle attachment at kinetochores, centromere splitting, and nuclear reformation. If a diploid cell has 2n = 16 chromosomes and 2C DNA at G₁, give chromosome count and DNA content after S phase, after Mitosis, and after Meiosis I.', NULL, NULL, 'LA', 'Biology', 'Cell Cycle and Cell Division', 5, '4 stages explained cleanly (3M). Counts: After S = 16 chr, 4C DNA; After Mitosis = 16 chr, 2C DNA; After Meiosis I = 8 chr, 2C DNA (2M).', 'Stages (3M) + Numerical ploidy/DNA table (2M)', NULL, '4 stages explained cleanly (3M). Counts: After S = 16 chr, 4C DNA; After Mitosis = 16 chr, 2C DNA; After Meiosis I = 8 chr, 2C DNA (2M).', 'HARD', true),
        ('11031111-0000-4000-8000-000000000078', '(i) Which stage can last months or years in oocytes of some vertebrates? (ii) Role of kinetochore disc during metaphase. (iii) Why is DNA content doubled during S phase without doubling chromosome count? (iv) What happens during Interkinesis between Meiosis I and II?', NULL, NULL, 'CASE', 'Biology', 'Cell Cycle and Cell Division', 4, '(i) Diplotene. (ii) Site on centromere where spindle microtubules attach to sister chromatids. (iii) Sister chromatids stay joined at one centromere so chromosome number remains 2n while DNA doubles 2C -> 4C. (iv) Short rest phase with centriole duplication (NO DNA replication).', '4 × 1M = 4M', 'Observing stained onion root tips and grasshopper testis squashes reveals precise chromosome choreography across equational and reductional divisions.', '(i) Diplotene. (ii) Site on centromere where spindle microtubules attach to sister chromatids. (iii) Sister chromatids stay joined at one centromere so chromosome number remains 2n while DNA doubles 2C -> 4C. (iv) Short rest phase with centriole duplication (NO DNA replication).', 'HARD', true),
        ('11031111-0000-4000-8000-000000000079', 'Reaction centre chlorophyll molecule of Photosystem II (PS II) and PS I respectively absorb maximally at:', '{"A":"700 nm and 680 nm","B":"680 nm (P680) and 700 nm (P700)","C":"450 nm and 550 nm","D":"650 nm and 750 nm"}'::jsonb, 'B', 'MCQ', 'Biology', 'Photosynthesis in Higher Plants', 1, 'PS II = P680; PS I = P700.', NULL, NULL, 'PS II = P680; PS I = P700.', 'EASY', true),
        ('11031111-0000-4000-8000-00000000007a', 'First stable organic product of CO₂ fixation in C₃ plants (Calvin cycle) and C₄ plants (Hatch-Slack) respectively are:', '{"A":"OAA and 3-PGA","B":"3-PGA (3-carbon) and Oxaloacetic acid OAA (4-carbon)","C":"RuBP and PEP","D":"Malate and Glucose"}'::jsonb, 'B', 'MCQ', 'Biology', 'Photosynthesis in Higher Plants', 1, 'C₃ forms 3-PGA; C₄ forms 4-carbon OAA in mesophyll.', NULL, NULL, 'C₃ forms 3-PGA; C₄ forms 4-carbon OAA in mesophyll.', 'EASY', true),
        ('11031111-0000-4000-8000-00000000007b', 'Kranz ("wreath") anatomy of concentric bundle sheath cells with agranal chloroplasts is a hallmark of:', '{"A":"C₃ rice and wheat","B":"C₄ plants (Maize, Sugarcane, Sorghum)","C":"Algae","D":"Bryophytes"}'::jsonb, 'B', 'MCQ', 'Biology', 'Photosynthesis in Higher Plants', 1, 'Prevents wasteful photorespiration by concentrating CO₂ around RuBisCO.', NULL, NULL, 'Prevents wasteful photorespiration by concentrating CO₂ around RuBisCO.', 'EASY', true),
        ('11031111-0000-4000-8000-00000000007c', 'Photolysis (splitting) of water releasing O₂ during light reaction is directly associated with:', '{"A":"PS I in stroma","B":"PS II on the inner (lumen) side of thylakoid membrane (needs Mn²⁺, Cl⁻)","C":"Stroma lamellae","D":"Mitochondria"}'::jsonb, 'B', 'MCQ', 'Biology', 'Photosynthesis in Higher Plants', 1, '2H₂O -> 4H⁺ + O₂ + 4e⁻ replaces PS II electrons.', NULL, NULL, '2H₂O -> 4H⁺ + O₂ + 4e⁻ replaces PS II electrons.', 'EASY', true),
        ('11031111-0000-4000-8000-00000000007d', 'Cyclic photophosphorylation in stroma lamellae produces:', '{"A":"Both ATP and NADPH","B":"Only ATP (neither NADPH nor O₂)","C":"Only NADPH","D":"Glucose directly"}'::jsonb, 'B', 'MCQ', 'Biology', 'Photosynthesis in Higher Plants', 1, 'Stroma lamellae lack PS II and NADP reductase.', NULL, NULL, 'Stroma lamellae lack PS II and NADP reductase.', 'EASY', true),
        ('11031111-0000-4000-8000-00000000007e', 'Assertion (A): C₄ plants are significantly more productive and tolerate higher temperatures than C₃ plants.
Reason (R): C₄ plants completely eliminate photorespiration by using PEPcase in mesophyll and pumping malate/CO₂ to RuBisCO inside bundle sheath cells.
Choose the correct option:
A) Both A and R are true, and R is the correct explanation of A.
B) Both A and R are true, and R is not the correct explanation of A.
C) A is true but R is false.
D) A is false but R is true.', '{"A":"Both A and R are true, and R is the correct explanation of A","B":"Both A and R are true, and R is not the correct explanation of A","C":"A is true but R is false","D":"A is false but R is true"}'::jsonb, 'A', 'ASSERTION_REASON', 'Biology', 'Photosynthesis in Higher Plants', 1, 'Zero photorespiration boosts C₄ biomass yield.', NULL, NULL, 'Zero photorespiration boosts C₄ biomass yield.', 'EASY', true),
        ('11031111-0000-4000-8000-00000000007f', 'State Blackman''s Law of Limiting Factors with light intensity vs CO₂ concentration example.', NULL, NULL, 'VSA', 'Biology', 'Photosynthesis in Higher Plants', 2, 'If a chemical process is affected by more than one factor, its rate is determined by the factor nearest its minimal value. At low light, raising CO₂ won''t raise photosynthesis rate until light increases.', 'Statement (1M) + Example (1M)', NULL, 'If a chemical process is affected by more than one factor, its rate is determined by the factor nearest its minimal value. At low light, raising CO₂ won''t raise photosynthesis rate until light increases.', 'MEDIUM', true),
        ('11031111-0000-4000-8000-000000000080', 'Why is Chlorophyll-a called the chief photosynthetic pigment while Chl-b, xanthophylls, and carotenoids are accessory pigments?', NULL, NULL, 'VSA', 'Biology', 'Photosynthesis in Higher Plants', 2, 'Chl-a forms the reaction centre directly converting light energy; accessory pigments absorb wider wavelengths, funnel energy to Chl-a, and shield Chl-a from photo-oxidation.', '1M each', NULL, 'Chl-a forms the reaction centre directly converting light energy; accessory pigments absorb wider wavelengths, funnel energy to Chl-a, and shield Chl-a from photo-oxidation.', 'MEDIUM', true),
        ('11031111-0000-4000-8000-000000000081', 'Compare C₃ and C₄ plants across: Primary CO₂ acceptor, Primary CO₂ fixing enzyme, Cell type containing RuBisCO, and Photorespiration.', NULL, NULL, 'SA', 'Biology', 'Photosynthesis in Higher Plants', 3, 'C₃: RuBP (5C), RuBisCO, Mesophyll, Photorespiration high. C₄: PEP (3C), PEPcase in mesophyll while RuBisCO is in Bundle Sheath, Photorespiration negligible.', '3M', NULL, 'C₃: RuBP (5C), RuBisCO, Mesophyll, Photorespiration high. C₄: PEP (3C), PEPcase in mesophyll while RuBisCO is in Bundle Sheath, Photorespiration negligible.', 'MEDIUM', true),
        ('11031111-0000-4000-8000-000000000082', 'Explain the Chemiosmotic Hypothesis of ATP synthesis across the thylakoid membrane during light reactions.', NULL, NULL, 'SA', 'Biology', 'Photosynthesis in Higher Plants', 3, 'Proton gradient builds inside thylakoid lumen (from water splitting, PQ proton pumping across membrane, and stromal NADP⁺ reduction consuming H⁺). Flow back through CF₀-CF₁ ATP synthase drives conformational ATP synthesis.', '3 proton sources (2M) + ATP synthase (1M)', NULL, 'Proton gradient builds inside thylakoid lumen (from water splitting, PQ proton pumping across membrane, and stromal NADP⁺ reduction consuming H⁺). Flow back through CF₀-CF₁ ATP synthase drives conformational ATP synthesis.', 'MEDIUM', true),
        ('11031111-0000-4000-8000-000000000083', 'Trace the three phases of the Calvin Cycle (Carboxylation, Reduction, Regeneration). Calculate exact number of ATP and NADPH molecules consumed to synthesise ONE molecule of Glucose (6 turns of Calvin cycle) in C₃ vs C₄ plants.', NULL, NULL, 'LA', 'Biology', 'Photosynthesis in Higher Plants', 5, '3 phases cleanly explained (2.5M). Per CO₂ fixed in C₃: 3 ATP + 2 NADPH -> for 1 Glucose (6 CO₂): 18 ATP + 12 NADPH. In C₄ (2 extra ATP per CO₂ for PEP regeneration in mesophyll): 30 ATP + 12 NADPH (2.5M).', '3 phases (2.5M) + ATP/NADPH stoichiometry (2.5M)', NULL, '3 phases cleanly explained (2.5M). Per CO₂ fixed in C₃: 3 ATP + 2 NADPH -> for 1 Glucose (6 CO₂): 18 ATP + 12 NADPH. In C₄ (2 extra ATP per CO₂ for PEP regeneration in mesophyll): 30 ATP + 12 NADPH (2.5M).', 'HARD', true),
        ('11031111-0000-4000-8000-000000000084', '(i) Where did Jan Ingenhousz and Cornelius van Niel prove sunlight and H₂O (not CO₂) as O₂ source? (ii) What triggers photorespiration when RuBisCO binds O₂ instead of CO₂? (iii) Identify products of photorespiration from 5C RuBP + O₂. (iv) Optimum temperature range for C₃ vs C₄ plants.', NULL, NULL, 'CASE', 'Biology', 'Photosynthesis in Higher Plants', 4, '(i) Ingenhousz showed aquatic Hydrilla bubbles O₂ in light; van Niel (purple/green sulphur bacteria) proved O₂ comes from H₂O splitting (confirmed via ¹⁸O radioisotope). (ii) High O₂ / low CO₂ and high temperature. (iii) 1 molecule 3-PGA (3C) + 1 molecule Phosphoglycolate (2C) — wastes ATP/CO₂. (iv) C₃: 20–25°C; C₄: 30–40°C.', '4 × 1M = 4M', 'Comparing wheat and sugarcane leaves in a greenhouse reveals stark anatomical differences around vascular bundles alongside shifts in CO₂ compensation points.', '(i) Ingenhousz showed aquatic Hydrilla bubbles O₂ in light; van Niel (purple/green sulphur bacteria) proved O₂ comes from H₂O splitting (confirmed via ¹⁸O radioisotope). (ii) High O₂ / low CO₂ and high temperature. (iii) 1 molecule 3-PGA (3C) + 1 molecule Phosphoglycolate (2C) — wastes ATP/CO₂. (iv) C₃: 20–25°C; C₄: 30–40°C.', 'HARD', true),
        ('11031111-0000-4000-8000-000000000085', 'Final electron acceptor at Complex IV (cytochrome c oxidase) in mitochondrial electron transport chain is:', '{"A":"NAD⁺","B":"Molecular oxygen (O₂ forming H₂O)","C":"FAD","D":"Pyruvate"}'::jsonb, 'B', 'MCQ', 'Biology', 'Respiration in Plants', 1, 'O₂ accepts electrons + protons to form metabolic water.', NULL, NULL, 'O₂ accepts electrons + protons to form metabolic water.', 'EASY', true),
        ('11031111-0000-4000-8000-000000000086', 'Which respiratory pathway is common to both aerobic and anaerobic organisms in the cytoplasm?', '{"A":"Krebs cycle","B":"Glycolysis (EMP pathway converting Glucose -> 2 Pyruvate)","C":"Oxidative phosphorylation","D":"Fermentation"}'::jsonb, 'B', 'MCQ', 'Biology', 'Respiration in Plants', 1, '10-step cytoplasmic glycolysis needs no O₂.', NULL, NULL, '10-step cytoplasmic glycolysis needs no O₂.', 'EASY', true),
        ('11031111-0000-4000-8000-000000000087', 'Respiratory Quotient (RQ = CO₂ evolved / O₂ consumed) for carbohydrates and fats respectively is:', '{"A":"0.7 and 1.0","B":"1.0 and ~0.7 (tripalmitin)","C":"1.3 and 0.9","D":"Infinity and 0"}'::jsonb, 'B', 'MCQ', 'Biology', 'Respiration in Plants', 1, 'Balanced C₆H₁₂O₆ gives 6/6 = 1.0; Tripalmitin gives 102/145 = 0.7.', NULL, NULL, 'Balanced C₆H₁₂O₆ gives 6/6 = 1.0; Tripalmitin gives 102/145 = 0.7.', 'EASY', true),
        ('11031111-0000-4000-8000-000000000088', 'Net ATP and NADH+H⁺ directly gained during Glycolysis of 1 molecule of Glucose are:', '{"A":"2 ATP + 2 NADH+H⁺","B":"4 ATP + 2 NADH+H⁺","C":"38 ATP","D":"1 ATP + 1 NADH+H⁺"}'::jsonb, 'A', 'MCQ', 'Biology', 'Respiration in Plants', 1, '2 ATP invested, 4 ATP substrate-level produced -> net 2 ATP + 2 NADH.', NULL, NULL, '2 ATP invested, 4 ATP substrate-level produced -> net 2 ATP + 2 NADH.', 'EASY', true),
        ('11031111-0000-4000-8000-000000000089', 'Which enzyme converts pyruvate to Acetyl-CoA during link reaction inside mitochondrial matrix?', '{"A":"Hexokinase","B":"Pyruvate dehydrogenase (requiring Mg²⁺, CoA, NAD⁺)","C":"Succinate dehydrogenase","D":"RuBisCO"}'::jsonb, 'B', 'MCQ', 'Biology', 'Respiration in Plants', 1, 'Releases 2 CO₂ + 2 NADH per glucose.', NULL, NULL, 'Releases 2 CO₂ + 2 NADH per glucose.', 'EASY', true),
        ('11031111-0000-4000-8000-00000000008a', 'Assertion (A): Respiration is more accurately described as an amphibolic pathway rather than purely catabolic.
Reason (R): Respiratory intermediates like Acetyl-CoA and α-ketoglutarate are withdrawn for synthesis (anabolism) of fatty acids and amino acids while substrates break down.
Choose the correct option:
A) Both A and R are true, and R is the correct explanation of A.
B) Both A and R are true, and R is not the correct explanation of A.
C) A is true but R is false.
D) A is false but R is true.', '{"A":"Both A and R are true, and R is the correct explanation of A","B":"Both A and R are true, and R is not the correct explanation of A","C":"A is true but R is false","D":"A is false but R is true"}'::jsonb, 'A', 'ASSERTION_REASON', 'Biology', 'Respiration in Plants', 1, 'Simultaneous breakdown & biosynthetic precursor supply = amphibolic.', NULL, NULL, 'Simultaneous breakdown & biosynthetic precursor supply = amphibolic.', 'EASY', true),
        ('11031111-0000-4000-8000-00000000008b', 'What is Substrate-Level Phosphorylation? Give two steps where it occurs in aerobic respiration.', NULL, NULL, 'VSA', 'Biology', 'Respiration in Plants', 2, 'Direct enzymatic transfer of phosphate from a high-energy substrate onto ADP/GDP forming ATP/GTP without ETC (e.g., PEP -> Pyruvate in glycolysis; Succinyl-CoA -> Succinic acid in Krebs cycle).', 'Definition (1M) + 2 steps (1M)', NULL, 'Direct enzymatic transfer of phosphate from a high-energy substrate onto ADP/GDP forming ATP/GTP without ETC (e.g., PEP -> Pyruvate in glycolysis; Succinyl-CoA -> Succinic acid in Krebs cycle).', 'MEDIUM', true),
        ('11031111-0000-4000-8000-00000000008c', 'Why is less than 7% of energy in glucose released during alcoholic or lactic acid fermentation?', NULL, NULL, 'VSA', 'Biology', 'Respiration in Plants', 2, 'Incomplete oxidation leaves most chemical energy trapped inside ethanol or lactic acid, and NADH is re-oxidised without passing electrons down the mitochondrial ETC.', 'Incomplete oxidation (1M) + No ETC ATP (1M)', NULL, 'Incomplete oxidation leaves most chemical energy trapped inside ethanol or lactic acid, and NADH is re-oxidised without passing electrons down the mitochondrial ETC.', 'MEDIUM', true),
        ('11031111-0000-4000-8000-00000000008d', 'Trace the Fate of Pyruvate under anaerobic conditions in (i) Yeast and (ii) Striated muscle cells during heavy exercise.', NULL, NULL, 'SA', 'Biology', 'Respiration in Plants', 3, 'Yeast: Pyruvate --(decarboxylase)-> Acetaldehyde + CO₂ -> Ethanol (oxidising NADH -> NAD⁺). Muscle: Pyruvate --(lactate dehydrogenase)-> Lactic acid (no CO₂ released, NAD⁺ regenerated).', '1.5M each', NULL, 'Yeast: Pyruvate --(decarboxylase)-> Acetaldehyde + CO₂ -> Ethanol (oxidising NADH -> NAD⁺). Muscle: Pyruvate --(lactate dehydrogenase)-> Lactic acid (no CO₂ released, NAD⁺ regenerated).', 'MEDIUM', true),
        ('11031111-0000-4000-8000-00000000008e', 'Explain the roles of Complex I, II, III, IV, and Complex V (ATP Synthase F₀-F₁) in mitochondrial oxidative phosphorylation.', NULL, NULL, 'SA', 'Biology', 'Respiration in Plants', 3, 'Complex I oxidises NADH; Complex II (SDH) oxidises FADH₂; Ubiquinone -> Complex III -> Cytochrome c -> Complex IV reduces O₂ -> H₂O; Proton gradient across inner membrane drives F₀-F₁ ATP synthase.', '3M', NULL, 'Complex I oxidises NADH; Complex II (SDH) oxidises FADH₂; Ubiquinone -> Complex III -> Cytochrome c -> Complex IV reduces O₂ -> H₂O; Proton gradient across inner membrane drives F₀-F₁ ATP synthase.', 'MEDIUM', true),
        ('11031111-0000-4000-8000-00000000008f', 'Trace the complete Tricarboxylic Acid (Krebs) Cycle starting from Acetyl-CoA condensation with Oxaloacetic acid (OAA). Construct a neat energy balance sheet calculating net ATP yield per molecule of Glucose (assuming 1 NADH = 3 ATP, 1 FADH₂ = 2 ATP, or modern 2.5/1.5).', NULL, NULL, 'LA', 'Biology', 'Respiration in Plants', 5, 'Krebs 8 steps (citrate -> isocitrate -> α-KG -> succinyl-CoA -> succinate -> fumarate -> malate -> OAA; yields 3 NADH, 1 FADH₂, 1 GTP per turn; ×2 per glucose) (3M). Total ATP balance sheet: Glycolysis (2 ATP + 2 NADH = 8), Link (2 NADH = 6), Krebs (2 GTP + 6 NADH + 2 FADH₂ = 24) -> Net 38 ATP (or 36 with glycerol-phosphate shuttle / ~30–32 modern) (2M).', 'Krebs cycle steps (3M) + ATP accounting (2M)', NULL, 'Krebs 8 steps (citrate -> isocitrate -> α-KG -> succinyl-CoA -> succinate -> fumarate -> malate -> OAA; yields 3 NADH, 1 FADH₂, 1 GTP per turn; ×2 per glucose) (3M). Total ATP balance sheet: Glycolysis (2 ATP + 2 NADH = 8), Link (2 NADH = 6), Krebs (2 GTP + 6 NADH + 2 FADH₂ = 24) -> Net 38 ATP (or 36 with glycerol-phosphate shuttle / ~30–32 modern) (2M).', 'HARD', true),
        ('11031111-0000-4000-8000-000000000090', '(i) Calculate RQ for organic acids like malic/oxalic acid and state why it exceeds 1. (ii) Which step in Glycolysis consumes ATP (preparatory phase)? (iii) What acts as mobile electron carrier between Complex III and IV on outer surface of inner membrane? (iv) Define Fermentation poison threshold in yeast.', NULL, NULL, 'CASE', 'Biology', 'Respiration in Plants', 4, '(i) > 1 (e.g., 4CO₂/3O₂ = 1.33) because organic acids already have high intrinsic oxygen needing less external O₂. (ii) Glucose -> G6P (Hexokinase) and F6P -> F-1,6-BP (PFK). (iii) Cytochrome c. (iv) Yeast poison themselves to death once alcohol reaches ~13%.', '4 × 1M = 4M', 'Respirometer experiments measuring O₂ uptake vs CO₂ output across germinating pea seeds, castor oil seeds, and succulent leaves show distinct shifts in RQ values.', '(i) > 1 (e.g., 4CO₂/3O₂ = 1.33) because organic acids already have high intrinsic oxygen needing less external O₂. (ii) Glucose -> G6P (Hexokinase) and F6P -> F-1,6-BP (PFK). (iii) Cytochrome c. (iv) Yeast poison themselves to death once alcohol reaches ~13%.', 'HARD', true),
        ('11031111-0000-4000-8000-000000000091', 'Apical dominance (suppression of lateral buds by growing shoot tip) is caused by:', '{"A":"Cytokinin","B":"Auxin (IAA)","C":"Gibberellin","D":"Ethylene"}'::jsonb, 'B', 'MCQ', 'Biology', 'Plant Growth and Development', 1, 'Removing shoot tip allows lateral bushiness (tea plantations/hedges); antagonised by cytokinins.', NULL, NULL, 'Removing shoot tip allows lateral bushiness (tea plantations/hedges); antagonised by cytokinins.', 'EASY', true),
        ('11031111-0000-4000-8000-000000000092', '"Bolting" (internode elongation just prior to flowering in rosette plants like cabbage & beet) is promoted by:', '{"A":"Abscisic acid","B":"Gibberellins (GA₃)","C":"Auxin","D":"Ethylene"}'::jsonb, 'B', 'MCQ', 'Biology', 'Plant Growth and Development', 1, 'Gibberellins also boost sugarcane stem yield by up to 20 tonnes/acre.', NULL, NULL, 'Gibberellins also boost sugarcane stem yield by up to 20 tonnes/acre.', 'EASY', true),
        ('11031111-0000-4000-8000-000000000093', 'Gaseous plant growth regulator responsible for fruit ripening and triple response in seedlings is:', '{"A":"IAA","B":"Ethylene (C₂H₄)","C":"ABA","D":"Kinetin"}'::jsonb, 'B', 'MCQ', 'Biology', 'Plant Growth and Development', 1, 'Ethephon slowly releases ethylene accelerating tomato/apple ripening.', NULL, NULL, 'Ethephon slowly releases ethylene accelerating tomato/apple ripening.', 'EASY', true),
        ('11031111-0000-4000-8000-000000000094', 'Stress hormone that closes stomata during drought and induces seed dormancy is:', '{"A":"Gibberellic acid","B":"Abscisic acid (ABA)","C":"Cytokinin","D":"2,4-D"}'::jsonb, 'B', 'MCQ', 'Biology', 'Plant Growth and Development', 1, 'ABA acts antagonistically to GAs.', NULL, NULL, 'ABA acts antagonistically to GAs.', 'EASY', true),
        ('11031111-0000-4000-8000-000000000095', 'Synthetic auxin widely used by farmers as a dicot-selective weedicide on cereal lawns is:', '{"A":"Kinetin","B":"2,4-D (2,4-Dichlorophenoxyacetic acid)","C":"Ethephon","D":"Zeatin"}'::jsonb, 'B', 'MCQ', 'Biology', 'Plant Growth and Development', 1, '2,4-D kills broad-leaved dicot weeds without harming monocot grasses.', NULL, NULL, '2,4-D kills broad-leaved dicot weeds without harming monocot grasses.', 'EASY', true),
        ('11031111-0000-4000-8000-000000000096', 'Assertion (A): Development in plants is defined as the sum of growth and differentiation.
Reason (R): Plants exhibit plasticity — following different pathways in response to environment (like heterophylly in buttercup and cotton).
Choose the correct option:
A) Both A and R are true, and R is the correct explanation of A.
B) Both A and R are true, and R is not the correct explanation of A.
C) A is true but R is false.
D) A is false but R is true.', '{"A":"Both A and R are true, and R is the correct explanation of A","B":"Both A and R are true, and R is not the correct explanation of A","C":"A is true but R is false","D":"A is false but R is true"}'::jsonb, 'B', 'ASSERTION_REASON', 'Biology', 'Plant Growth and Development', 1, 'Both true; plasticity demonstrates adaptive developmental flexibility.', NULL, NULL, 'Both true; plasticity demonstrates adaptive developmental flexibility.', 'EASY', true),
        ('11031111-0000-4000-8000-000000000097', 'Distinguish between Differentiation, Dedifferentiation, and Redifferentiation with one plant example each.', NULL, NULL, 'VSA', 'Biology', 'Plant Growth and Development', 2, 'Differentiation: cells mature for specific function (tracheary elements). Dedifferentiation: mature living cells regain division power (interfascicular cambium/cork cambium). Redifferentiation: products mature again into secondary xylem/cortex.', '2M', NULL, 'Differentiation: cells mature for specific function (tracheary elements). Dedifferentiation: mature living cells regain division power (interfascicular cambium/cork cambium). Redifferentiation: products mature again into secondary xylem/cortex.', 'MEDIUM', true),
        ('11031111-0000-4000-8000-000000000098', 'What is Richmond-Lang effect and which hormone causes it?', NULL, NULL, 'VSA', 'Biology', 'Plant Growth and Development', 2, 'Delay of leaf senescence (yellowing) by nutrient mobilisation — caused by Cytokinins.', '1M each', NULL, 'Delay of leaf senescence (yellowing) by nutrient mobilisation — caused by Cytokinins.', 'MEDIUM', true),
        ('11031111-0000-4000-8000-000000000099', 'Compare Arithmetic Growth vs Geometric Growth mathematically with equations and curves.', NULL, NULL, 'SA', 'Biology', 'Plant Growth and Development', 3, 'Arithmetic: only one daughter cell keeps dividing -> L_t = L₀ + rt (linear curve, e.g., root elongation). Geometric: both daughters divide exponentially -> W₁ = W₀ e^(rt) (sigmoid S-curve: lag, log/exponential, stationary phases).', '1.5M each', NULL, 'Arithmetic: only one daughter cell keeps dividing -> L_t = L₀ + rt (linear curve, e.g., root elongation). Geometric: both daughters divide exponentially -> W₁ = W₀ e^(rt) (sigmoid S-curve: lag, log/exponential, stationary phases).', 'MEDIUM', true),
        ('11031111-0000-4000-8000-00000000009a', 'State three agricultural applications of Gibberellins and three of Ethylene.', NULL, NULL, 'SA', 'Biology', 'Plant Growth and Development', 3, 'GAs: elongate apple/grape stalks, boost sugarcane yield, speed up malting in brewing / early seed production in conifers. Ethylene: fruit ripening (ethephon), break potato tuber/peanut dormancy, thin cotton/cherry/walnut & induce female flowers in cucumber.', '1.5M each', NULL, 'GAs: elongate apple/grape stalks, boost sugarcane yield, speed up malting in brewing / early seed production in conifers. Ethylene: fruit ripening (ethephon), break potato tuber/peanut dormancy, thin cotton/cherry/walnut & induce female flowers in cucumber.', 'MEDIUM', true),
        ('11031111-0000-4000-8000-00000000009b', 'Trace the discovery of all five Plant Growth Regulators (Auxin by Darwin/Went, Gibberellin from "bakanae" foolish seedling disease/Kurosawa, Cytokinin by Skoog & Miller, ABA, Ethylene by Cousins) and summarise one antagonistic pair and one synergistic interaction.', NULL, NULL, 'LA', 'Biology', 'Plant Growth and Development', 5, '5 discoveries accurately traced (3.5M). Antagonistic: GA breaks dormancy vs ABA enforces dormancy (or Auxin apical dominance vs Cytokinin lateral bud growth). Synergistic: Auxin + Cytokinin in tissue culture morphogenesis (1.5M).', '5 PGR discoveries (3.5M) + Interactions (1.5M)', NULL, '5 discoveries accurately traced (3.5M). Antagonistic: GA breaks dormancy vs ABA enforces dormancy (or Auxin apical dominance vs Cytokinin lateral bud growth). Synergistic: Auxin + Cytokinin in tissue culture morphogenesis (1.5M).', 'HARD', true),
        ('11031111-0000-4000-8000-00000000009c', '(i) Define Absolute Growth Rate (AGR) vs Relative Growth Rate (RGR). (ii) If Leaf A grows from 5 cm² to 10 cm² and Leaf B from 50 cm² to 55 cm² in the same day, compare their AGR and RGR. (iii) Explain Plasticity citing heterophylly in Ranunculus (buttercup). (iv) Name the natural cytokinin isolated from corn kernels.', NULL, NULL, 'CASE', 'Biology', 'Plant Growth and Development', 4, '(i) AGR = total growth per unit time; RGR = growth per unit time expressed per initial parameter base. (ii) Both have equal AGR = 5 cm²/day, but Leaf A has RGR = 100% vs Leaf B RGR = 10%. (iii) Submerged vs terrestrial leaves develop different shapes in response to habitat. (iv) Zeatin.', '4 × 1M = 4M', 'Botany students plot root-tip elongation alongside fresh leaf surface measurements over seven days to contrast linear arithmetic vs exponential sigmoid growth curves.', '(i) AGR = total growth per unit time; RGR = growth per unit time expressed per initial parameter base. (ii) Both have equal AGR = 5 cm²/day, but Leaf A has RGR = 100% vs Leaf B RGR = 10%. (iii) Submerged vs terrestrial leaves develop different shapes in response to habitat. (iv) Zeatin.', 'HARD', true),
        ('11031111-0000-4000-8000-00000000009d', 'Volume of air remaining in the lungs even after a forcible expiration (cannot be measured by simple spirometer) is:', '{"A":"Tidal volume (500 mL)","B":"Residual Volume (RV, ~1100–1200 mL)","C":"Expiratory Reserve Volume","D":"Vital Capacity"}'::jsonb, 'B', 'MCQ', 'Biology', 'Breathing and Exchange of Gases', 1, 'RV prevents lung collapse (~1100–1200 mL).', NULL, NULL, 'RV prevents lung collapse (~1100–1200 mL).', 'EASY', true),
        ('11031111-0000-4000-8000-00000000009e', 'Percentage of CO₂ transported in blood chemically as bicarbonate ions (HCO₃⁻) and carbaminohaemoglobin respectively is:', '{"A":"7% and 23%","B":"70% (HCO₃⁻) and 20–25% (Hb)","C":"97% and 3%","D":"50% and 50%"}'::jsonb, 'B', 'MCQ', 'Biology', 'Breathing and Exchange of Gases', 1, '~70% as bicarbonate (via carbonic anhydrase), ~20–25% as carbaminohaemoglobin, ~7% dissolved in plasma.', NULL, NULL, '~70% as bicarbonate (via carbonic anhydrase), ~20–25% as carbaminohaemoglobin, ~7% dissolved in plasma.', 'EASY', true),
        ('11031111-0000-4000-8000-00000000009f', 'Oxygen-haemoglobin dissociation curve shifts to the RIGHT (promoting O₂ unloading in tissues) when:', '{"A":"pO₂ is high and pCO₂ low","B":"pCO₂ is high, H⁺ high (low pH), and temperature high (Bohr effect)","C":"Fetal Hb is present","D":"CO binds"}'::jsonb, 'B', 'MCQ', 'Biology', 'Breathing and Exchange of Gases', 1, 'Metabolically active tissues have high CO₂, H⁺, temperature -> right shift.', NULL, NULL, 'Metabolically active tissues have high CO₂, H⁺, temperature -> right shift.', 'EASY', true),
        ('11031111-0000-4000-8000-0000000000a0', 'Respiratory rhythm centre regulating normal breathing rate is located in:', '{"A":"Cerebellum","B":"Medulla oblongata (modulated by Pneumotaxic centre in Pons)","C":"Hypothalamus","D":"Spinal cord"}'::jsonb, 'B', 'MCQ', 'Biology', 'Breathing and Exchange of Gases', 1, 'Medulla rhythm centre + Pons pneumotaxic switch-off.', NULL, NULL, 'Medulla rhythm centre + Pons pneumotaxic switch-off.', 'EASY', true),
        ('11031111-0000-4000-8000-0000000000a1', 'Occupational respiratory disorder caused by inhaling fine silica/asbestos stone-grinding dust leading to lung fibrosis is:', '{"A":"Emphysema","B":"Silicosis / Asbestosis","C":"Asthma","D":"Pneumonia"}'::jsonb, 'B', 'MCQ', 'Biology', 'Breathing and Exchange of Gases', 1, 'Chronic dust triggers proliferation of fibrous tissue.', NULL, NULL, 'Chronic dust triggers proliferation of fibrous tissue.', 'EASY', true),
        ('11031111-0000-4000-8000-0000000000a2', 'Assertion (A): Smoking cigarettes frequently leads to Emphysema, a chronic respiratory disorder.
Reason (R): Smoke toxins damage delicate alveolar walls, drastically decreasing respiratory surface area for gas exchange.
Choose the correct option:
A) Both A and R are true, and R is the correct explanation of A.
B) Both A and R are true, and R is not the correct explanation of A.
C) A is true but R is false.
D) A is false but R is true.', '{"A":"Both A and R are true, and R is the correct explanation of A","B":"Both A and R are true, and R is not the correct explanation of A","C":"A is true but R is false","D":"A is false but R is true"}'::jsonb, 'A', 'ASSERTION_REASON', 'Biology', 'Breathing and Exchange of Gases', 1, 'Alveolar wall breakdown reduces gas diffusion area.', NULL, NULL, 'Alveolar wall breakdown reduces gas diffusion area.', 'EASY', true),
        ('11031111-0000-4000-8000-0000000000a3', 'Define Vital Capacity (VC) and Total Lung Capacity (TLC) in terms of respiratory volumes.', NULL, NULL, 'VSA', 'Biology', 'Breathing and Exchange of Gases', 2, 'VC = ERV + TV + IRV (~4000–4600 mL). TLC = VC + RV (total volume accommodated after forced inspiration).', '1M each', NULL, 'VC = ERV + TV + IRV (~4000–4600 mL). TLC = VC + RV (total volume accommodated after forced inspiration).', 'MEDIUM', true),
        ('11031111-0000-4000-8000-0000000000a4', 'Why is the diffusion membrane of alveoli only < 1 mm thick? Name its three layers.', NULL, NULL, 'VSA', 'Biology', 'Breathing and Exchange of Gases', 2, 'Thinness maximises rapid O₂/CO₂ partial-pressure diffusion. Three layers: thin squamous epithelium of alveoli, endothelium of alveolar capillaries, and fused basement substance between them.', 'Reason + 3 layers (2M)', NULL, 'Thinness maximises rapid O₂/CO₂ partial-pressure diffusion. Three layers: thin squamous epithelium of alveoli, endothelium of alveolar capillaries, and fused basement substance between them.', 'MEDIUM', true),
        ('11031111-0000-4000-8000-0000000000a5', 'Explain the Mechanism of Inspiration and Expiration involving diaphragm, external intercostal muscles, and intra-pulmonary pressure.', NULL, NULL, 'SA', 'Biology', 'Breathing and Exchange of Gases', 3, 'Inspiration: diaphragm contracts & flattens, external intercostals lift ribs/sternum upward & outward -> thoracic volume rises -> intra-pulmonary pressure drops below atmospheric -> air rushes in. Expiration reverses passively via muscle relaxation.', '1.5M each', NULL, 'Inspiration: diaphragm contracts & flattens, external intercostals lift ribs/sternum upward & outward -> thoracic volume rises -> intra-pulmonary pressure drops below atmospheric -> air rushes in. Expiration reverses passively via muscle relaxation.', 'MEDIUM', true),
        ('11031111-0000-4000-8000-0000000000a6', 'Why does Carbonic Anhydrase inside RBCs play a crucial double role in CO₂ transport at tissues vs alveoli?', NULL, NULL, 'SA', 'Biology', 'Breathing and Exchange of Gases', 3, 'In tissues (high pCO₂), enzyme rapidly converts CO₂ + H₂O -> H₂CO₃ -> H⁺ + HCO₃⁻ (chloride shift into plasma). At alveoli (low pCO₂), reaction reverses releasing CO₂ for exhalation.', '3M', NULL, 'In tissues (high pCO₂), enzyme rapidly converts CO₂ + H₂O -> H₂CO₃ -> H⁺ + HCO₃⁻ (chloride shift into plasma). At alveoli (low pCO₂), reaction reverses releasing CO₂ for exhalation.', 'MEDIUM', true),
        ('11031111-0000-4000-8000-0000000000a7', 'Give the partial pressures (pO₂ and pCO₂ in mmHg) at Atmospheric Air, Alveoli, Deoxygenated Blood, Oxygenated Blood, and Tissues. Trace Oxygen binding in lungs and dissociation in tissues using the sigmoid Oxygen-Haemoglobin Dissociation Curve.', NULL, NULL, 'LA', 'Biology', 'Breathing and Exchange of Gases', 5, 'Partial pressure table (2.5M: Alveoli pO₂ 104/pCO₂ 40, Deoxy 40/45, Oxy 95/40, Tissue 40/45). Sigmoid cooperative binding curve explained + 100 mL oxygenated blood delivers ~5 mL O₂ to tissues under normal conditions (2.5M).', 'Table (2.5M) + Curve & delivery (2.5M)', NULL, 'Partial pressure table (2.5M: Alveoli pO₂ 104/pCO₂ 40, Deoxy 40/45, Oxy 95/40, Tissue 40/45). Sigmoid cooperative binding curve explained + 100 mL oxygenated blood delivers ~5 mL O₂ to tissues under normal conditions (2.5M).', 'HARD', true),
        ('11031111-0000-4000-8000-0000000000a8', '(i) Calculate Inspiratory Capacity (IC) if TV = 500 mL and IRV = 2500 mL. (ii) Distinguish Asthma vs Emphysema. (iii) Why are chemosensitive receptors near medulla stimulated primarily by CO₂/H⁺ rather than O₂? (iv) How many O₂ molecules can one haemoglobin tetramer bind?', NULL, NULL, 'CASE', 'Biology', 'Breathing and Exchange of Gases', 4, '(i) IC = TV + IRV = 3000 mL. (ii) Asthma: allergic wheezing/bronchospasm; Emphysema: permanent alveolar wall destruction. (iii) Medullary chemoreceptors & aortic/carotid bodies detect slight rise in CO₂ and H⁺ immediately to increase ventilation. (iv) Maximum 4 O₂ molecules (one per Fe²⁺ haem).', '4 × 1M = 4M', 'A clinical spirometry test evaluates lung volumes of a marathon runner alongside a chronic smoker experiencing shortness of breath and elevated arterial pCO₂.', '(i) IC = TV + IRV = 3000 mL. (ii) Asthma: allergic wheezing/bronchospasm; Emphysema: permanent alveolar wall destruction. (iii) Medullary chemoreceptors & aortic/carotid bodies detect slight rise in CO₂ and H⁺ immediately to increase ventilation. (iv) Maximum 4 O₂ molecules (one per Fe²⁺ haem).', 'HARD', true),
        ('11031111-0000-4000-8000-0000000000a9', 'Which blood cells are nucleated and help phagocytose pathogens vs produce allergic/inflammatory histamine?', '{"A":"RBC and Platelets","B":"Neutrophils (phagocytic) and Basophils (histamine/serotonin/heparin)","C":"Eosinophils only","D":"Lymphocytes only"}'::jsonb, 'B', 'MCQ', 'Biology', 'Body Fluids and Circulation', 1, 'Neutrophils (60-65% WBC) are top phagocytes; Basophils trigger inflammation.', NULL, NULL, 'Neutrophils (60-65% WBC) are top phagocytes; Basophils trigger inflammation.', 'EASY', true),
        ('11031111-0000-4000-8000-0000000000aa', 'A person with blood group AB⁺ is called a universal recipient because their plasma contains:', '{"A":"Both anti-A and anti-B antibodies","B":"Neither anti-A nor anti-B antibodies (and possesses A, B, Rh antigens on RBCs)","C":"Only Rh antibody","D":"No antigens"}'::jsonb, 'B', 'MCQ', 'Biology', 'Body Fluids and Circulation', 1, 'Absence of plasma antibodies avoids agglutination of donor RBCs.', NULL, NULL, 'Absence of plasma antibodies avoids agglutination of donor RBCs.', 'EASY', true),
        ('11031111-0000-4000-8000-0000000000ab', 'Pacemaker of the human heart generating ~70–75 action potentials/min spontaneously is:', '{"A":"AV node","B":"SA node (Sino-atrial node in upper right atrium)","C":"Bundle of His","D":"Purkinje fibres"}'::jsonb, 'B', 'MCQ', 'Biology', 'Body Fluids and Circulation', 1, 'SAN sets rhythmic cardiac excitation.', NULL, NULL, 'SAN sets rhythmic cardiac excitation.', 'EASY', true),
        ('11031111-0000-4000-8000-0000000000ac', 'In a standard ECG, the QRS complex represents:', '{"A":"Atrial depolarisation","B":"Ventricular depolarisation (initiating ventricular systole)","C":"Ventricular repolarisation","D":"Joint diastole"}'::jsonb, 'B', 'MCQ', 'Biology', 'Body Fluids and Circulation', 1, 'P wave = atrial depolarisation; QRS = ventricular depolarisation; T = ventricular repolarisation.', NULL, NULL, 'P wave = atrial depolarisation; QRS = ventricular depolarisation; T = ventricular repolarisation.', 'EASY', true),
        ('11031111-0000-4000-8000-0000000000ad', '"Lub" (first) and "Dub" (second) heart sounds during each cardiac cycle are caused respectively by closure of:', '{"A":"Semilunar valves; AV valves","B":"Tricuspid & Bicuspid (AV) valves; Semilunar valves","C":"SA node; AV node","D":"Vena cava; Aorta"}'::jsonb, 'B', 'MCQ', 'Biology', 'Body Fluids and Circulation', 1, 'Lub marks start of ventricular systole; Dub marks ventricular diastole.', NULL, NULL, 'Lub marks start of ventricular systole; Dub marks ventricular diastole.', 'EASY', true),
        ('11031111-0000-4000-8000-0000000000ae', 'Assertion (A): Erythroblastosis foetalis can endanger a second Rh⁺ foetus carried by an Rh⁻ mother.
Reason (R): During first delivery, mixing of Rh⁺ foetal blood stimulates anti-Rh antibodies in the Rh⁻ mother, which can cross the placenta in subsequent pregnancies and destroy foetal RBCs.
Choose the correct option:
A) Both A and R are true, and R is the correct explanation of A.
B) Both A and R are true, and R is not the correct explanation of A.
C) A is true but R is false.
D) A is false but R is true.', '{"A":"Both A and R are true, and R is the correct explanation of A","B":"Both A and R are true, and R is not the correct explanation of A","C":"A is true but R is false","D":"A is false but R is true"}'::jsonb, 'A', 'ASSERTION_REASON', 'Biology', 'Body Fluids and Circulation', 1, 'Prevented by anti-Rh antibody (RhoGAM) injection immediately after first delivery.', NULL, NULL, 'Prevented by anti-Rh antibody (RhoGAM) injection immediately after first delivery.', 'EASY', true),
        ('11031111-0000-4000-8000-0000000000af', 'Define Stroke Volume and Cardiac Output. Calculate cardiac output at 72 beats/min and 70 mL stroke volume.', NULL, NULL, 'VSA', 'Biology', 'Body Fluids and Circulation', 2, 'Stroke volume (~70 mL): blood pumped by each ventricle per beat. Cardiac output = SV × HR = 70 × 72 = 5040 mL/min (~5 L/min).', '1M each', NULL, 'Stroke volume (~70 mL): blood pumped by each ventricle per beat. Cardiac output = SV × HR = 70 × 72 = 5040 mL/min (~5 L/min).', 'MEDIUM', true),
        ('11031111-0000-4000-8000-0000000000b0', 'What is Lymph and state two vital functions of the lymphatic system.', NULL, NULL, 'VSA', 'Biology', 'Body Fluids and Circulation', 2, 'Colourless interstitial fluid lacking RBCs and large proteins drained by lymphatics. Carries specialised lymphocytes for immune response and absorbs digested fats via intestinal lacteals.', '1M each', NULL, 'Colourless interstitial fluid lacking RBCs and large proteins drained by lymphatics. Carries specialised lymphocytes for immune response and absorbs digested fats via intestinal lacteals.', 'MEDIUM', true),
        ('11031111-0000-4000-8000-0000000000b1', 'Explain the Blood Clotting (Coagulation) cascade involving Thrombokinase, Prothrombin, Fibrinogen, and Ca²⁺ ions.', NULL, NULL, 'SA', 'Biology', 'Body Fluids and Circulation', 3, 'Injured platelets/tissues release thromboplastins activating enzyme complex Thrombokinase -> converts inactive Prothrombin to active Thrombin (needs Ca²⁺) -> Thrombin converts soluble Fibrinogen into insoluble Fibrin meshwork trapping blood cells.', 'Cascade steps cleanly (3M)', NULL, 'Injured platelets/tissues release thromboplastins activating enzyme complex Thrombokinase -> converts inactive Prothrombin to active Thrombin (needs Ca²⁺) -> Thrombin converts soluble Fibrinogen into insoluble Fibrin meshwork trapping blood cells.', 'MEDIUM', true),
        ('11031111-0000-4000-8000-0000000000b2', 'Distinguish between Coronary Artery Disease (Atherosclerosis), Angina pectoris, and Heart Failure.', NULL, NULL, 'SA', 'Biology', 'Body Fluids and Circulation', 3, 'CAD: Ca/fat/cholesterol plaques narrow coronary lumens. Angina: acute chest pain when heart muscle gets insufficient O₂. Heart failure: heart fails to pump blood effectively enough to meet body needs.', '1M × 3', NULL, 'CAD: Ca/fat/cholesterol plaques narrow coronary lumens. Angina: acute chest pain when heart muscle gets insufficient O₂. Heart failure: heart fails to pump blood effectively enough to meet body needs.', 'MEDIUM', true),
        ('11031111-0000-4000-8000-0000000000b3', 'Explain the complete Cardiac Cycle (0.8 seconds at 72 bpm) across Joint Diastole, Atrial Systole, and Ventricular Systole, linking AV/semilunar valve events and ECG waves (P, QRS, T). Draw/explain Pulmonary vs Systemic Double Circulation.', NULL, NULL, 'LA', 'Biology', 'Body Fluids and Circulation', 5, 'Joint diastole (0.4s: all relaxed, 70% passive ventricular filling), Atrial systole (0.1s: P wave, +30% filling), Ventricular systole (0.3s: QRS, AV valves shut "Lub", semilunar open pushing stroke volume, followed by T wave & semilunar shut "Dub") (3.5M). Double circulation keeps O₂-rich systemic and O₂-poor pulmonary circuits separate (1.5M).', 'Cardiac cycle (3.5M) + Double circulation (1.5M)', NULL, 'Joint diastole (0.4s: all relaxed, 70% passive ventricular filling), Atrial systole (0.1s: P wave, +30% filling), Ventricular systole (0.3s: QRS, AV valves shut "Lub", semilunar open pushing stroke volume, followed by T wave & semilunar shut "Dub") (3.5M). Double circulation keeps O₂-rich systemic and O₂-poor pulmonary circuits separate (1.5M).', 'HARD', true),
        ('11031111-0000-4000-8000-0000000000b4', '(i) Count of RBCs, WBCs, and Platelets per mm³ of healthy human blood. (ii) Which plasma proteins aid clotting, osmotic balance, and immunity respectively? (iii) Why does AV bundle pause impulse briefly at AV node? (iv) Effect of sympathetic vs parasympathetic neural signals on heart rate.', NULL, NULL, 'CASE', 'Biology', 'Body Fluids and Circulation', 4, '(i) RBC 5–5.5 million; WBC 6000–8000; Platelets 1.5–3.5 lakh/mm³. (ii) Fibrinogen (clotting), Albumin (osmotic balance), Globulin (defence). (iii) Allows atria to finish contracting and empty blood into ventricles before ventricular systole. (iv) Sympathetic increases HR & cardiac output; Parasympathetic (vagus) lowers HR.', '4 × 1M = 4M', 'A cardiology technician records a 12-lead ECG and blood panel while assessing valve timing, pacemaker conduction, and Rh compatibility.', '(i) RBC 5–5.5 million; WBC 6000–8000; Platelets 1.5–3.5 lakh/mm³. (ii) Fibrinogen (clotting), Albumin (osmotic balance), Globulin (defence). (iii) Allows atria to finish contracting and empty blood into ventricles before ventricular systole. (iv) Sympathetic increases HR & cardiac output; Parasympathetic (vagus) lowers HR.', 'HARD', true),
        ('11031111-0000-4000-8000-0000000000b5', 'Order of toxicity (highest to lowest) and water requirement among nitrogenous wastes is:', '{"A":"Urea > Ammonia > Uric acid","B":"Ammonia > Urea > Uric acid","C":"Uric acid > Urea > Ammonia","D":"Urea > Uric acid > Ammonia"}'::jsonb, 'B', 'MCQ', 'Biology', 'Excretory Products and their Elimination', 1, 'Aquatic bony fish = ammonotelic; Mammals = ureotelic; Birds/Reptiles/Insects = uricotelic.', NULL, NULL, 'Aquatic bony fish = ammonotelic; Mammals = ureotelic; Birds/Reptiles/Insects = uricotelic.', 'EASY', true),
        ('11031111-0000-4000-8000-0000000000b6', 'Normal Glomerular Filtration Rate (GFR) in a healthy adult human is approximately:', '{"A":"125 mL/min (180 litres/day)","B":"1.5 litres/day","C":"50 mL/min","D":"500 mL/min"}'::jsonb, 'A', 'MCQ', 'Biology', 'Excretory Products and their Elimination', 1, '99% of the 180 L/day filtrate is reabsorbed leaving ~1.5 L urine/day.', NULL, NULL, '99% of the 180 L/day filtrate is reabsorbed leaving ~1.5 L urine/day.', 'EASY', true),
        ('11031111-0000-4000-8000-0000000000b7', 'Presence of glucose and ketone bodies in human urine respectively are diagnostic markers of:', '{"A":"Uremia","B":"Diabetes mellitus (glycosuria + ketonuria)","C":"Renal calculi","D":"Glomerulonephritis"}'::jsonb, 'B', 'MCQ', 'Biology', 'Excretory Products and their Elimination', 1, 'Insulin deficiency spills glucose and ketones into urine.', NULL, NULL, 'Insulin deficiency spills glucose and ketones into urine.', 'EASY', true),
        ('11031111-0000-4000-8000-0000000000b8', 'Antidiuretic Hormone (ADH / Vasopressin) conserves body water by stimulating reabsorption at:', '{"A":"Bowman''s capsule","B":"DCT and Collecting Duct","C":"Descending Loop of Henle","D":"Glomerulus"}'::jsonb, 'B', 'MCQ', 'Biology', 'Excretory Products and their Elimination', 1, 'ADH inserts aquaporins in distal nephron segments; deficiency causes Diabetes insipidus.', NULL, NULL, 'ADH inserts aquaporins in distal nephron segments; deficiency causes Diabetes insipidus.', 'EASY', true),
        ('11031111-0000-4000-8000-0000000000b9', 'ANF (Atrial Natriuretic Factor) secreted by heart atria acts as a check on RAAS by causing:', '{"A":"Vasoconstriction raising BP","B":"Vasodilation lowering blood pressure and promoting Na⁺/water excretion","C":"Renin release","D":"ADH secretion"}'::jsonb, 'B', 'MCQ', 'Biology', 'Excretory Products and their Elimination', 1, 'Antagonises vasoconstrictive Angiotensin II.', NULL, NULL, 'Antagonises vasoconstrictive Angiotensin II.', 'EASY', true),
        ('11031111-0000-4000-8000-0000000000ba', 'Assertion (A): Juxtamedullary nephrons possess long Loops of Henle dipping deep into the renal medulla.
Reason (R): Long Loops of Henle generate steep medullary osmolar gradient (300 to 1200 mOsmol/L) via the counter-current mechanism to produce hypertonic urine.
Choose the correct option:
A) Both A and R are true, and R is the correct explanation of A.
B) Both A and R are true, and R is not the correct explanation of A.
C) A is true but R is false.
D) A is false but R is true.', '{"A":"Both A and R are true, and R is the correct explanation of A","B":"Both A and R are true, and R is not the correct explanation of A","C":"A is true but R is false","D":"A is false but R is true"}'::jsonb, 'A', 'ASSERTION_REASON', 'Biology', 'Excretory Products and their Elimination', 1, 'Essential for concentrating urine in terrestrial mammals.', NULL, NULL, 'Essential for concentrating urine in terrestrial mammals.', 'EASY', true),
        ('11031111-0000-4000-8000-0000000000bb', 'What is the Juxtaglomerular Apparatus (JGA)? How does it trigger RAAS when GFR falls?', NULL, NULL, 'VSA', 'Biology', 'Excretory Products and their Elimination', 2, 'Special sensitive cellular region formed at the contact of DCT and afferent arteriole. Drop in GFR stimulates JG cells to release Renin -> converts Angiotensinogen -> Angiotensin I -> Angiotensin II (vasoconstrictor + stimulates Aldosterone for Na⁺/water reabsorption).', 'Structure (1M) + RAAS cascade (1M)', NULL, 'Special sensitive cellular region formed at the contact of DCT and afferent arteriole. Drop in GFR stimulates JG cells to release Renin -> converts Angiotensinogen -> Angiotensin I -> Angiotensin II (vasoconstrictor + stimulates Aldosterone for Na⁺/water reabsorption).', 'MEDIUM', true),
        ('11031111-0000-4000-8000-0000000000bc', 'Contrast Excretion roles of Human Lungs, Liver, and Sweat/Sebaceous glands.', NULL, NULL, 'VSA', 'Biology', 'Excretory Products and their Elimination', 2, 'Lungs remove ~200 mL/min CO₂ & water vapour; Liver excretes bilirubin, biliverdin, cholesterol, drugs via bile; Sweat eliminates NaCl, trace urea, lactic acid; Sebum removes sterols/waxes.', '0.5M × 4', NULL, 'Lungs remove ~200 mL/min CO₂ & water vapour; Liver excretes bilirubin, biliverdin, cholesterol, drugs via bile; Sweat eliminates NaCl, trace urea, lactic acid; Sebum removes sterols/waxes.', 'MEDIUM', true),
        ('11031111-0000-4000-8000-0000000000bd', 'Explain the exact absorptive & secretory roles of PCT, Henle''s Loop, and DCT in urine formation.', NULL, NULL, 'SA', 'Biology', 'Excretory Products and their Elimination', 3, 'PCT: cuboidal brush-border epithelium reabsorbs ~70–80% electrolytes/water and 100% glucose/amino acids + secretes H⁺, NH₃, K⁺. Henle''s loop: descending limb permeable to water only (concentrates filtrate); ascending limb impermeable to water, actively transports NaCl (dilutes filtrate). DCT: conditional Na⁺/water reabsorption (Aldosterone/ADH) + K⁺/H⁺ secretion for pH balance.', '1M × 3', NULL, 'PCT: cuboidal brush-border epithelium reabsorbs ~70–80% electrolytes/water and 100% glucose/amino acids + secretes H⁺, NH₃, K⁺. Henle''s loop: descending limb permeable to water only (concentrates filtrate); ascending limb impermeable to water, actively transports NaCl (dilutes filtrate). DCT: conditional Na⁺/water reabsorption (Aldosterone/ADH) + K⁺/H⁺ secretion for pH balance.', 'MEDIUM', true),
        ('11031111-0000-4000-8000-0000000000be', 'Describe Hemodialysis ("Artificial Kidney") and its anticoagulant mechanism for uremic patients.', NULL, NULL, 'SA', 'Biology', 'Excretory Products and their Elimination', 3, 'Blood drained from radial artery passes through cellophane coils immersed in dialysing fluid (same composition as plasma EXCEPT nitrogenous wastes). Heparin prevents clotting during filtration; cleared blood mixed with anti-heparin returns to vein.', 'Process (2M) + Cellophane & heparin (1M)', NULL, 'Blood drained from radial artery passes through cellophane coils immersed in dialysing fluid (same composition as plasma EXCEPT nitrogenous wastes). Heparin prevents clotting during filtration; cleared blood mixed with anti-heparin returns to vein.', 'MEDIUM', true),
        ('11031111-0000-4000-8000-0000000000bf', 'Explain the Counter-Current Mechanism of urine concentration in human kidneys involving Henle''s Loop and Vasa Recta, showing how medullary interstitium osmolarity increases from 300 mOsmol/L in cortex to 1200 mOsmol/L in inner medulla and explaining the role of NaCl and Urea.', NULL, NULL, 'LA', 'Biology', 'Excretory Products and their Elimination', 5, 'Opposite flows in two limbs of Loop of Henle + two limbs of Vasa Recta form counter-current system (1.5M). Ascending limb actively/passively pumps NaCl into medulla trapped by Vasa Recta descending/ascending exchange; collecting duct recycles small amounts of Urea into deep interstitium -> maintains 300 to 1200 mOsmol/L gradient -> water exits collecting duct osmotically producing urine ~4× concentrated (3.5M).', 'Mechanism & Vasa Recta (3M) + NaCl/Urea gradient (2M)', NULL, 'Opposite flows in two limbs of Loop of Henle + two limbs of Vasa Recta form counter-current system (1.5M). Ascending limb actively/passively pumps NaCl into medulla trapped by Vasa Recta descending/ascending exchange; collecting duct recycles small amounts of Urea into deep interstitium -> maintains 300 to 1200 mOsmol/L gradient -> water exits collecting duct osmotically producing urine ~4× concentrated (3.5M).', 'HARD', true),
        ('11031111-0000-4000-8000-0000000000c0', '(i) Define Micturition and name the neural reflex involved. (ii) Which smooth muscle & sphincter relax during micturition? (iii) Identify total urine volume and urea excreted daily by a healthy human. (iv) Contrast Diabetes mellitus vs Diabetes insipidus.', NULL, NULL, 'CASE', 'Biology', 'Excretory Products and their Elimination', 4, '(i) Voluntary process of urine release; Micturition reflex triggered by bladder stretch receptors. (ii) Bladder detrusor muscle contracts while urethral sphincter relaxes. (iii) ~1–1.5 litres urine containing 25–30 g urea/day. (iv) Mellitus = insulin lack (sweet glycosuria); Insipidus = ADH lack (excessive dilute urine).', '4 × 1M = 4M', 'Nephrologists compare desert mammals with long medullary loops against aquatic animals while examining renal blood pressure regulation and solute clearance.', '(i) Voluntary process of urine release; Micturition reflex triggered by bladder stretch receptors. (ii) Bladder detrusor muscle contracts while urethral sphincter relaxes. (iii) ~1–1.5 litres urine containing 25–30 g urea/day. (iv) Mellitus = insulin lack (sweet glycosuria); Insipidus = ADH lack (excessive dilute urine).', 'HARD', true),
        ('11031111-0000-4000-8000-0000000000c1', 'Structural and functional contractile unit of a myofibril between two successive Z-lines is called:', '{"A":"Sarcoplasmic reticulum","B":"Sarcomere","C":"Sarcolemma","D":"H-zone"}'::jsonb, 'B', 'MCQ', 'Biology', 'Locomotion and Movement', 1, '1 Sarcomere = ½ I-band + A-band + ½ I-band.', NULL, NULL, '1 Sarcomere = ½ I-band + A-band + ½ I-band.', 'EASY', true),
        ('11031111-0000-4000-8000-0000000000c2', 'During maximal skeletal muscle contraction, which region disappears completely while A-band length stays unchanged?', '{"A":"I-band stays same","B":"H-zone disappears as thin actin filaments slide over thick myosin filaments (A-band constant)","C":"M-line vanishes","D":"Z-line breaks"}'::jsonb, 'B', 'MCQ', 'Biology', 'Locomotion and Movement', 1, 'Filaments slide without shortening individually.', NULL, NULL, 'Filaments slide without shortening individually.', 'EASY', true),
        ('11031111-0000-4000-8000-0000000000c3', 'Which regulatory protein covers the active myosin-binding sites on actin in a resting muscle?', '{"A":"Actinin","B":"Tropomyosin (masked/unmasked by Troponin-Ca²⁺ complex)","C":"Myoglobin","D":"Keratin"}'::jsonb, 'B', 'MCQ', 'Biology', 'Locomotion and Movement', 1, 'Ca²⁺ binding to Troponin-C shifts Tropomyosin exposing myosin sites.', NULL, NULL, 'Ca²⁺ binding to Troponin-C shifts Tropomyosin exposing myosin sites.', 'EASY', true),
        ('11031111-0000-4000-8000-0000000000c4', 'Total number of bones in an adult human axial skeleton vs appendicular skeleton are:', '{"A":"126 and 80","B":"80 and 126 (Total = 206 bones)","C":"100 and 106","D":"60 and 146"}'::jsonb, 'B', 'MCQ', 'Biology', 'Locomotion and Movement', 1, 'Axial = 80 (skull, vertebral column, sternum, ribs); Appendicular = 126.', NULL, NULL, 'Axial = 80 (skull, vertebral column, sternum, ribs); Appendicular = 126.', 'EASY', true),
        ('11031111-0000-4000-8000-0000000000c5', 'Ball-and-socket synovial joint vs Hinge joint examples respectively are:', '{"A":"Elbow and Atlas-Axis","B":"Shoulder/Hip (glenoid/acetabulum) and Knee/Elbow","C":"Carpals and Pubic symphysis","D":"Skull sutures and Wrist"}'::jsonb, 'B', 'MCQ', 'Biology', 'Locomotion and Movement', 1, 'Ball-and-socket allows multi-axial motion; hinge allows 1-plane flexion.', NULL, NULL, 'Ball-and-socket allows multi-axial motion; hinge allows 1-plane flexion.', 'EASY', true),
        ('11031111-0000-4000-8000-0000000000c6', 'Assertion (A): Red muscle fibres ("aerobic muscles") can contract continuously for long periods without rapid fatigue.
Reason (R): Red fibres possess high myoglobin content and numerous mitochondria generating steady ATP aerobically, unlike white fibres relying on anaerobic glycolysis.
Choose the correct option:
A) Both A and R are true, and R is the correct explanation of A.
B) Both A and R are true, and R is not the correct explanation of A.
C) A is true but R is false.
D) A is false but R is true.', '{"A":"Both A and R are true, and R is the correct explanation of A","B":"Both A and R are true, and R is not the correct explanation of A","C":"A is true but R is false","D":"A is false but R is true"}'::jsonb, 'A', 'ASSERTION_REASON', 'Biology', 'Locomotion and Movement', 1, 'Myoglobin + rich mitochondria prevent early lactic fatigue.', NULL, NULL, 'Myoglobin + rich mitochondria prevent early lactic fatigue.', 'EASY', true),
        ('11031111-0000-4000-8000-0000000000c7', 'Distinguish between True ribs, False ribs (vertebrochondral), and Floating ribs in the human ribcage.', NULL, NULL, 'VSA', 'Biology', 'Locomotion and Movement', 2, '1st–7th pairs = True ribs (attach directly to sternum via hyaline cartilage). 8th, 9th, 10th pairs = False ribs (join 7th rib cartilage). 11th & 12th pairs = Floating ribs (not connected ventrally to sternum).', '2M', NULL, '1st–7th pairs = True ribs (attach directly to sternum via hyaline cartilage). 8th, 9th, 10th pairs = False ribs (join 7th rib cartilage). 11th & 12th pairs = Floating ribs (not connected ventrally to sternum).', 'MEDIUM', true),
        ('11031111-0000-4000-8000-0000000000c8', 'What is Myasthenia gravis vs Muscular dystrophy?', NULL, NULL, 'VSA', 'Biology', 'Locomotion and Movement', 2, 'Myasthenia gravis: autoimmune disorder attacking neuromuscular junctions causing fatigue & paralysis. Muscular dystrophy: progressive genetic degeneration of skeletal muscles.', '1M each', NULL, 'Myasthenia gravis: autoimmune disorder attacking neuromuscular junctions causing fatigue & paralysis. Muscular dystrophy: progressive genetic degeneration of skeletal muscles.', 'MEDIUM', true)
        ON CONFLICT (id) DO NOTHING;

Reason (R): Chemical synapses use neurotransmitter-filled vesicles across a ~20 nm cleft allowing unidirectional modulation, amplification, and integration.
Choose the correct option:
A) Both A and R are true, and R is the correct explanation of A.
B) Both A and R are true, and R is not the correct explanation of A.
C) A is true but R is false.
D) A is false but R is true.', '{"A":"Both A and R are true, and R is the correct explanation of A","B":"Both A and R are true, and R is not the correct explanation of A","C":"A is true but R is false","D":"A is false but R is true"}'::jsonb, 'A', 'ASSERTION_REASON', 'Biology', 'Neural Control and Coordination', 1, 'Programmable synaptic plasticity beats raw gap-junction speed.', NULL, NULL, 'Programmable synaptic plasticity beats raw gap-junction speed.', 'EASY', true),
        ('11031111-0000-4000-8000-0000000000d3', 'Distinguish between Depolarisation and Repolarisation during an action potential.', NULL, NULL, 'VSA', 'Biology', 'Neural Control and Coordination', 2, 'Depolarisation: sudden voltage-gated Na⁺ influx reverses membrane polarity (+30 mV inside). Repolarisation: Na⁺ channels close and K⁺ rushes outward restoring resting negative potential inside.', '1M each', NULL, 'Depolarisation: sudden voltage-gated Na⁺ influx reverses membrane polarity (+30 mV inside). Repolarisation: Na⁺ channels close and K⁺ rushes outward restoring resting negative potential inside.', 'MEDIUM', true),
        ('11031111-0000-4000-8000-0000000000d4', 'What is the Sodium-Potassium (Na⁺/K⁺) Pump stoichiometry?', NULL, NULL, 'VSA', 'Biology', 'Neural Control and Coordination', 2, 'Actively transports 3 Na⁺ ions outwards for every 2 K⁺ ions pumped inwards per ATP hydrolysed, maintaining resting polarisation.', '3 Na⁺ out : 2 K⁺ in + ATP (2M)', NULL, 'Actively transports 3 Na⁺ ions outwards for every 2 K⁺ ions pumped inwards per ATP hydrolysed, maintaining resting polarisation.', 'MEDIUM', true),
        ('11031111-0000-4000-8000-0000000000d5', 'Compare Chemical Synapse vs Electrical Synapse on synaptic cleft, neurotransmitter involvement, speed, and direction.', NULL, NULL, 'SA', 'Biology', 'Neural Control and Coordination', 3, 'Electrical: pre- & post-membranes very close (gap junctions), direct ion current flow, faster, rare in humans. Chemical: fluid-filled synaptic cleft, neurotransmitters (ACh/dopamine/GABA) bind post-synaptic receptors, unidirectional, common.', '3M', NULL, 'Electrical: pre- & post-membranes very close (gap junctions), direct ion current flow, faster, rare in humans. Chemical: fluid-filled synaptic cleft, neurotransmitters (ACh/dopamine/GABA) bind post-synaptic receptors, unidirectional, common.', 'MEDIUM', true),
        ('11031111-0000-4000-8000-0000000000d6', 'List the three regions of Brainstem and describe functions of Hypothalamus and Cerebellum.', NULL, NULL, 'SA', 'Biology', 'Neural Control and Coordination', 3, 'Brainstem = Midbrain + Pons + Medulla oblongata. Hypothalamus: body temperature thermostat, hunger/thirst urge, neurosecretory pituitary control. Cerebellum: convoluted surface coordinating precision balance, posture, and muscle coordination.', '3M', NULL, 'Brainstem = Midbrain + Pons + Medulla oblongata. Hypothalamus: body temperature thermostat, hunger/thirst urge, neurosecretory pituitary control. Cerebellum: convoluted surface coordinating precision balance, posture, and muscle coordination.', 'MEDIUM', true),
        ('11031111-0000-4000-8000-0000000000d7', 'Explain the Generation and Conduction of a Nerve Impulse along an axon (Polarised resting state -> Threshold stimulus & Depolarisation -> Reversal of polarity/Action potential -> Local current circuit propagation -> Repolarisation & Refractory recovery) AND explain Chemical Synaptic Transmission across a synaptic cleft.', NULL, NULL, 'LA', 'Biology', 'Neural Control and Coordination', 5, 'Axonal impulse steps clearly traced with ion movements (3M) + Synaptic transmission (Ca²⁺ influx -> vesicle fusion -> neurotransmitter diffusion across cleft -> receptor binding -> new EPSP/IPSP) (2M).', 'Impulse conduction (3M) + Chemical synapse (2M)', NULL, 'Axonal impulse steps clearly traced with ion movements (3M) + Synaptic transmission (Ca²⁺ influx -> vesicle fusion -> neurotransmitter diffusion across cleft -> receptor binding -> new EPSP/IPSP) (2M).', 'HARD', true),
        ('11031111-0000-4000-8000-0000000000d8', '(i) Name the three cranial meninges from outside to inside. (ii) Which fluid-filled space lies between pia mater and arachnoid? (iii) Where are visual/auditory reflex centres (corpora quadrigemina) located? (iv) Contrast Unipolar, Bipolar, and Multipolar neurons with locations.', NULL, NULL, 'CASE', 'Biology', 'Neural Control and Coordination', 4, '(i) Dura mater (outer), Arachnoid (middle), Pia mater (inner touching brain). (ii) Sub-arachnoid space containing CSF. (iii) Dorsal Midbrain (four round lobes). (iv) Unipolar (embryonic), Bipolar (retina/olfactory), Multipolar (cerebral cortex).', '4 × 1M = 4M', 'Neuroscientists recording patch-clamp axon spikes trace how myelin sheaths, ion channels, and synaptic vesicles orchestrate millisecond neural computation.', '(i) Dura mater (outer), Arachnoid (middle), Pia mater (inner touching brain). (ii) Sub-arachnoid space containing CSF. (iii) Dorsal Midbrain (four round lobes). (iv) Unipolar (embryonic), Bipolar (retina/olfactory), Multipolar (cerebral cortex).', 'HARD', true),
        ('11031111-0000-4000-8000-0000000000d9', 'Which hormone secreted by the Pineal gland regulates our 24-hour diurnal sleep-wake rhythm?', '{"A":"Thyroxine","B":"Melatonin","C":"Cortisol","D":"Oxytocin"}'::jsonb, 'B', 'MCQ', 'Biology', 'Chemical Coordination and Integration', 1, 'Melatonin peaks in darkness regulating sleep cycle and body temperature.', NULL, NULL, 'Melatonin peaks in darkness regulating sleep cycle and body temperature.', 'EASY', true),
        ('11031111-0000-4000-8000-0000000000da', 'Which hormones are stored and released by the Posterior Pituitary (Neurohypophysis) though actually synthesised in Hypothalamus?', '{"A":"GH and TSH","B":"Oxytocin and Vasopressin (ADH)","C":"FSH and LH","D":"Prolactin and ACTH"}'::jsonb, 'B', 'MCQ', 'Biology', 'Chemical Coordination and Integration', 1, 'Transported axonally down neurohypophysis.', NULL, NULL, 'Transported axonally down neurohypophysis.', 'EASY', true),
        ('11031111-0000-4000-8000-0000000000db', 'Adrenal cortex secretes three steroid classes: Glucocorticoids (cortisol), Mineralocorticoids (aldosterone), and sex corticoids. Undersecretion causes:', '{"A":"Cushing''s syndrome","B":"Addison''s disease (acute weakness, fatigue, altered carbohydrate metabolism)","C":"Grave''s disease","D":"Acromegaly"}'::jsonb, 'B', 'MCQ', 'Biology', 'Chemical Coordination and Integration', 1, 'Addison''s disease results from adrenal cortical hyposecretion.', NULL, NULL, 'Addison''s disease results from adrenal cortical hyposecretion.', 'EASY', true),
        ('11031111-0000-4000-8000-0000000000dc', 'Hyposecretion of Growth Hormone in childhood vs Hypersecretion in adults causes respectively:', '{"A":"Acromegaly and Cretinism","B":"Pituitary dwarfism and Acromegaly (severe disfigurement of face/extremities)","C":"Myxoedema and Goitre","D":"Gigantism and Tetany"}'::jsonb, 'B', 'MCQ', 'Biology', 'Chemical Coordination and Integration', 1, 'Post-epiphyseal fusion excess GH causes Acromegaly.', NULL, NULL, 'Post-epiphyseal fusion excess GH causes Acromegaly.', 'EASY', true),
        ('11031111-0000-4000-8000-0000000000dd', 'Hormone from Pars intermedia regulating skin pigmentation via melanocytes is:', '{"A":"ACTH","B":"MSH (Melanocyte Stimulating Hormone)","C":"Calcitonin","D":"Parathormone"}'::jsonb, 'B', 'MCQ', 'Biology', 'Chemical Coordination and Integration', 1, 'Regulates melanin dispersion.', NULL, NULL, 'Regulates melanin dispersion.', 'EASY', true),
        ('11031111-0000-4000-8000-0000000000de', 'Assertion (A): Peptide/protein hormones (like Insulin and Epinephrine) require membrane-bound receptors and second messengers, whereas steroid hormones (like Cortisol and Estrogen) act via intracellular nuclear receptors.
Reason (R): Water-soluble peptide hormones cannot cross the hydrophobic lipid bilayer, whereas lipid-soluble steroids diffuse freely into cytoplasm/nucleus to alter gene expression directly.
Choose the correct option:
A) Both A and R are true, and R is the correct explanation of A.
B) Both A and R are true, and R is not the correct explanation of A.
C) A is true but R is false.
D) A is false but R is true.', '{"A":"Both A and R are true, and R is the correct explanation of A","B":"Both A and R are true, and R is not the correct explanation of A","C":"A is true but R is false","D":"A is false but R is true"}'::jsonb, 'A', 'ASSERTION_REASON', 'Biology', 'Chemical Coordination and Integration', 1, 'Receptor location matches hormone solubility.', NULL, NULL, 'Receptor location matches hormone solubility.', 'EASY', true),
        ('11031111-0000-4000-8000-0000000000df', 'Name two hormones that work antagonistically to regulate blood calcium levels and state their source glands.', NULL, NULL, 'VSA', 'Biology', 'Chemical Coordination and Integration', 2, 'Thyrocalcitonin (TCT, protein hormone from thyroid parafollicular cells) lowers blood Ca²⁺; Parathyroid hormone (PTH, peptide from parathyroid glands) raises blood Ca²⁺ (hypercalcaemic).', '1M each', NULL, 'Thyrocalcitonin (TCT, protein hormone from thyroid parafollicular cells) lowers blood Ca²⁺; Parathyroid hormone (PTH, peptide from parathyroid glands) raises blood Ca²⁺ (hypercalcaemic).', 'MEDIUM', true),
        ('11031111-0000-4000-8000-0000000000e0', 'Distinguish between Exophthalmic Goitre (Grave''s disease) and Simple Hypothyroid Goitre (Cretinism in kids).', NULL, NULL, 'VSA', 'Biology', 'Chemical Coordination and Integration', 2, 'Grave''s disease: hyperthyroidism with enlarged thyroid, protruding eyeballs, high BMR, weight loss. Simple goitre / Cretinism: iodine deficiency / hypothyroidism causing stunted physical & mental growth in children.', '1M each', NULL, 'Grave''s disease: hyperthyroidism with enlarged thyroid, protruding eyeballs, high BMR, weight loss. Simple goitre / Cretinism: iodine deficiency / hypothyroidism causing stunted physical & mental growth in children.', 'MEDIUM', true),
        ('11031111-0000-4000-8000-0000000000e1', 'Explain the opposing roles of Insulin (β-cells) and Glucagon (α-cells) from Islets of Langerhans in blood glucose homeostasis.', NULL, NULL, 'SA', 'Biology', 'Chemical Coordination and Integration', 3, 'Glucagon (hyperglycaemic): stimulates hepatic glycogenolysis & gluconeogenesis raising blood glucose. Insulin (hypoglycaemic): enhances cellular glucose uptake by hepatocytes/adipocytes and triggers glycogenesis lowering blood glucose.', '1.5M each', NULL, 'Glucagon (hyperglycaemic): stimulates hepatic glycogenolysis & gluconeogenesis raising blood glucose. Insulin (hypoglycaemic): enhances cellular glucose uptake by hepatocytes/adipocytes and triggers glycogenesis lowering blood glucose.', 'MEDIUM', true),
        ('11031111-0000-4000-8000-0000000000e2', 'Name four gastrointestinal tract peptide hormones (Gastrin, Secretin, CCK, GIP) and state one target organ & action of each.', NULL, NULL, 'SA', 'Biology', 'Chemical Coordination and Integration', 3, 'Gastrin (gastric glands -> HCl & pepsinogen); Secretin (exocrine pancreas -> water & HCO₃⁻); CCK (pancreas enzymes & gall bladder bile); GIP (inhibits gastric secretion & motility).', '3M', NULL, 'Gastrin (gastric glands -> HCl & pepsinogen); Secretin (exocrine pancreas -> water & HCO₃⁻); CCK (pancreas enzymes & gall bladder bile); GIP (inhibits gastric secretion & motility).', 'MEDIUM', true),
        ('11031111-0000-4000-8000-0000000000e3', 'Explain the Mechanism of Hormone Action comparing (a) Membrane-bound Receptor + Second Messenger cascade (FSH / Epinephrine using cAMP, IP₃, Ca²⁺) and (b) Intracellular Receptor-Genome complex (Estrogen / Testosterone / Cortisol). Also list five hormones secreted by Adenohypophysis (Anterior Pituitary) with one target function each.', NULL, NULL, 'LA', 'Biology', 'Chemical Coordination and Integration', 5, 'Two mechanisms cleanly traced (2.5M) + 5 anterior pituitary hormones: GH, Prolactin, TSH, ACTH, LH & FSH (2.5M).', 'Mechanisms (2.5M) + 5 pituitary hormones (2.5M)', NULL, 'Two mechanisms cleanly traced (2.5M) + 5 anterior pituitary hormones: GH, Prolactin, TSH, ACTH, LH & FSH (2.5M).', 'HARD', true),
        ('11031111-0000-4000-8000-0000000000e4', '(i) Name two "Hormones of Fight or Flight" from Adrenal Medulla and two physiological effects. (ii) Role of Thymosin from Thymus gland and why immune strength weakens in old age. (iii) Hormone secreted by kidney JG cells stimulating RBC production. (iv) Name two gonadotropins and their role in males & females.', NULL, NULL, 'CASE', 'Biology', 'Chemical Coordination and Integration', 4, '(i) Adrenaline (Epinephrine) & Noradrenaline -> pupillary dilation, piloerection, sweating, increased heart beat & respiratory rate, glycogen breakdown. (ii) T-lymphocyte differentiation & antibody support; thymus degenerates with age reducing thymosin. (iii) Erythropoietin. (iv) LH & FSH (androgens/ovulation & spermatogenesis/follicle growth).', '4 × 1M = 4M', 'An endocrinology case study links cold intolerance, high blood glucose, weakened elderly immunity, and acute stress adrenaline surges to hormonal feedback loops.', '(i) Adrenaline (Epinephrine) & Noradrenaline -> pupillary dilation, piloerection, sweating, increased heart beat & respiratory rate, glycogen breakdown. (ii) T-lymphocyte differentiation & antibody support; thymus degenerates with age reducing thymosin. (iii) Erythropoietin. (iv) LH & FSH (androgens/ovulation & spermatogenesis/follicle growth).', 'HARD', true),
        ('11031111-0000-4000-8000-0000000000e5', 'Which of the following follows the correct ICBN / ICZN convention for writing a scientific name?', '{"A":"mangifera Indica","B":"Mangifera Indica","C":"Mangifera indica","D":"MANGIFERA INDICA"}'::jsonb, 'C', 'MCQ', 'Biology', 'The Living World', 1, 'Option (C) is correct. First word (Genus) begins with a Capital letter ("Mangifera") and second word (specific epithet) starts with a small letter ("indica"), printed in italics or underlined separately.', 'Genus capitalized, species lowercase -> Mangifera indica [1 Mark]', NULL, 'Examiner Tip: When handwritten, both genus and species must be underlined separately. | Common Pitfall: Capitalizing the species name ("Indica").', 'EASY', true),
        ('11031111-0000-4000-8000-0000000000e6', 'Which living organisms completely lack a cell wall, are the smallest living cells known, and can survive without oxygen?', '{"A":"Cyanobacteria","B":"Diatoms","C":"Mycoplasma","D":"Dinoflagellates"}'::jsonb, 'C', 'MCQ', 'Biology', 'Biological Classification', 1, 'Option (C) is correct. Mycoplasmas are prokaryotes lacking a cell wall completely and can survive under anaerobic conditions.', 'Identify Mycoplasma as smallest wall-less cells [1 Mark]', NULL, 'Examiner Tip: Mycoplasmas are insensitive to penicillin because penicillin targets cell-wall synthesis. | Common Pitfall: Confusing Mycoplasma with Diatoms (silica cell walls).', 'EASY', true),
        ('11031111-0000-4000-8000-0000000000e7', 'In mosses (Bryophytes), the predominant stage of the life cycle consists of two stages. The creeping, green, branched and frequently filamentous stage is called:', '{"A":"Prothallus","B":"Protonema","C":"Sporophyte","D":"Gemmae"}'::jsonb, 'B', 'MCQ', 'Biology', 'Plant Kingdom', 1, 'Option (B) is correct. Protonema develops directly from a spore, followed by the leafy stage bearing sex organs. ("Prothallus" belongs to Pteridophytes.)', 'Identify Protonema stage in mosses [1 Mark]', NULL, 'Examiner Tip: Distinguish Protonema (Mosses/Bryophytes) from Prothallus (Ferns/Pteridophytes)! | Common Pitfall: Confusing protonema with prothallus.', 'EASY', true),
        ('11031111-0000-4000-8000-0000000000e8', 'Water vascular system, radial symmetry in adults, and spiny calcareous ossicles are unique diagnostic features of Phylum:', '{"A":"Porifera","B":"Coelenterata","C":"Mollusca","D":"Echinodermata"}'::jsonb, 'D', 'MCQ', 'Biology', 'Animal Kingdom', 1, 'Option (D) is correct. Echinoderms (like Asterias / starfish) possess a unique water vascular system helping in locomotion, capture and transport of food, and respiration.', 'Identify Phylum Echinodermata [1 Mark]', NULL, 'Examiner Tip: Porifera = canal system; Cnidaria = cnidoblasts; Ctenophora = comb plates; Echinodermata = water vascular system. | Common Pitfall: Confusing water canal system (Porifera) with water vascular system (Echinodermata).', 'EASY', true),
        ('11031111-0000-4000-8000-0000000000e9', 'When ovules develop on the inner wall of the ovary or on peripheral part in a unilocular ovary (e.g., Mustard and Argemone), the placentation is:', '{"A":"Axile","B":"Parietal","C":"Free central","D":"Basal"}'::jsonb, 'B', 'MCQ', 'Biology', 'Morphology of Flowering Plants', 1, 'Option (B) is correct. In Parietal placentation (mustard, Argemone), ovules lie on the inner peripheral wall of the ovary.', 'Identify Parietal placentation [1 Mark]', NULL, 'Examiner Tip: Match examples: Marginal = Pea; Axile = China rose/Tomato/Lemon; Free central = Dianthus/Primrose; Basal = Sunflower/Marigold. | Common Pitfall: Mixing up Axile and Parietal examples.', 'EASY', true),
        ('11031111-0000-4000-8000-0000000000ea', 'Which group of organelles constitutes the coordinated "endomembrane system" of a eukaryotic cell?', '{"A":"Mitochondria, Chloroplast, Peroxisome","B":"Endoplasmic Reticulum, Golgi complex, Lysosomes, Vacuoles","C":"Nucleus, Ribosomes, Centrosome","D":"Plastids, Golgi complex, Cytoskeleton"}'::jsonb, 'B', 'MCQ', 'Biology', 'Cell', 1, 'Option (B) is correct. ER, Golgi apparatus, Lysosomes and Vacuoles have coordinated functions and constitute the endomembrane system (Mitochondria, Chloroplasts & Peroxisomes are excluded).', 'Identify ER, Golgi, Lysosomes, Vacuoles [1 Mark]', NULL, 'Examiner Tip: NCERT explicitly lists why mitochondria & chloroplasts are NOT part of endomembrane system. | Common Pitfall: Including mitochondria in endomembrane system.', 'EASY', true),
        ('11031111-0000-4000-8000-0000000000eb', 'The bond formed between the carboxyl group of one amino acid and the amino group of the next amino acid in a polypeptide chain is:', '{"A":"Glycosidic bond","B":"Phosphodiester bond","C":"Peptide bond (CONH)","D":"Hydrogen bond only"}'::jsonb, 'C', 'MCQ', 'Biology', 'Biomolecules', 1, 'Option (C) is correct. Amino acids link via peptide bonds (-CO-NH-) with elimination of a water molecule (dehydration synthesis).', 'Identify Peptide bond linking amino acids [1 Mark]', NULL, 'Examiner Tip: Sugars -> Glycosidic bond; Nucleotides -> Phosphodiester bond; Amino acids -> Peptide bond. | Common Pitfall: Selecting glycosidic bond.', 'EASY', true),
        ('11031111-0000-4000-8000-0000000000ec', 'Crossing over (recombination) between non-sister chromatids of homologous chromosomes occurs during which substage of Prophase I?', '{"A":"Leptotene","B":"Zygotene","C":"Pachytene","D":"Diplotene"}'::jsonb, 'C', 'MCQ', 'Biology', 'Cell Cycle & Division', 1, 'Option (C) is correct. During Pachytene, recombination nodules appear and enzyme recombinase mediates crossing over between non-sister chromatids.', 'Identify Pachytene + recombinase enzyme [1 Mark]', NULL, 'Examiner Tip: Zygotene = synapsis/bivalent; Pachytene = crossing over; Diplotene = chiasmata visible; Diakinesis = terminalisation. | Common Pitfall: Confusing Zygotene (synapsis) with Pachytene (crossing over).', 'EASY', true),
        ('11031111-0000-4000-8000-0000000000ed', 'In C4 plants like maize and sugarcane, the primary CO₂ acceptor in mesophyll cells is:', '{"A":"RuBP (5-carbon)","B":"PEP (3-carbon Phosphoenolpyruvate)","C":"Oxaloacetic acid (OAA)","D":"3-PGA"}'::jsonb, 'B', 'MCQ', 'Biology', 'Photosynthesis in Higher Plants', 1, 'Option (B) is correct. In mesophyll cells of C4 plants, 3-carbon PEP accepts CO₂ via PEPcase enzyme to form 4-carbon OAA. RuBP acts later inside bundle sheath cells.', 'Identify PEP (3C) as primary acceptor in C4 mesophyll [1 Mark]', NULL, 'Examiner Tip: Remember: Primary acceptor = PEP (3C); First stable product = OAA (4C). | Common Pitfall: Marking OAA (first product) instead of PEP (acceptor).', 'EASY', true),
        ('11031111-0000-4000-8000-0000000000ee', 'What is the Respiratory Quotient (RQ) value when carbohydrates (like glucose) are completely oxidised in aerobic respiration?', '{"A":"0.7","B":"0.9","C":"1.0","D":"> 1.0"}'::jsonb, 'C', 'MCQ', 'Biology', 'Respiration in Plants', 1, 'Option (C) is correct. C₆H₁₂O₆ + 6O₂ → 6CO₂ + 6H₂O. RQ = CO₂ evolved / O₂ consumed = 6 / 6 = 1.0.', 'RQ = 6 CO₂ / 6 O₂ = 1.0 for carbohydrates [1 Mark]', NULL, 'Examiner Tip: Carbohydrates = 1.0; Fats (Tripalmitin) = 0.7; Proteins ≈ 0.9; Organic acids > 1. | Common Pitfall: Marking 0.7 (fats).', 'EASY', true),
        ('11031111-0000-4000-8000-0000000000ef', 'Which gaseous plant growth regulator promotes rapid internode/petiole elongation in deep-water rice plants and induces fruit ripening?', '{"A":"Auxin","B":"Gibberellin","C":"Cytokinin","D":"Ethylene"}'::jsonb, 'D', 'MCQ', 'Biology', 'Plant Growth', 1, 'Option (D) is correct. Ethylene is a gaseous PGR that accelerates fruit ripening (respiratory climactic) and promotes petiole/internode elongation in deep-water rice.', 'Identify Ethylene as gaseous PGR [1 Mark]', NULL, 'Examiner Tip: Only gaseous PGR in NCERT = Ethylene (applied commercially as Ethephon). | Common Pitfall: Selecting Gibberellin because of internode elongation.', 'EASY', true),
        ('11031111-0000-4000-8000-0000000000f0', 'Which combination of physiological factors shifts the oxyhaemoglobin dissociation curve to the RIGHT (favouring O₂ release in tissues)?', '{"A":"High pO₂, low pCO₂, low H⁺, low temp","B":"Low pO₂, high pCO₂, high H⁺ (low pH), high temp","C":"High pH and low temperature","D":"Zero pCO₂"}'::jsonb, 'B', 'MCQ', 'Biology', 'Breathing & Exchange of Gases', 1, 'Option (B) is correct. In metabolically active tissues, high pCO₂, high H⁺ (low pH), high temperature and low pO₂ shift the curve right (Bohr effect), promoting dissociation of O₂ from haemoglobin.', 'High pCO₂, high H⁺, high temp, low pO₂ -> right shift [1 Mark]', NULL, 'Examiner Tip: Alveoli (low pCO₂, high pO₂) favour association (left shift); Tissues (high pCO₂, high H⁺) favour dissociation (right shift). | Common Pitfall: Confusing high H⁺ with high pH!', 'EASY', true),
        ('11031111-0000-4000-8000-0000000000f1', 'Assertion (A): Mitosis is called equational division.
Reason (R): The number of chromosomes in the parent cell and the two daughter cells formed after mitosis remains identical.', '{"A":"Both A and R are true, and R is the correct explanation of A","B":"Both A and R are true, but R is not the correct explanation of A","C":"A is true, but R is false","D":"A is false, but R is true"}'::jsonb, 'A', 'ASSERTION_REASON', 'Biology', 'Cell Cycle', 1, 'Option (A) is correct. During Anaphase, sister chromatids separate equally so diploid (2n) parent yields diploid (2n) daughter cells.', 'Option (A) noting equal chromosome retention [1 Mark]', NULL, 'Examiner Tip: Meiosis I is reductional (2n -> n); Mitosis and Meiosis II are equational. | Common Pitfall: Confusing DNA amount doubling in S-phase with chromosome number doubling.', 'EASY', true),
        ('11031111-0000-4000-8000-0000000000f2', 'Assertion (A): Photorespiration does NOT occur in C4 plants like maize.
Reason (R): C4 plants maintain a high concentration of CO₂ around RuBisCO inside bundle sheath cells, preventing its oxygenase activity.', '{"A":"Both A and R are true, and R is the correct explanation of A","B":"Both A and R are true, but R is not the correct explanation of A","C":"A is true, but R is false","D":"A is false, but R is true"}'::jsonb, 'A', 'ASSERTION_REASON', 'Biology', 'Photosynthesis', 1, 'Option (A) is correct. Decarboxylation of C4 malic acid inside thick-walled bundle sheath cells floods RuBisCO with CO₂, maximising carboxylation and eliminating wasteful photorespiration.', 'Option (A) explaining CO₂ concentrating mechanism around RuBisCO [1 Mark]', NULL, 'Examiner Tip: Photorespiration produces neither ATP nor NADPH in C3 plants. | Common Pitfall: Thinking C4 plants lack RuBisCO altogether (they have it in bundle sheath cells!).', 'EASY', true),
        ('11031111-0000-4000-8000-0000000000f3', 'Assertion (A): Terrestrial mammals can produce hypertonic urine much more concentrated than their blood plasma.
Reason (R): Counter-current mechanism operating between Henle''s loop and vasa recta maintains an increasing osmolarity gradient (300 to 1200 mOsmol/L) in the renal medulla.', '{"A":"Both A and R are true, and R is the correct explanation of A","B":"Both A and R are true, but R is not the correct explanation of A","C":"A is true, but R is false","D":"A is false, but R is true"}'::jsonb, 'A', 'ASSERTION_REASON', 'Biology', 'Excretion', 1, 'Option (A) is correct. NaCl transported by ascending limb of Henle''s loop is exchanged with descending vasa recta and urea from collecting duct maintains the medullary osmotic gradient up to 1200 mOsmol/L.', 'Option (A) citing medullary gradient 300-1200 mOsmol/L [1 Mark]', NULL, 'Examiner Tip: Humans produce urine nearly 4 times more concentrated than initial filtrate. | Common Pitfall: Reversing permeability of descending limb (water only) and ascending limb (electrolytes only).', 'EASY', true),
        ('11031111-0000-4000-8000-0000000000f4', 'Assertion (A): A resting axonal membrane is positively charged on the outer surface and negatively charged inside.
Reason (R): The axonal membrane at rest is nearly impermeable to K⁺ ions and freely permeable to Na⁺ ions.', '{"A":"Both A and R are true, and R is the correct explanation of A","B":"Both A and R are true, but R is not the correct explanation of A","C":"A is true, but R is false","D":"A is false, but R is true"}'::jsonb, 'C', 'ASSERTION_REASON', 'Biology', 'Neural Control', 1, 'Option (C) is correct. At rest, the axonal membrane is comparatively MORE permeable to K⁺ ions and nearly IMPERMEABLE to Na⁺ ions and negatively charged proteins. Thus A is true, R is false.', 'Option (C): A true, R false (resting is permeable to K+, impermeable to Na+) [1 Mark]', NULL, 'Examiner Tip: Na⁺-K⁺ pump actively transports 3 Na⁺ outwards for 2 K⁺ inwards. | Common Pitfall: Missing the inverted Na+/K+ permeability in Reason R.', 'EASY', true),
        ('11031111-0000-4000-8000-0000000000f5', 'Explain what happens during "double fertilisation" unique to angiosperms, naming the ploidy of both products formed.', NULL, NULL, 'VSA', 'Biology', 'Plant Kingdom', 2, 'Out of two male gametes released by the pollen tube into the embryo sac:
1. Syngamy: One male gamete (n) fuses with the egg cell (n) to form a diploid Zygote (2n) -> develops into embryo.
2. Triple Fusion: The second male gamete (n) fuses with the diploid secondary nucleus / two polar nuclei (2n) to form triploid Primary Endosperm Nucleus (PEN, 3n) -> develops into nutritive endosperm.', 'Syngamy forming diploid zygote (2n) [1 Mark] | Triple fusion forming triploid PEN (3n) [1 Mark]', NULL, 'Examiner Tip: State exact ploidy: Zygote = 2n, PEN = 3n. | Common Pitfall: Confusing PEN ploidy as 2n instead of 3n.', 'MEDIUM', true),
        ('11031111-0000-4000-8000-0000000000f6', 'Differentiate between Valvate and Vexillary aestivation with one plant example for each.', NULL, NULL, 'VSA', 'Biology', 'Morphology', 2, '1. Valvate aestivation: Sepals or petals in a whorl just touch one another at the margin without overlapping (e.g., Calotropis).
2. Vexillary (papilionaceous) aestivation: Five petals where the largest posterior petal (standard) overlaps two lateral petals (wings), which in turn overlap the two smallest anterior petals (keel) (e.g., Pea, Bean).', 'Valvate definition + Calotropis [1 Mark] | Vexillary (standard, wings, keel) + Pea/Bean [1 Mark]', NULL, 'Examiner Tip: Use NCERT terms: Standard, Wings, Keel for Vexillary. | Common Pitfall: Mixing up Twisted (China rose) with Imbricate (Cassia/Gulmohar).', 'MEDIUM', true),
        ('11031111-0000-4000-8000-0000000000f7', 'What is competitive inhibition of an enzyme? Illustrate with the classical example of succinic dehydrogenase.', NULL, NULL, 'VSA', 'Biology', 'Biomolecules', 2, 'When an inhibitor molecule closely resembles the natural substrate in molecular structure and competes for binding at the active site of the enzyme, it is called competitive inhibition.
Example: Malonate closely resembles succinate and competitively inhibits succinic dehydrogenase enzyme activity.', 'Definition (structural mimic binding active site) [1 Mark] | Malonate inhibiting succinic dehydrogenase [1 Mark]', NULL, 'Examiner Tip: Competitive inhibition is overcome by increasing substrate concentration. | Common Pitfall: Confusing competitive inhibitor with non-competitive allosteric inhibitor.', 'MEDIUM', true),
        ('11031111-0000-4000-8000-0000000000f8', 'State two anatomical or biochemical differences between Red muscle fibres and White muscle fibres.', NULL, NULL, 'VSA', 'Biology', 'Locomotion & Movement', 2, '1. Red fibres contain very high myoglobin content and abundant mitochondria, generating ATP aerobically for sustained slow work (e.g., marathon posture muscles).
2. White fibres have very low myoglobin and fewer mitochondria, but high sarcoplasmic reticulum, relying mainly on anaerobic glycolysis for rapid bursts of contraction.', 'Myoglobin & mitochondrial difference [1 Mark] | Aerobic sustained vs anaerobic rapid contraction [1 Mark]', NULL, 'Examiner Tip: Mention sarcoplasmic reticulum abundance in white fibres. | Common Pitfall: Saying white fibres lack actin or myosin.', 'MEDIUM', true),
        ('11031111-0000-4000-8000-0000000000f9', 'Define Vital Capacity (VC) and write its relation with Tidal Volume (TV), Inspiratory Reserve Volume (IRV), and Expiratory Reserve Volume (ERV).', NULL, NULL, 'VSA', 'Biology', 'Breathing', 2, 'Vital Capacity (VC) is the maximum volume of air a person can breathe in after a forced expiration (or breathe out after a forced inspiration).
Formula: VC = ERV + TV + IRV (typically 3500–4500 mL).', 'Definition of Vital Capacity [1 Mark] | Formula VC = ERV + TV + IRV [1 Mark]', NULL, 'Examiner Tip: VC does NOT include Residual Volume (RV); Total Lung Capacity = VC + RV. | Common Pitfall: Adding Residual Volume into Vital Capacity.', 'MEDIUM', true),
        ('11031111-0000-4000-8000-0000000000fa', 'State the three fundamental diagnostic characters of Phylum Chordata and mention how Urochordata differs from Cephalochordata regarding the notochord.', NULL, NULL, 'SA', 'Biology', 'Animal Kingdom', 3, 'Three fundamental features of Chordates:
1. Presence of a dorsal solid/elastic Notochord.
2. Dorsal hollow nerve cord.
3. Paired pharyngeal gill slits (along with post-anal tail and closed circulatory system).
Difference:
• In Urochordata (e.g., Ascidia), notochord is present ONLY in the larval tail.
• In Cephalochordata (e.g., Branchiostoma/Amphioxus), notochord extends from head to tail region and persists throughout life.', 'Three fundamental chordate features [1.5 Marks] | Notochord location/persistence in Uro vs Cephalochordata [1.5 Marks]', NULL, 'Examiner Tip: Specify "dorsal hollow single nerve cord" (vs ventral solid double in non-chordates). | Common Pitfall: Saying chordates always have a vertebral column (only Vertebrata subphylum does!).', 'MEDIUM', true),
        ('11031111-0000-4000-8000-0000000000fb', 'Enumerate three clear anatomical differences between a Dicotyledonous stem and a Monocotyledonous stem.', NULL, NULL, 'SA', 'Biology', 'Anatomy of Flowering Plants', 3, '1. Vascular Bundles Arrangement: Arranged in a ring in dicot stem; scattered throughout ground tissue in monocot stem.
2. Type of Vascular Bundles & Cambium: Conjoint, collateral and OPEN (cambium present -> secondary growth) in dicots; Conjoint, collateral and CLOSED (cambium absent -> no secondary growth) in monocots.
3. Hypodermis & Ground Tissue: Collenchymatous hypodermis with well-differentiated cortex, endodermis, pericycle & pith in dicots; Sclerenchymatous hypodermis and undifferentiated ground tissue in monocots.', 'Ring vs scattered vascular bundles [1 Mark] | Open (cambium) vs Closed vascular bundles [1 Mark] | Hypodermis & pith differentiation [1 Mark]', NULL, 'Examiner Tip: In roots, vascular bundles are RADIAL; in stems and leaves, they are CONJOINT. | Common Pitfall: Confusing stem vascular bundles with radial root bundles.', 'MEDIUM', true),
        ('11031111-0000-4000-8000-0000000000fc', 'Describe three biological significances of Meiosis in sexually reproducing organisms, and distinguish Anaphase I from Anaphase of Mitosis.', NULL, NULL, 'SA', 'Biology', 'Cell Cycle', 3, 'Significances of Meiosis:
1. Maintains constant chromosome number across generations by halving 2n → n in gametes.
2. Introduces genetic variations via crossing over (Pachytene) and independent assortment, essential for evolution.
3. Forms haploid spores/gametes in plants and animals.
Anaphase Distinction:
In Anaphase I of meiosis, homologous chromosomes separate while sister chromatids remain attached at centromeres (centromeres do NOT split). In Mitotic Anaphase, centromeres split and sister chromatids separate.', 'Two clear significances of meiosis [1.5 Marks] | Anaphase I (homologs separate, no centromere split) vs Mitosis [1.5 Marks]', NULL, 'Examiner Tip: Highlighting "centromeres do NOT divide in Anaphase I" earns full clarity marks. | Common Pitfall: Saying sister chromatids separate in Anaphase I.', 'MEDIUM', true),
        ('11031111-0000-4000-8000-0000000000fd', 'Explain the role of Oxygen as the terminal electron acceptor in the mitochondrial Electron Transport System (ETS), and state how ATP synthase synthesises ATP.', NULL, NULL, 'SA', 'Biology', 'Respiration in Plants', 3, '1. Role of Oxygen: Electrons from NADH and FADH₂ pass down Complexes I–IV of the inner mitochondrial membrane. At Complex IV (cytochrome c oxidase), oxygen acts as the final hydrogen/electron acceptor, combining with protons (H⁺) to form metabolic water (½O₂ + 2H⁺ + 2e⁻ → H₂O). Without O₂, the entire ETS stalls.
2. ATP Synthase (Complex V): Pumping of H⁺ across inner membrane creates a proton gradient in the intermembrane space. Protons flow back into the matrix down this electrochemical gradient through F₀ channel, driving conformational change in F₁ headpiece to phosphorylate ADP + Pi → ATP.', 'Terminal electron/proton acceptor forming H₂O [1.5 Marks] | Proton gradient & F₀-F₁ ATP synthase coupling [1.5 Marks]', NULL, 'Examiner Tip: Oxygen is called the "terminal" acceptor — it removes spent electrons to keep the chain flowing. | Common Pitfall: Saying ATP synthase itself pumps protons outward instead of letting protons flow back.', 'MEDIUM', true),
        ('11031111-0000-4000-8000-0000000000fe', 'Briefly describe the three sequential phases of one human cardiac cycle (0.8 seconds) and explain what causes the "Lub" and "Dub" heart sounds.', NULL, NULL, 'SA', 'Biology', 'Body Fluids & Circulation', 3, '1. Atrial Systole (~0.1 s): SAN triggers contraction of both atria, pushing ~30% extra blood into ventricles.
2. Ventricular Systole (~0.3 s): Ventricles contract; AV valves close sharply causing first sound "Lub", followed by semilunar valves opening to pump ~70 mL stroke volume into aorta and pulmonary artery.
3. Joint Diastole (~0.4 s): Both atria and ventricles relax; closure of semilunar valves prevents backflow, producing the second sound "Dub".', 'Atrial systole, ventricular systole, joint diastole durations [1.5 Marks] | Lub (AV valves close) & Dub (semilunar valves close) [1.5 Marks]', NULL, 'Examiner Tip: Lub = closure of Tricuspid & Bicuspid (AV) valves; Dub = closure of Semilunar valves. | Common Pitfall: Attributing heart sounds to opening of valves instead of sharp closure.', 'MEDIUM', true),
        ('11031111-0000-4000-8000-0000000000ff', 'Define Photoperiodism and Vernalisation. How do Long-Day Plants differ from Short-Day Plants in flowering response?', NULL, NULL, 'SA', 'Biology', 'Plant Growth', 3, '1. Photoperiodism: Response of plants to relative durations of light and dark periods to induce flowering, perceived by leaves (via phytochrome/florigen).
2. Vernalisation: Promotion of flowering quantitatively or qualitatively by exposure to low temperature (e.g., winter varieties of wheat/barley/rye).
Difference:
• Long-Day Plants require exposure to light exceeding a critical photoperiod.
• Short-Day Plants require light period shorter than a critical duration (more importantly, an uninterrupted critical dark period).', 'Definitions of Photoperiodism & Vernalisation [1.5 Marks] | LDP vs SDP critical photoperiod contrast [1.5 Marks]', NULL, 'Examiner Tip: Site of perception of photoperiod = Leaves; Site of vernalisation = Shoot apical meristem/embryo. | Common Pitfall: Confusing dormancy breaking with photoperiodic flowering.', 'MEDIUM', true),
        ('11031111-0000-4000-8000-000000000100', 'Trace the step-by-step transmission of a nerve impulse across a chemical synapse from pre-synaptic neuron to post-synaptic neuron.', NULL, NULL, 'SA', 'Biology', 'Neural Control', 3, '1. Action potential arrives at the axon terminal (synaptic knob) of pre-synaptic neuron.
2. It depolarises the membrane, opening voltage-gated Ca²⁺ channels; Ca²⁺ enters and stimulates synaptic vesicles to fuse with pre-synaptic membrane.
3. Vesicles release neurotransmitters (e.g., acetylcholine) into the fluid-filled synaptic cleft.
4. Neurotransmitters bind to specific receptors on the post-synaptic membrane, opening ion channels and generating a new excitatory or inhibitory post-synaptic potential.', 'Impulse arrival + synaptic vesicle fusion [1.5 Marks] | Neurotransmitter release across cleft -> receptor ion channel opening [1.5 Marks]', NULL, 'Examiner Tip: Chemical synapses always have a synaptic cleft (~20 nm) and allow one-way conduction. | Common Pitfall: Omitting role of neurotransmitter receptors on post-synaptic membrane.', 'MEDIUM', true),
        ('11031111-0000-4000-8000-000000000101', 'Read the passage and answer:
During photosynthesis in green plants, light reactions occur inside thylakoid membranes via Photosystems I and II, generating ATP and NADPH + H⁺, along with photolysis of water. The dark reaction (Calvin cycle) occurs in the stroma.

(a) Name the metal ions/minerals required for photolysis of water inside PS II. (1M)
(b) Differentiate between Cyclic and Non-Cyclic photophosphorylation based on electron return and products formed. (2M)
(c) How many ATP and NADPH molecules are consumed to fix 1 molecule of Glucose (6 CO₂) in the C3 Calvin cycle? (1M)', NULL, NULL, 'CASE', 'Biology', 'Case Study', 4, '(a) Manganese (Mn²⁺) and Chloride (Cl⁻) ions.
(b) Non-cyclic involves both PS II and PS I, splits water to evolve O₂, electrons do not return to PS II, and produces BOTH ATP and NADPH. Cyclic involves only PS I (in stroma lamellae), electrons return to P700, evolves NO O₂ and forms ONLY ATP.
(c) 18 ATP and 12 NADPH (3 ATP and 2 NADPH per CO₂ fixed × 6 turns).', '(a) Mn²⁺ and Cl⁻ [1 Mark] | (b) Cyclic vs Non-cyclic differences [2 Marks] | (c) 18 ATP and 12 NADPH [1 Mark]', NULL, 'Examiner Tip: Per 1 CO₂ in C3 cycle = 3 ATP + 2 NADPH; per 1 CO₂ in C4 cycle = 5 ATP + 2 NADPH. | Common Pitfall: Writing 12 ATP instead of 18 ATP for 1 Glucose.', 'HARD', true),
        ('11031111-0000-4000-8000-000000000102', 'Read the passage and answer:
A skeletal muscle fibre contains alternating dark A-bands (myosin + overlapping actin) and light I-bands (actin only) between successive Z-lines forming a functional unit called a sarcomere.

(a) What happens to the length of the A-band and I-band during maximal muscle contraction? (1M)
(b) Explain the role of Ca²⁺ ions released from the sarcoplasmic reticulum in initiating contraction. (2M)
(c) What causes muscle fatigue during prolonged vigorous activity? (1M)', NULL, NULL, 'CASE', 'Biology', 'Case Study', 4, '(a) A-band length remains CONSTANT; I-band shortens (H-zone disappears) as actin filaments slide inward.
(b) Ca²⁺ ions bind to a subunit of Troponin on thin actin filaments, unmasking the active binding sites for myosin heads. Activated myosin (using ATP hydrolysis) forms cross-bridges and pulls actin towards the M-line.
(c) Repeated activation leads to anaerobic breakdown of glycogen in muscles, accumulating lactic acid and causing fatigue.', '(a) A-band unchanged, I-band shortens [1 Mark] | (b) Ca²⁺ binds Troponin -> unmasks myosin-binding sites on actin [2 Marks] | (c) Lactic acid accumulation [1 Mark]', NULL, 'Examiner Tip: A-band NEVER changes length; I-band and H-zone shorten. | Common Pitfall: Saying myosin filaments themselves shorten in length.', 'HARD', true),
        ('11031111-0000-4000-8000-000000000103', '(a) Outline the key steps and net ATP/NADH gain of Glycolysis (EMP pathway). Where does it take place in a cell?
(b) Give the substrate-level phosphorylation steps and net product summary per glucose molecule in the Krebs (TCA) cycle.
(c) Why is fermentation far less energy-efficient than aerobic respiration?', NULL, NULL, 'LA', 'Biology', 'Respiration in Plants', 5, '(a) Site: Cytoplasm (occurs in both aerobes and anaerobes). A 6C Glucose is phosphorylated twice (consuming 2 ATP) -> splits into two 3C triose phosphates -> oxidised to two Pyruvate molecules, producing 4 ATP directly and 2 NADH. Net direct gain = 2 ATP + 2 NADH.
(b) Each Pyruvate forms Acetyl-CoA (yielding 1 NADH -> 2 total) and enters Mitochondrial Matrix TCA cycle. Per glucose (2 turns of Krebs cycle): 6 NADH, 2 FADH₂, 2 GTP/ATP (substrate-level when Succinyl-CoA -> Succinic acid), and 4 CO₂ released.
(c) In fermentation (yeast/muscle), glucose is only partially oxidised (<7% energy released) with net gain of only 2 ATP, whereas complete aerobic oxidation yields 38 ATP (or 36–38 ATP).', '(a) Cytoplasm site + 2 ATP consumed, 4 produced (Net 2 ATP, 2 NADH) [2 Marks] | (b) Matrix site + 2 turns output (6 NADH, 2 FADH₂, 2 GTP) [2 Marks] | (c) Incomplete oxidation (<7% energy, 2 ATP) in fermentation [1 Mark]', NULL, 'Examiner Tip: Remember two turns of Krebs cycle occur per glucose molecule! | Common Pitfall: Reporting 1 turn counts (3 NADH, 1 FADH₂) as total per glucose.', 'HARD', true),
        ('11031111-0000-4000-8000-000000000104', '(a) Describe the three processes involved in urine formation in a human nephron, highlighting the role of PCT.
(b) Explain how ADH (Vasopressin) and the Renin-Angiotensin-Aldosterone System (RAAS) restore low blood pressure / GFR.', NULL, NULL, 'LA', 'Biology', 'Excretory Products & Elimination', 5, '(a) 1. Glomerular Filtration (Ultrafiltration): Non-selective filtration across 3 layers (endothelium, podocytes with filtration slits, basement membrane) producing ~125 mL/min GFR (180 L/day).
2. Reabsorption: Nearly 99% filtrate reabsorbed; PCT lined by cuboidal brush-border epithelium reabsorbs almost all essential nutrients (100% glucose/amino acids) and 70–80% electrolytes and water.
3. Tubular Secretion: PCT, DCT and collecting duct secrete H⁺, K⁺ and NH₃ into filtrate to maintain ionic and acid-base pH balance.
(b) Low blood volume activates osmoreceptors -> ADH increases water reabsorption from DCT/collecting duct. Low GFR triggers JG cells to release Renin -> Angiotensinogen -> Angiotensin II (vasoconstrictor + stimulates Adrenal cortex to release Aldosterone for Na⁺/water reabsorption in DCT), raising BP and GFR.', '(a) Ultrafiltration + PCT 70-80% reabsorption + Secretion [3 Marks] | (b) ADH water reabsorption + JGA Renin/Angiotensin II/Aldosterone pathway [2 Marks]', NULL, 'Examiner Tip: Always mention Juxtaglomerular Apparatus (JGA) and podocytes/filtration slits. | Common Pitfall: Confusing Aldosterone (Na⁺ reabsorption) with ADH (water permeability).', 'HARD', true),
        ('11031111-0000-4000-8000-000000000105', '(a) List the salient features of the Watson-Crick B-DNA double helix model.
(b) Explain how temperature, pH, and substrate concentration affect enzyme catalytic activity (with V_max and K_m concept).', NULL, NULL, 'LA', 'Biology', 'Biomolecules', 5, '(a) 1. Two polynucleotide chains coiled in a right-handed helix in antiparallel polarity (5''→3'' and 3''→5'').
2. Sugar-phosphate forms outer backbone; nitrogenous bases project inward perpendicular to axis.
3. Complementary base pairing via H-bonds: A=T (2 H-bonds), G≡C (3 H-bonds).
4. Pitch = 3.4 nm (34 Å) with 10 base pairs per turn (0.34 nm rise per bp).
(b) 1. Temperature & pH: Enzymes show peak activity at optimum temperature and optimum pH (bell-shaped curve); low temperature preserves enzyme in inactive state, while high temperature denatures tertiary protein structure.
2. Substrate concentration: Rate rises initially with [S] until all active sites saturate at V_max; K_m is substrate concentration giving ½ V_max.', '(a) Antiparallel strands, A=T/G≡C H-bonds, 3.4 nm pitch / 10 bp [2.5 Marks] | (b) Optimum T/pH denaturation + saturation at V_max [2.5 Marks]', NULL, 'Examiner Tip: Notice B-DNA pitch = 3.4 nm (34 Å), spacing = 0.34 nm (3.4 Å), rotation = 36° per bp. | Common Pitfall: Confusing covalent phosphodiester backbone bonds with hydrogen base-pair bonds.', 'HARD', true),
        ('11031111-0000-4000-8000-000000000106', 'In a standard electrocardiogram (ECG), the QRS complex represents:', '{"A":"Depolarisation of the atria","B":"Depolarisation of the ventricles initiating ventricular contraction","C":"Repolarisation of the ventricles","D":"Joint diastole"}'::jsonb, 'B', 'MCQ', 'Biology', 'Body Fluids & Circulation', 1, 'Option (B) is correct. P-wave = atrial depolarisation; QRS complex = ventricular depolarisation; T-wave = ventricular repolarisation.', 'QRS complex = ventricular depolarisation [1 Mark]', NULL, 'Examiner Tip: Counting QRS complexes in a given duration gives the heart beat rate. | Common Pitfall: Confusing QRS with ventricular repolarisation (T-wave).', 'EASY', true),
        ('11031111-0000-4000-8000-000000000107', 'Which two hormones are synthesised by the hypothalamus and transported axonally to the posterior pituitary (neurohypophysis) for storage and release?', '{"A":"GH and Prolactin","B":"TSH and ACTH","C":"Oxytocin and Vasopressin (ADH)","D":"Insulin and Glucagon"}'::jsonb, 'C', 'MCQ', 'Biology', 'Chemical Coordination', 1, 'Option (C) is correct. Oxytocin and Vasopressin (ADH) are synthesised in hypothalamic neurosecretory cells and stored/released by the posterior pituitary.', 'Identify Oxytocin and Vasopressin (ADH) [1 Mark]', NULL, 'Examiner Tip: Posterior pituitary does NOT synthesise these two hormones — it only stores and releases them! | Common Pitfall: Thinking posterior pituitary synthesises Oxytocin itself.', 'EASY', true),
        ('11031111-0000-4000-8000-000000000108', 'Distinguish between Diabetes Mellitus and Diabetes Insipidus based on the deficient hormone and urinary symptom.', NULL, NULL, 'VSA', 'Biology', 'Chemical Coordination', 2, '1. Diabetes Mellitus: Caused by hyposecretion/deficiency of Insulin from pancreatic β-cells -> hyperglycaemia, glycosuria (loss of glucose in urine) and ketone bodies.
2. Diabetes Insipidus: Caused by hyposecretion of Vasopressin (ADH) from posterior pituitary -> inability of distal nephrons to reabsorb water, causing excessive dilute urination (diuresis) without sugar.', 'Insulin deficiency + glucose in urine (Mellitus) [1 Mark] | ADH deficiency + water loss without glucose (Insipidus) [1 Mark]', NULL, 'Examiner Tip: Key distinction: Sugar present in Mellitus; Pure water loss in Insipidus. | Common Pitfall: Linking Diabetes Insipidus to insulin.', 'MEDIUM', true)
