        INSERT INTO learn_questions (id, question_text, options_json, correct_answer, question_type, subject, chapter, marks, model_answer, marking_scheme_json, case_passage, explanation, difficulty, is_verified)
        VALUES
        ('11031111-0000-4000-8000-000000000001', 'Binomial nomenclature system was formally introduced by:', '{"A":"Ernst Mayr","B":"Carolus Linnaeus","C":"R.H. Whittaker","D":"Aristotle"}'::jsonb, 'B', 'MCQ', 'Biology', 'The Living World', 1, 'Linnaeus in Systema Naturae / Species Plantarum.', NULL, NULL, 'Linnaeus in Systema Naturae / Species Plantarum.', 'EASY', true),
        ('11031111-0000-4000-8000-000000000002', 'Correct sequence of taxonomic categories in descending hierarchy is:', '{"A":"Kingdom -> Phylum -> Class -> Order -> Family -> Genus -> Species","B":"Kingdom -> Order -> Class -> Phylum","C":"Species -> Genus -> Family","D":"Division -> Class -> Phylum"}'::jsonb, 'A', 'MCQ', 'Biology', 'The Living World', 1, 'Standard 7 obligate categories.', NULL, NULL, 'Standard 7 obligate categories.', 'EASY', true),
        ('11031111-0000-4000-8000-000000000003', 'In Mangifera indica Linn., what does "Linn." denote?', '{"A":"Latin origin","B":"Linnaeus first described the species","C":"Leaf type","D":"Locality"}'::jsonb, 'B', 'MCQ', 'Biology', 'The Living World', 1, 'Author citation in Roman font.', NULL, NULL, 'Author citation in Roman font.', 'EASY', true),
        ('11031111-0000-4000-8000-000000000004', 'As we go higher from Species to Kingdom, the number of common characteristics:', '{"A":"Increases","B":"Decreases","C":"Remains constant","D":"Doubles"}'::jsonb, 'B', 'MCQ', 'Biology', 'The Living World', 1, 'Higher taxa share fewer specific traits.', NULL, NULL, 'Higher taxa share fewer specific traits.', 'EASY', true),
        ('11031111-0000-4000-8000-000000000005', 'Botanical gardens serve primarily as:', '{"A":"Dead specimen dryers","B":"Ex-situ conservation & living reference collections for identification","C":"Zoo enclosures","D":"Fossil museums"}'::jsonb, 'B', 'MCQ', 'Biology', 'The Living World', 1, 'Kew, Howrah IBG, Lucknow NBRI house living labelled plants.', NULL, NULL, 'Kew, Howrah IBG, Lucknow NBRI house living labelled plants.', 'EASY', true),
        ('11031111-0000-4000-8000-000000000006', 'Assertion (A): Scientific names are printed in italics (or underlined separately when handwritten).
        INSERT INTO learn_questions (id, question_text, options_json, correct_answer, question_type, subject, chapter, marks, model_answer, marking_scheme_json, case_passage, explanation, difficulty, is_verified)
        VALUES
        ('11031111-0000-4000-8000-0000000000c9', 'Describe the ultrastructure of Thick (Myosin) and Thin (Actin) contractile proteins.', NULL, NULL, 'SA', 'Biology', 'Locomotion and Movement', 3, 'Thin filament: two helically wound F-actin (G-actin polymer) chains + two tropomyosin strands + troponin trimer masking binding sites. Thick filament: polymerised meromyosins (HMM globular head with ATPase & actin-binding sites + short arm; LMM tail).', 'Actin (1.5M) + Myosin HMM/LMM (1.5M)', NULL, 'Thin filament: two helically wound F-actin (G-actin polymer) chains + two tropomyosin strands + troponin trimer masking binding sites. Thick filament: polymerised meromyosins (HMM globular head with ATPase & actin-binding sites + short arm; LMM tail).', 'MEDIUM', true),
        ('11031111-0000-4000-8000-0000000000ca', 'Classify the three structural types of Joints in humans with one anatomical example each.', NULL, NULL, 'SA', 'Biology', 'Locomotion and Movement', 3, 'Fibrous/Immovable (skull sutures), Cartilaginous/Slightly movable (adjacent vertebrae discs), Synovial/Freely movable fluid-filled cavity (hinge knee, pivot atlas-axis, gliding carpals, saddle thumb metacarpal).', '3 × 1M', NULL, 'Fibrous/Immovable (skull sutures), Cartilaginous/Slightly movable (adjacent vertebrae discs), Synovial/Freely movable fluid-filled cavity (hinge knee, pivot atlas-axis, gliding carpals, saddle thumb metacarpal).', 'MEDIUM', true),
        ('11031111-0000-4000-8000-0000000000cb', 'Explain the Sliding Filament Theory of muscle contraction step-by-step from arrival of neural signal at Motor End Plate (Acetylcholine release, Ca²⁺ release from sarcoplasmic reticulum, cross-bridge formation & ATP hydrolysis, power stroke, detachment & relaxation).', NULL, NULL, 'LA', 'Biology', 'Locomotion and Movement', 5, 'Neural signal -> ACh released -> sarcolemma action potential -> Ca²⁺ released from SR -> binds Troponin -> uncovers Actin active site -> Myosin head hydrolyses ATP & forms cross-bridge -> pulls actin toward M-line (I-band & H-zone shrink, Z-lines move closer) -> fresh ATP detaches head -> relaxation when Ca²⁺ pumped back into SR.', '5 steps cleanly ordered (5M)', NULL, 'Neural signal -> ACh released -> sarcolemma action potential -> Ca²⁺ released from SR -> binds Troponin -> uncovers Actin active site -> Myosin head hydrolyses ATP & forms cross-bridge -> pulls actin toward M-line (I-band & H-zone shrink, Z-lines move closer) -> fresh ATP detaches head -> relaxation when Ca²⁺ pumped back into SR.', 'HARD', true),
        ('11031111-0000-4000-8000-0000000000cc', '(i) Name the pelvic girdle cavity where femur head articulates, and pectoral girdle cavity for humerus head. (ii) What causes Tetany and Osteoporosis? (iii) Identify the single U-shaped bone at base of buccal cavity. (iv) How many cervical vertebrae do almost all mammals (including humans) have?', NULL, NULL, 'CASE', 'Biology', 'Locomotion and Movement', 4, '(i) Acetabulum (pelvic) and Glenoid cavity (pectoral). (ii) Tetany: rapid muscle spasms due to low Ca²⁺ in body fluids; Osteoporosis: age-related bone mass loss & fracture risk due to lower oestrogen. (iii) Hyoid bone. (iv) 7 cervical vertebrae.', '4 × 1M = 4M', 'Sports physiologists study EMG traces, bone mineral density, and fast-twitch vs slow-twitch muscle fibres across marathoners and sprinters.', '(i) Acetabulum (pelvic) and Glenoid cavity (pectoral). (ii) Tetany: rapid muscle spasms due to low Ca²⁺ in body fluids; Osteoporosis: age-related bone mass loss & fracture risk due to lower oestrogen. (iii) Hyoid bone. (iv) 7 cervical vertebrae.', 'HARD', true),
        ('11031111-0000-4000-8000-0000000000cd', 'During resting membrane potential of an axon, the axoplasm has high concentration of:', '{"A":"Na⁺ and positive net charge","B":"K⁺ ions and negatively charged proteins (resting potential ≈ -70 mV)","C":"Ca²⁺ only","D":"Cl⁻ only"}'::jsonb, 'B', 'MCQ', 'Biology', 'Neural Control and Coordination', 1, 'Na⁺/K⁺ pump exports 3 Na⁺ for 2 K⁺ keeping inside negative.', NULL, NULL, 'Na⁺/K⁺ pump exports 3 Na⁺ for 2 K⁺ keeping inside negative.', 'EASY', true),
        ('11031111-0000-4000-8000-0000000000ce', 'Saltatory conduction (jumping of nerve impulse from Node of Ranvier to Node of Ranvier) occurs in:', '{"A":"Unmyelinated axons","B":"Myelinated nerve fibres wrapped by Schwann cells","C":"Dendrites only","D":"Cardiac muscle"}'::jsonb, 'B', 'MCQ', 'Biology', 'Neural Control and Coordination', 1, 'Myelin sheath insulates internodes, speeding conduction & saving ATP.', NULL, NULL, 'Myelin sheath insulates internodes, speeding conduction & saving ATP.', 'EASY', true),
        ('11031111-0000-4000-8000-0000000000cf', 'Which brain part links the two cerebral hemispheres together via a thick tract of nerve fibres?', '{"A":"Pons","B":"Corpus callosum","C":"Thalamus","D":"Medulla"}'::jsonb, 'B', 'MCQ', 'Biology', 'Neural Control and Coordination', 1, 'Corpus callosum integrates left & right hemispheres.', NULL, NULL, 'Corpus callosum integrates left & right hemispheres.', 'EASY', true),
        ('11031111-0000-4000-8000-0000000000d0', 'The Limbic System (amygdala, hippocampus + inner cerebral lobes) along with Hypothalamus regulates:', '{"A":"Voluntary balance only","B":"Sexual behaviour, expression of emotional reactions (rage, fear, pleasure), and motivation","C":"Heart rate only","D":"Auditory reflex"}'::jsonb, 'B', 'MCQ', 'Biology', 'Neural Control and Coordination', 1, 'Emotional and autonomic drive hub.', NULL, NULL, 'Emotional and autonomic drive hub.', 'EASY', true),
        ('11031111-0000-4000-8000-0000000000d1', 'Which cells in the brain produce myelin sheath around CNS axons vs PNS axons?', '{"A":"Schwann cells in CNS","B":"Oligodendrocytes in CNS and Schwann cells in PNS","C":"Astrocytes only","D":"Microglia"}'::jsonb, 'B', 'MCQ', 'Biology', 'Neural Control and Coordination', 1, 'Schwann cells myelinate PNS; Oligodendrocytes myelinate CNS.', NULL, NULL, 'Schwann cells myelinate PNS; Oligodendrocytes myelinate CNS.', 'EASY', true),
        ('11031111-0000-4000-8000-0000000000d2', 'Assertion (A): Electrical synapses transmit impulses faster than chemical synapses, yet chemical synapses dominate the human nervous system.
